-- VEDU curated catalog 2026.11.2. Originals and AI-assisted workbooks have distinct provenance.
-- Repeatable, one-time per revision. Retired courses are soft-deleted; learner history is retained.
BEGIN;
CREATE TABLE IF NOT EXISTS lms.catalog_revisions(revision text PRIMARY KEY,applied_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS lms.curated_courses(course_key text PRIMARY KEY,course_id bigint UNIQUE REFERENCES lms.courses,revision text NOT NULL);
CREATE TABLE IF NOT EXISTS lms.catalog_retirements(course_id bigint PRIMARY KEY REFERENCES lms.courses,previous_teacher_id bigint,previous_status text,retired_at timestamptz DEFAULT now());
DO $curated$
DECLARE c jsonb; l jsonb; r jsonb; q jsonb; a jsonb; t jsonb; cid bigint; lid bigint; qid bigint; rid bigint; sid bigint; tid bigint; adminid bigint; n int; pos int; ai int; rotation int; selected bigint[]='{}'; used bigint[]; prev bigint; teacherids bigint[]='{}'; idx int=0;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('vedu-curated-2026.11'));
IF EXISTS(SELECT 1 FROM lms.catalog_revisions WHERE revision='2026.11.2') THEN RETURN; END IF;
SELECT user_id INTO adminid FROM auth.users WHERE role='ADMIN' ORDER BY user_id LIMIT 1;
FOR t IN SELECT value FROM jsonb_array_elements('[{"username":"gv.minhan","name":"Nguyễn Minh An","hash":"$2b$10$wLN0etsBA4rrTiEr.vsq5OmVMKP0AqYO2cVEJAWAwaB2PL8wMj8/u"},{"username":"gv.thanhha","name":"Trần Thanh Hà","hash":"$2b$10$98Lo.IN3HNg0IsHfC4/LGenwDtB6q9y7kh539Aj9m38q/00AgqDye"},{"username":"gv.quanghuy","name":"Lê Quang Huy","hash":"$2b$10$UwVwD9iWWbXe6hYucXABNOuZCRGVf.yhoG1kBUMeaCPM9Vdm.NYCK"},{"username":"gv.ngocmai","name":"Phạm Ngọc Mai","hash":"$2b$10$0SU4hHojcfT13UsiHGJBb.eBLR9KxIJEsAa1zXsEDpncVag.svb6a"}]'::jsonb) LOOP
 INSERT INTO auth.users(full_name,username,email,password_hash,role,is_active,is_test_account)
 VALUES(t->>'name',t->>'username',(t->>'username')||'@vedu.local',t->>'hash','TEACHER',true,true) ON CONFLICT DO NOTHING;
 SELECT user_id INTO tid FROM auth.users WHERE username=t->>'username' AND role='TEACHER';
 IF tid IS NULL THEN RAISE EXCEPTION 'Instructor username conflict'; END IF;
 teacherids=array_append(teacherids,tid);
END LOOP;
FOR c IN SELECT value FROM jsonb_array_elements('[{"key":"dsa","name":"Cấu trúc dữ liệu và giải thuật","topic":"Lập trình & Phát triển phần mềm","marker":"[VEDU-CURATED-v202611:dsa]","summary":"Khóa tự học Cấu trúc dữ liệu và giải thuật theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Kiến thức CNTT nền tảng và máy tính để thực hành.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Cấu trúc dữ liệu và giải thuật theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nKiến thức CNTT nền tảng và máy tính để thực hành.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 10 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tổng quan cấu trúc dữ liệu và giải thuật\n2. Phân tích độ phức tạp\n3. Đệ quy\n4. Mảng và danh sách tuyến tính\n5. Danh sách liên kết\n6. Ngăn xếp (Stack)\n7. Hàng đợi (Queue)\n8. Cây nhị phân\n9. Tìm kiếm\n10. Sắp xếp\n\nNGUỒN\nVEDU_CTDLGT.zip\n\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/dsa/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"}]},{"title":"01 · Tổng quan cấu trúc dữ liệu và giải thuật","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Giải thuật là gì?\n\n2. Cấu trúc dữ liệu dùng để làm gì?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=kQyEg0p5K1g&list=PLNz_ygAlIfQM"}]},{"title":"02 · Phân tích độ phức tạp","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Vòng lặp chạy n lần với thao tác O(1) có độ phức tạp nào?\n\n2. Hai vòng lặp lồng nhau, mỗi vòng n lần thường có độ phức tạp nào?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=-AGbOe6tZFE&list=PLNz_ygAlIfQM&index=2"}]},{"title":"03 · Đệ quy","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Trong đệ quy, điều kiện dừng nhằm mục đích gì?\n\n2. 5! bằng bao nhiêu?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=jsJBCEp-zVY&list=PLNz_ygAlIfQM&index=3"}]},{"title":"04 · Mảng và danh sách tuyến tính","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Ưu điểm chính của mảng là gì?\n\n2. Mảng 0-based gồm 6 phần tử có chỉ số cuối là bao nhiêu?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=rI__qzRXKpQ&list=PLNz_ygAlIfQM&index=4"}]},{"title":"05 · Danh sách liên kết","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Một nút của danh sách liên kết đơn thường chứa gì?\n\n2. Ký hiệu next = null ở nút cuối biểu thị gì?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=FfcXdp_KS98&list=PLNz_ygAlIfQM&index=5"}]},{"title":"06 · Ngăn xếp (Stack)","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Stack tuân theo nguyên tắc nào?\n\n2. Thao tác thêm phần tử vào stack gọi là gì?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=PMs-IUjZoag&list=PLNz_ygAlIfQM&index=6"}]},{"title":"07 · Hàng đợi (Queue)","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Queue tuân theo nguyên tắc nào?\n\n2. Thao tác thêm phần tử vào queue gọi là gì?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=9yytlPu-DKM&list=PLNz_ygAlIfQM&index=7"}]},{"title":"08 · Cây nhị phân","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Mỗi nút của cây nhị phân có tối đa bao nhiêu con?\n\n2. Nút không có con gọi là gì?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=hrHEr1XLFbE&list=PLNz_ygAlIfQM&index=8"}]},{"title":"09 · Tìm kiếm","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Tìm kiếm nhị phân cần điều kiện nào?\n\n2. Tìm kiếm tuyến tính trong trường hợp xấu nhất là?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/09.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=DX5TkbwDi1E&list=PLNz_ygAlIfQM&index=9"}]},{"title":"10 · Sắp xếp","content":"Đọc giáo trình Đỗ Xuân Lôi trong mục Tài liệu; đối chiếu thuật toán bằng ví dụ và kiểm thử dữ liệu biên.\n\nBÀI TẬP NHỎ\n\n1. Bubble sort thường có độ phức tạp trường hợp xấu nhất nào?\n\n2. Sau một lượt selection sort tăng dần, phần tử nào được đưa về đầu đoạn chưa sắp xếp?\n\nTHỰC HÀNH\n\nCài đặt ví dụ theo chủ đề bài học, tự tạo ít nhất 5 ca kiểm thử gồm rỗng, một phần tử, dữ liệu trùng và trường hợp biên; ghi đầu vào, kết quả kỳ vọng và kết quả thực.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/dsa/10.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e873cea6-8246-f931-f0a9-6f34231a3d7c.pdf"},{"title":"Sach_CTDLGT_DoXuanLoi.pdf","type":"PDF","url":"vedu-file:6aa1c15f-3864-6cbf-64b0-3e317fe45b70.pdf"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=TkoCrp8golw&list=PLNz_ygAlIfQM&index=10"}]}],"questions":[{"text":"Giải thuật là gì?","options":["Một dãy bước hữu hạn để giải quyết bài toán","Một loại phần cứng","Một ngôn ngữ lập trình","Một kiểu dữ liệu"],"correct":0},{"text":"Cấu trúc dữ liệu dùng để làm gì?","options":["Lưu trữ và tổ chức dữ liệu để xử lý","Chỉ vẽ giao diện","Thay thế hệ điều hành","Tăng tốc mạng"],"correct":0},{"text":"Tính chất cần có của một giải thuật là gì?","options":["Có tính xác định và dừng","Luôn dùng đệ quy","Luôn cần đồ thị","Không có đầu vào"],"correct":0},{"text":"Vòng lặp chạy n lần với thao tác O(1) có độ phức tạp nào?","options":["O(1)","O(log n)","O(n)","O(n²)"],"correct":2},{"text":"Hai vòng lặp lồng nhau, mỗi vòng n lần thường có độ phức tạp nào?","options":["O(n²)","O(log n)","O(n)","O(1)"],"correct":0},{"text":"Ký hiệu Big-O thường mô tả điều gì?","options":["Cận trên tiệm cận của mức tăng tài nguyên","Kích thước file","Số dòng code chính xác","Tốc độ mạng"],"correct":0},{"text":"Trong đệ quy, điều kiện dừng nhằm mục đích gì?","options":["Tránh gọi vô hạn","Tăng bộ nhớ","Xóa biến","Sắp xếp dữ liệu"],"correct":0},{"text":"5! bằng bao nhiêu?","options":["25","60","120","720"],"correct":2},{"text":"Đệ quy trực tiếp là khi nào?","options":["Hàm gọi lại chính nó","Hai hàm không liên quan","Chỉ có vòng for","Hàm không có tham số"],"correct":0},{"text":"Ưu điểm chính của mảng là gì?","options":["Truy cập theo chỉ số nhanh","Chèn đầu luôn O(1)","Không cần bộ nhớ","Kích thước luôn vô hạn"],"correct":0},{"text":"Mảng 0-based gồm 6 phần tử có chỉ số cuối là bao nhiêu?","options":["4","5","6","7"],"correct":1},{"text":"Trong mảng liên tiếp, chèn đầu có thể cần thao tác gì?","options":["Dịch các phần tử","Chỉ đổi con trỏ head","Không làm gì","Đổi cấu trúc cây"],"correct":0},{"text":"Một nút của danh sách liên kết đơn thường chứa gì?","options":["Dữ liệu và liên kết đến nút sau","Chỉ địa chỉ cuối mảng","Hai cây con","Một hàng đợi"],"correct":0},{"text":"Ký hiệu next = null ở nút cuối biểu thị gì?","options":["Không có nút tiếp theo","Danh sách luôn rỗng","Nút đầu","Vòng lặp"],"correct":0},{"text":"Thêm nút vào đầu danh sách liên kết đơn, đã có head, thường mất bao lâu?","options":["O(1)","O(n)","O(n²)","O(log n)"],"correct":0},{"text":"Stack tuân theo nguyên tắc nào?","options":["FIFO","LIFO","Ngẫu nhiên","Ưu tiên"],"correct":1},{"text":"Thao tác thêm phần tử vào stack gọi là gì?","options":["Push","Pop","Dequeue","Sort"],"correct":0},{"text":"Push A, push B, pop: phần tử được lấy ra là gì?","options":["A","B","C","Không có"],"correct":1},{"text":"Queue tuân theo nguyên tắc nào?","options":["LIFO","FIFO","Đệ quy","Sắp xếp"],"correct":1},{"text":"Thao tác thêm phần tử vào queue gọi là gì?","options":["Enqueue","Pop","Peek stack","Rotate tree"],"correct":0}]},{"key":"deep-learning","name":"Học sâu","topic":"Khoa học dữ liệu & AI","marker":"[VEDU-CURATED-v202611:deep-learning]","summary":"Khóa tự học Học sâu theo học liệu nhóm cung cấp, gồm 5 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Sinh viên đã học Học máy, học song hành Thực hành Học sâu","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Học sâu theo học liệu nhóm cung cấp, gồm 5 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nSinh viên đã học Học máy, học song hành Thực hành Học sâu\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 5 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tổng quan\n2. ANN và lan truyền ngược\n3. Huấn luyện mạng nơron\n4. CNN và ResNet\n5. RNN, BPTT, LSTM và GRU\n\nNGUỒN\nVEDU_Deep Learning.zip\nDeep Learning dành cho người mới bắt đầu https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB\nHướng dẫn lập trình với TensorFlow https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM\nSimon J.D. Prince - Understanding Deep Learning https://udlbook.github.io/udlbook/\nTensorFlow - Working with RNNs https://www.tensorflow.org/guide/keras/working_with_rnns\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/deep-learning/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:130a0369-0c9f-f80a-70e6-8bd49861b5cf.pdf"},{"title":"01 - Chap 1- Tong quan.pdf","type":"PDF","url":"vedu-file:8d16249c-8f0c-9db3-22b8-e4d89f570d6b.pdf"},{"title":"02 - Chap 2 - Mang neural nhan tao - ann.pdf","type":"PDF","url":"vedu-file:c2441b8a-8693-4cba-fae0-25f143383b21.pdf"},{"title":"03 - Chap 3- Huan luyen mang noron.pdf","type":"PDF","url":"vedu-file:c1833bb7-4085-e82b-3ba9-d4b07753c60b.pdf"},{"title":"04 - Chap 4- CNN.pdf","type":"PDF","url":"vedu-file:bc69c51a-50b7-3625-5f73-003e5177d2d1.pdf"},{"title":"54_Hoc sau (Mau9b_KHDL).pdf","type":"PDF","url":"vedu-file:256b432d-86a1-f6ac-536a-53d24f5d83f8.pdf"},{"title":"Tối ưu huấn luyện mạng NN (TKT).pdf","type":"PDF","url":"vedu-file:bfdec83b-e18f-92f2-282a-e5e84dc0c880.pdf"}]},{"title":"01 · Tổng quan","content":"BÀI TẬP NHỎ\n\n1. Phân biệt AI, machine learning và deep learning; nêu hai tình huống không cần mạng sâu.\n\n2. Dữ liệu 1.000 ảnh chia 70/15/15: tính số ảnh mỗi tập. Nếu nhiều ảnh thuộc cùng một người, nên chia theo ảnh hay theo người? Vì sao?\n\nTHỰC HÀNH\n\nThiết kế bài toán phân loại ảnh sản phẩm: mô tả đầu vào/đầu ra, nhãn, cách thu thập, chia tập theo nguồn, baseline, metric và giới hạn. Nộp bản thiết kế 2 trang; chưa cần huấn luyện.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:130a0369-0c9f-f80a-70e6-8bd49861b5cf.pdf"},{"title":"01 - Chap 1- Tong quan.pdf","type":"PDF","url":"vedu-file:8d16249c-8f0c-9db3-22b8-e4d89f570d6b.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Simon J.D. Prince - Understanding Deep Learning","type":"LINK","url":"https://udlbook.github.io/udlbook/"},{"title":"TensorFlow - Working with RNNs","type":"LINK","url":"https://www.tensorflow.org/guide/keras/working_with_rnns"}]},{"title":"02 · ANN và lan truyền ngược","content":"BÀI TẬP NHỎ\n\n1. Mạng Dense 2→3→1 có bias ở hai lớp: tính số tham số. Giải thích vì sao một perceptron tuyến tính không biểu diễn XOR.\n\n2. Neuron sigmoid với x=2, w=0, b=0, y=1; dùng binary crossentropy. Tính dự đoán, dL/dw, dL/db; cập nhật SGD learning rate 0,1.\n\nTHỰC HÀNH\n\nVẽ MLP 2→3→1, ghi kích thước ma trận. Với một mẫu tự chọn, trình bày forward, loss và chain rule cho ít nhất một trọng số. Kiểm tra đạo hàm bằng sai phân trung tâm (epsilon 1e-5); báo sai lệch thực tính. Đây là bài cá nhân mẫu sau chương 2, không phải đề chính thức.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:130a0369-0c9f-f80a-70e6-8bd49861b5cf.pdf"},{"title":"02 - Chap 2 - Mang neural nhan tao - ann.pdf","type":"PDF","url":"vedu-file:c2441b8a-8693-4cba-fae0-25f143383b21.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Simon J.D. Prince - Understanding Deep Learning","type":"LINK","url":"https://udlbook.github.io/udlbook/"},{"title":"TensorFlow - Working with RNNs","type":"LINK","url":"https://www.tensorflow.org/guide/keras/working_with_rnns"}]},{"title":"03 · Huấn luyện mạng nơron","content":"BÀI TẬP NHỎ\n\n1. Loss train giảm từ 0,8 xuống 0,1 nhưng validation giảm tới 0,4 rồi tăng 0,7: nhận xét và đề xuất hai cách xử lý.\n\n2. Với w=2, gradient=0,3 và learning rate=0,1, tính một bước SGD. Phân biệt learning-rate schedule, early stopping và optimizer.\n\nTHỰC HÀNH\n\nLập kế hoạch so sánh SGD/Adam trên cùng ANN và split; kiểm soát batch size, ngân sách, seed. Chọn ít nhất hai yếu tố trong chuẩn hóa, khởi tạo, regularization, augmentation, transfer learning hoặc ensemble; giải thích tác động và thiết kế ablation. Nộp kế hoạch, bảng chạy thực nếu có, và kết luận không vượt quá bằng chứng.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:130a0369-0c9f-f80a-70e6-8bd49861b5cf.pdf"},{"title":"03 - Chap 3- Huan luyen mang noron.pdf","type":"PDF","url":"vedu-file:c1833bb7-4085-e82b-3ba9-d4b07753c60b.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Simon J.D. Prince - Understanding Deep Learning","type":"LINK","url":"https://udlbook.github.io/udlbook/"},{"title":"TensorFlow - Working with RNNs","type":"LINK","url":"https://www.tensorflow.org/guide/keras/working_with_rnns"}]},{"title":"04 · CNN và ResNet","content":"BÀI TẬP NHỎ\n\n1. Đầu vào 32×32×3, convolution 16 filters 3×3, stride1, padding valid, có bias; tính output và tham số. Qua maxpool2×2 stride2 cho shape nào?\n\n2. Residual block y=F(x)+x: khi nào cộng trực tiếp được? Nêu cách xử lý nếu số kênh hoặc kích thước không gian khác.\n\nTHỰC HÀNH\n\nVẽ CNN nhỏ và một residual block, ghi shape từng tầng. Cài đặt block hoặc viết mã giả đầy đủ với shortcut projection khi cần; kiểm tra đầu vào (2,32,32,16) và đầu ra mong đợi. So sánh CNN thường và mạng có shortcut trong một kế hoạch thực nghiệm công bằng. Nếu đã chạy, nộp log thật; nếu chỉ thiết kế, ghi rõ.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:130a0369-0c9f-f80a-70e6-8bd49861b5cf.pdf"},{"title":"04 - Chap 4- CNN.pdf","type":"PDF","url":"vedu-file:bc69c51a-50b7-3625-5f73-003e5177d2d1.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Simon J.D. Prince - Understanding Deep Learning","type":"LINK","url":"https://udlbook.github.io/udlbook/"},{"title":"TensorFlow - Working with RNNs","type":"LINK","url":"https://www.tensorflow.org/guide/keras/working_with_rnns"}]},{"title":"05 · RNN, BPTT, LSTM và GRU","content":"BÀI TẬP NHỎ\n\n1. Với h_t=tanh(0,5h_(t−1)+x_t), h_0=0, x_1=1, x_2=0, tính h_1,h_2 đến 4 chữ số. Giải thích trọng số dùng chung theo thời gian.\n\n2. SimpleRNN có d=8 features, h=16 hidden units và một vector bias: tính tham số. Nêu khác biệt trạng thái của LSTM và GRU.\n\nTHỰC HÀNH\n\nThiết kế dự báo một bước cho chuỗi 200 quan sát, dùng 10 quan sát quá khứ. Dành mốc 1–140 cho train, 141–170 validation, 171–200 test theo thời điểm target; chỉ fit scaler trên train. Vẽ sơ đồ unroll và đường truyền gradient qua 3 bước. So sánh RNN/LSTM/GRU, đề xuất xử lý gradient và tiêu chí đánh giá MAE. Không dùng dữ liệu tương lai trong cửa sổ đầu vào.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:130a0369-0c9f-f80a-70e6-8bd49861b5cf.pdf"},{"title":"01 - Chap 1- Tong quan.pdf","type":"PDF","url":"vedu-file:8d16249c-8f0c-9db3-22b8-e4d89f570d6b.pdf"},{"title":"02 - Chap 2 - Mang neural nhan tao - ann.pdf","type":"PDF","url":"vedu-file:c2441b8a-8693-4cba-fae0-25f143383b21.pdf"},{"title":"03 - Chap 3- Huan luyen mang noron.pdf","type":"PDF","url":"vedu-file:c1833bb7-4085-e82b-3ba9-d4b07753c60b.pdf"},{"title":"04 - Chap 4- CNN.pdf","type":"PDF","url":"vedu-file:bc69c51a-50b7-3625-5f73-003e5177d2d1.pdf"},{"title":"54_Hoc sau (Mau9b_KHDL).pdf","type":"PDF","url":"vedu-file:256b432d-86a1-f6ac-536a-53d24f5d83f8.pdf"},{"title":"Tối ưu huấn luyện mạng NN (TKT).pdf","type":"PDF","url":"vedu-file:bfdec83b-e18f-92f2-282a-e5e84dc0c880.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Simon J.D. Prince - Understanding Deep Learning","type":"LINK","url":"https://udlbook.github.io/udlbook/"},{"title":"TensorFlow - Working with RNNs","type":"LINK","url":"https://www.tensorflow.org/guide/keras/working_with_rnns"}]}],"questions":[{"text":"Chia train/validation/test nhằm mục đích gì?","options":["Học tham số, chọn cấu hình, rồi đánh giá trên tập giữ lại","Huấn luyện trên cả ba tập","Chỉ giảm số lượng ảnh","Bảo đảm accuracy đạt 100%"],"correct":0},{"text":"Dense có 4 đầu vào, 3 đầu ra và bias có bao nhiêu tham số?","options":["15","12","7","24"],"correct":0},{"text":"Vai trò của backpropagation là gì?","options":["Tính gradient theo quy tắc dây chuyền","Tự tạo thêm nhãn đúng","Thay thế hàm mất mát","Bảo đảm cực tiểu toàn cục"],"correct":0},{"text":"Loss train giảm nhưng loss validation tăng là dấu hiệu gì?","options":["Có thể đang overfit","Chắc chắn underfit","Validation phải dùng để cập nhật trọng số","Không cần xem thêm dữ liệu"],"correct":0},{"text":"Đặc điểm của convolution so với Dense trên ảnh?","options":["Chia sẻ trọng số và khai thác vùng lân cận","Mỗi ảnh phải có trọng số riêng","Luôn không có tham số","Không dùng được gradient"],"correct":0},{"text":"Với chuỗi thời gian, chia tập phù hợp nhất là gì?","options":["Giữ thứ tự thời gian và đánh giá trên giai đoạn sau","Trộn mọi thời điểm rồi fit trên test","Chọn test giống train","Chỉ dùng những chuỗi dự đoán đúng"],"correct":0},{"text":"Early stopping thường theo dõi tập nào?","options":["Validation","Test để cập nhật từng epoch","Toàn bộ dữ liệu trước khi chia","Không cần đo lường"],"correct":0},{"text":"So sánh hai mô hình công bằng cần gì?","options":["Cùng cách chia dữ liệu, metric và ngân sách được ghi rõ","Chọn test khác cho mỗi mô hình","Chỉ so số lớp","Chỉ báo lần chạy tốt nhất không ghi seed"],"correct":0}]},{"key":"data-mining","name":"Khai phá dữ liệu","topic":"Khoa học dữ liệu & AI","marker":"[VEDU-CURATED-v202611:data-mining]","summary":"Khóa tự học Khai phá dữ liệu theo học liệu nhóm cung cấp, gồm 5 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Kiến thức CNTT nền tảng và máy tính để thực hành.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Khai phá dữ liệu theo học liệu nhóm cung cấp, gồm 5 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nKiến thức CNTT nền tảng và máy tính để thực hành.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 5 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tổng quan và tiền xử lý\n2. Tập phổ biến và luật kết hợp\n3. Phân lớp dữ liệu\n4. Gom cụm dữ liệu\n5. Tương quan, kiểm định và hồi quy\n\nNGUỒN\nVEDU_KhaiPhaDuLieu.zip\nKhai thác dữ liệu (Course2025-HUIT) https://www.youtube.com/playlist?list=PLf5IPckgFwFXx4iupnopVRPflUGquequj\nĐề cương trong CTĐT CNTT2017 https://fit.huit.edu.vn/app_web/images/documents/n00ct/1-ctdt-nganh-cntt_nam-2017.pdf\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/data-mining/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:15f79700-667a-a693-45a9-804ca9602068.pdf"},{"title":"3 - Bai tap chuong 2 - Buoi 1.pdf","type":"PDF","url":"vedu-file:d38acb71-e020-452f-5e54-2248666baff0.pdf"},{"title":"BÀI KIỂM TRA 2.pdf","type":"PDF","url":"vedu-file:4d031ca8-2a46-f869-36a6-c4e67e305951.pdf"},{"title":"Chuong III_Phân lớp dữ liệu -31.pdf","type":"PDF","url":"vedu-file:6ca576f1-25af-c3df-b7ea-ca971761f6b6.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp (tiếp theo).pdf","type":"PDF","url":"vedu-file:828dda87-779f-8583-205b-3d05831043ce.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp.pdf","type":"PDF","url":"vedu-file:71db5cd1-c144-9ab9-ef77-18e1c76a9839.pdf"},{"title":"Chuong IV_Gom cụm dữ liệu.pdf","type":"PDF","url":"vedu-file:5282b5e1-9365-bdfe-f098-b7fe65ad70dc.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu (tiếp theo).pdf","type":"PDF","url":"vedu-file:fa89e432-fddd-01f8-d41d-37462202dc14.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu.pdf","type":"PDF","url":"vedu-file:4e91d7cf-9f46-4c59-5468-49329033a255.pdf"},{"title":"Chuong V_Phân tích tương quan và hồi quy.pdf","type":"PDF","url":"vedu-file:4fdb9f4c-2354-0c2f-4dd0-0b388fd559a1.pdf"},{"title":"KNN.xlsx","type":"SPREADSHEET","url":"/course-materials/batch-assets/b7dd7192-504f-8837-5052-f341905c68c4.xlsx"},{"title":"The first test.pdf","type":"PDF","url":"vedu-file:caa6fdff-8ec1-54be-321f-b6c55ae27017.pdf"}]},{"title":"01 · Tổng quan và tiền xử lý","content":"BÀI TẬP NHỎ\n\n1. Phân biệt phân lớp, hồi quy, gom cụm và luật kết hợp. Với mỗi loại, nêu đầu vào, đầu ra và một ví dụ.\n\n2. Dữ liệu tuổi [20,22,thiếu,26]: điền thiếu bằng trung bình phần quan sát, sau đó chuẩn hóa min-max. Trong mô hình dự đoán, thời điểm fit các phép biến đổi là khi nào?\n\nTHỰC HÀNH\n\nThiết kế quy trình KDD cho bài toán phân loại khách hàng phản hồi chiến dịch: xác định nhãn, dữ liệu có trước thời điểm dự đoán, làm sạch, chia tập, lựa chọn mô hình, metric và ứng dụng kết quả. Nộp sơ đồ và giải thích 2 trang. Không dùng thông tin chỉ xuất hiện sau phản hồi làm đầu vào.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/data-mining/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:15f79700-667a-a693-45a9-804ca9602068.pdf"},{"title":"3 - Bai tap chuong 2 - Buoi 1.pdf","type":"PDF","url":"vedu-file:d38acb71-e020-452f-5e54-2248666baff0.pdf"},{"title":"BÀI KIỂM TRA 2.pdf","type":"PDF","url":"vedu-file:4d031ca8-2a46-f869-36a6-c4e67e305951.pdf"},{"title":"Chuong III_Phân lớp dữ liệu -31.pdf","type":"PDF","url":"vedu-file:6ca576f1-25af-c3df-b7ea-ca971761f6b6.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp (tiếp theo).pdf","type":"PDF","url":"vedu-file:828dda87-779f-8583-205b-3d05831043ce.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp.pdf","type":"PDF","url":"vedu-file:71db5cd1-c144-9ab9-ef77-18e1c76a9839.pdf"},{"title":"Chuong IV_Gom cụm dữ liệu.pdf","type":"PDF","url":"vedu-file:5282b5e1-9365-bdfe-f098-b7fe65ad70dc.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu (tiếp theo).pdf","type":"PDF","url":"vedu-file:fa89e432-fddd-01f8-d41d-37462202dc14.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu.pdf","type":"PDF","url":"vedu-file:4e91d7cf-9f46-4c59-5468-49329033a255.pdf"},{"title":"Chuong V_Phân tích tương quan và hồi quy.pdf","type":"PDF","url":"vedu-file:4fdb9f4c-2354-0c2f-4dd0-0b388fd559a1.pdf"},{"title":"Khai thác dữ liệu (Course2025-HUIT)","type":"LINK","url":"https://www.youtube.com/playlist?list=PLf5IPckgFwFXx4iupnopVRPflUGquequj"},{"title":"Đề cương trong CTĐT CNTT2017","type":"LINK","url":"https://fit.huit.edu.vn/app_web/images/documents/n00ct/1-ctdt-nganh-cntt_nam-2017.pdf"}]},{"title":"02 · Tập phổ biến và luật kết hợp","content":"BÀI TẬP NHỎ\n\n1. Cho T1={A,B}, T2={A,C}, T3={A,B,C}, T4={B,C}, T5={A,B}. Tính support, confidence và lift của A→B.\n\n2. Với 8 giao dịch và minsup30%, số lần xuất hiện tối thiểu là bao nhiêu? Phân biệt tập phổ biến đóng với tập phổ biến tối đại.\n\nTHỰC HÀNH\n\nTrên 5 giao dịch ở bài nhỏ1, chạy Apriori với minsup40%, trình bày Ck và Lk; xác định tập đóng/tối đại. Sinh luật confidence≥70%. Dựng FP-tree với thứ tự tần suất giảm dần, hòa thì A trước B trước C; đối chiếu tập phổ biến thu được. Nộp bảng đếm và hình cây.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/data-mining/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:15f79700-667a-a693-45a9-804ca9602068.pdf"},{"title":"3 - Bai tap chuong 2 - Buoi 1.pdf","type":"PDF","url":"vedu-file:d38acb71-e020-452f-5e54-2248666baff0.pdf"},{"title":"BÀI KIỂM TRA 2.pdf","type":"PDF","url":"vedu-file:4d031ca8-2a46-f869-36a6-c4e67e305951.pdf"},{"title":"Chuong III_Phân lớp dữ liệu -31.pdf","type":"PDF","url":"vedu-file:6ca576f1-25af-c3df-b7ea-ca971761f6b6.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp (tiếp theo).pdf","type":"PDF","url":"vedu-file:828dda87-779f-8583-205b-3d05831043ce.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp.pdf","type":"PDF","url":"vedu-file:71db5cd1-c144-9ab9-ef77-18e1c76a9839.pdf"},{"title":"Chuong IV_Gom cụm dữ liệu.pdf","type":"PDF","url":"vedu-file:5282b5e1-9365-bdfe-f098-b7fe65ad70dc.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu (tiếp theo).pdf","type":"PDF","url":"vedu-file:fa89e432-fddd-01f8-d41d-37462202dc14.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu.pdf","type":"PDF","url":"vedu-file:4e91d7cf-9f46-4c59-5468-49329033a255.pdf"},{"title":"Chuong V_Phân tích tương quan và hồi quy.pdf","type":"PDF","url":"vedu-file:4fdb9f4c-2354-0c2f-4dd0-0b388fd559a1.pdf"},{"title":"Khai thác dữ liệu (Course2025-HUIT)","type":"LINK","url":"https://www.youtube.com/playlist?list=PLf5IPckgFwFXx4iupnopVRPflUGquequj"},{"title":"Đề cương trong CTĐT CNTT2017","type":"LINK","url":"https://fit.huit.edu.vn/app_web/images/documents/n00ct/1-ctdt-nganh-cntt_nam-2017.pdf"}]},{"title":"03 · Phân lớp dữ liệu","content":"BÀI TẬP NHỎ\n\n1. Tập nhãn gồm 4 Có,4 Không. Tính entropy cơ số2. Một thuộc tính chia thành hai nhánh thuần, mỗi nhánh4 mẫu: information gain bằng bao nhiêu?\n\n2. TP=18,FP=6,FN=2,TN=24: tính accuracy, precision, recall,F1 cho lớp dương. Nêu vì sao cần nhiều metric.\n\nTHỰC HÀNH\n\nDùng KNN.xlsx gốc làm bài minh họa: xác định cột đặc trưng và nhãn, không đưa tên khách hàng vào khoảng cách. Giải một truy vấn do bạn tự chọn với k=3, ghi quy tắc chuẩn hóa và xử lý hòa. Tiếp theo lập kế hoạch so sánh cây quyết định, Naive Bayes và KNN trên bộ dữ liệu đủ lớn; nêu cross-validation và chống rò rỉ. Không kết luận hiệu năng thực tế từ vài dòng dữ liệu minh họa.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/data-mining/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:15f79700-667a-a693-45a9-804ca9602068.pdf"},{"title":"3 - Bai tap chuong 2 - Buoi 1.pdf","type":"PDF","url":"vedu-file:d38acb71-e020-452f-5e54-2248666baff0.pdf"},{"title":"BÀI KIỂM TRA 2.pdf","type":"PDF","url":"vedu-file:4d031ca8-2a46-f869-36a6-c4e67e305951.pdf"},{"title":"Chuong III_Phân lớp dữ liệu -31.pdf","type":"PDF","url":"vedu-file:6ca576f1-25af-c3df-b7ea-ca971761f6b6.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp (tiếp theo).pdf","type":"PDF","url":"vedu-file:828dda87-779f-8583-205b-3d05831043ce.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp.pdf","type":"PDF","url":"vedu-file:71db5cd1-c144-9ab9-ef77-18e1c76a9839.pdf"},{"title":"Chuong IV_Gom cụm dữ liệu.pdf","type":"PDF","url":"vedu-file:5282b5e1-9365-bdfe-f098-b7fe65ad70dc.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu (tiếp theo).pdf","type":"PDF","url":"vedu-file:fa89e432-fddd-01f8-d41d-37462202dc14.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu.pdf","type":"PDF","url":"vedu-file:4e91d7cf-9f46-4c59-5468-49329033a255.pdf"},{"title":"Chuong V_Phân tích tương quan và hồi quy.pdf","type":"PDF","url":"vedu-file:4fdb9f4c-2354-0c2f-4dd0-0b388fd559a1.pdf"},{"title":"Khai thác dữ liệu (Course2025-HUIT)","type":"LINK","url":"https://www.youtube.com/playlist?list=PLf5IPckgFwFXx4iupnopVRPflUGquequj"},{"title":"Đề cương trong CTĐT CNTT2017","type":"LINK","url":"https://fit.huit.edu.vn/app_web/images/documents/n00ct/1-ctdt-nganh-cntt_nam-2017.pdf"}]},{"title":"04 · Gom cụm dữ liệu","content":"BÀI TẬP NHỎ\n\n1. Cho điểm 1D [1,2,8,9], k=2, tâm ban đầu1 và9. Thực hiện gán cụm, cập nhật tâm rồi tính SSE theo tâm mới.\n\n2. Giải thích vì sao SSE thường giảm khi tăng k. So sánh k-means với k-medoids và gom cụm phân cấp; khi nào cần chuẩn hóa?\n\nTHỰC HÀNH\n\nDùng dữ liệu 2D tự tạo: (1,1),(1,2),(2,1),(8,8),(8,9),(9,8). Chạy k-means k=2 với tâm đầu (1,1),(8,8), lưu từng vòng và SSE. Vẽ cụm, đối chiếu gom cụm phân cấp với complete linkage và khoảng cách Euclid. Thử một điểm ngoại lai (30,30), phân tích ảnh hưởng; không gọi nhãn cụm là nhãn đúng đã biết.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/data-mining/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:15f79700-667a-a693-45a9-804ca9602068.pdf"},{"title":"3 - Bai tap chuong 2 - Buoi 1.pdf","type":"PDF","url":"vedu-file:d38acb71-e020-452f-5e54-2248666baff0.pdf"},{"title":"BÀI KIỂM TRA 2.pdf","type":"PDF","url":"vedu-file:4d031ca8-2a46-f869-36a6-c4e67e305951.pdf"},{"title":"Chuong III_Phân lớp dữ liệu -31.pdf","type":"PDF","url":"vedu-file:6ca576f1-25af-c3df-b7ea-ca971761f6b6.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp (tiếp theo).pdf","type":"PDF","url":"vedu-file:828dda87-779f-8583-205b-3d05831043ce.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp.pdf","type":"PDF","url":"vedu-file:71db5cd1-c144-9ab9-ef77-18e1c76a9839.pdf"},{"title":"Chuong IV_Gom cụm dữ liệu.pdf","type":"PDF","url":"vedu-file:5282b5e1-9365-bdfe-f098-b7fe65ad70dc.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu (tiếp theo).pdf","type":"PDF","url":"vedu-file:fa89e432-fddd-01f8-d41d-37462202dc14.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu.pdf","type":"PDF","url":"vedu-file:4e91d7cf-9f46-4c59-5468-49329033a255.pdf"},{"title":"Chuong V_Phân tích tương quan và hồi quy.pdf","type":"PDF","url":"vedu-file:4fdb9f4c-2354-0c2f-4dd0-0b388fd559a1.pdf"},{"title":"Khai thác dữ liệu (Course2025-HUIT)","type":"LINK","url":"https://www.youtube.com/playlist?list=PLf5IPckgFwFXx4iupnopVRPflUGquequj"},{"title":"Đề cương trong CTĐT CNTT2017","type":"LINK","url":"https://fit.huit.edu.vn/app_web/images/documents/n00ct/1-ctdt-nganh-cntt_nam-2017.pdf"}]},{"title":"05 · Tương quan, kiểm định và hồi quy","content":"BÀI TẬP NHỎ\n\n1. Với x=[1,2,3], y=[2,4,6], tính Pearson r và đường hồi quy y=a+bx. Có suy ra quan hệ nhân quả không?\n\n2. Chọn phương pháp cho từng tình huống: liên hệ giữa hai biến định tính; so sánh trung bình ba nhóm; quan hệ tuyến tính giữa hai biến định lượng. Nêu một điều kiện cần kiểm tra cho mỗi phương pháp.\n\nTHỰC HÀNH\n\nXây dựng kế hoạch phân tích dữ liệu khách hàng: dùng chi-square cho vùng×phản hồi, ANOVA cho chi tiêu giữa các vùng, Pearson và hồi quy cho thu nhập×chi tiêu. Viết H0/H1, mức ý nghĩa0,05, giả định và cách xử lý khi giả định không đạt. Phân biệt hồi quy tuyến tính/đa biến/đa thức và logistic. Nếu chạy trên dữ liệu giả lập phải ghi rõ, không suy rộng ra dân số thật.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/data-mining/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:15f79700-667a-a693-45a9-804ca9602068.pdf"},{"title":"3 - Bai tap chuong 2 - Buoi 1.pdf","type":"PDF","url":"vedu-file:d38acb71-e020-452f-5e54-2248666baff0.pdf"},{"title":"BÀI KIỂM TRA 2.pdf","type":"PDF","url":"vedu-file:4d031ca8-2a46-f869-36a6-c4e67e305951.pdf"},{"title":"Chuong III_Phân lớp dữ liệu -31.pdf","type":"PDF","url":"vedu-file:6ca576f1-25af-c3df-b7ea-ca971761f6b6.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp (tiếp theo).pdf","type":"PDF","url":"vedu-file:828dda87-779f-8583-205b-3d05831043ce.pdf"},{"title":"Chuong II_Tập phổ biến và luật kết hợp.pdf","type":"PDF","url":"vedu-file:71db5cd1-c144-9ab9-ef77-18e1c76a9839.pdf"},{"title":"Chuong IV_Gom cụm dữ liệu.pdf","type":"PDF","url":"vedu-file:5282b5e1-9365-bdfe-f098-b7fe65ad70dc.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu (tiếp theo).pdf","type":"PDF","url":"vedu-file:fa89e432-fddd-01f8-d41d-37462202dc14.pdf"},{"title":"Chuong I_Tổng quan về khai thác dữ liệu.pdf","type":"PDF","url":"vedu-file:4e91d7cf-9f46-4c59-5468-49329033a255.pdf"},{"title":"Chuong V_Phân tích tương quan và hồi quy.pdf","type":"PDF","url":"vedu-file:4fdb9f4c-2354-0c2f-4dd0-0b388fd559a1.pdf"},{"title":"Khai thác dữ liệu (Course2025-HUIT)","type":"LINK","url":"https://www.youtube.com/playlist?list=PLf5IPckgFwFXx4iupnopVRPflUGquequj"},{"title":"Đề cương trong CTĐT CNTT2017","type":"LINK","url":"https://fit.huit.edu.vn/app_web/images/documents/n00ct/1-ctdt-nganh-cntt_nam-2017.pdf"}]}],"questions":[{"text":"KDD có bước nào trước khi xây mô hình?","options":["Hiểu và tiền xử lý dữ liệu","Công bố kết quả trước khi chạy","Dùng nhãn test để chọn đặc trưng","Xóa toàn bộ ngoại lệ không phân tích"],"correct":0},{"text":"Dữ liệu tuổi 20,22,thiếu,26 có trung bình phần quan sát là bao nhiêu?","options":["68/3","17","26","22"],"correct":0},{"text":"KNN phân lớp dựa chủ yếu vào gì?","options":["Nhãn của các láng giềng gần theo khoảng cách đã chọn","Chỉ tên bản ghi","Số thứ tự hàng","Luôn chọn lớp hiếm nhất"],"correct":0},{"text":"Support của A trong 20 giao dịch nếu A xuất hiện 5 lần?","options":["0,25","4","0,75","5"],"correct":0},{"text":"Confidence A→B nếu A có 10 lần, A và B cùng có 6 lần?","options":["0,6","0,4","1,67","6"],"correct":0},{"text":"Chọn số cụm bằng nhãn test rồi báo kết quả trên chính test có vấn đề gì?","options":["Làm rò rỉ thông tin đánh giá","Luôn tăng tính khách quan","Thay thế validation hợp lệ","Không ảnh hưởng nếu dữ liệu ít"],"correct":0},{"text":"Hồi quy thường dự đoán loại đầu ra nào?","options":["Giá trị số liên tục","Chỉ tên lớp rời rạc","Chỉ mã định danh","Luôn là giá trị Boolean"],"correct":0},{"text":"Metric nào cần xem khi lớp dương hiếm?","options":["Precision, recall và ma trận nhầm lẫn","Chỉ accuracy là đủ mọi trường hợp","Chỉ số lượng hàng","Chỉ thời gian đọc CSV"],"correct":0}]},{"key":"software-testing","name":"Kiểm định phần mềm","topic":"Lập trình & Phát triển phần mềm","marker":"[VEDU-CURATED-v202611:software-testing]","summary":"Khóa tự học Kiểm định phần mềm theo học liệu nhóm cung cấp, gồm 8 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Công nghệ phần mềm","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Kiểm định phần mềm theo học liệu nhóm cung cấp, gồm 8 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nCông nghệ phần mềm\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 8 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tổng quan kiểm thử\n2. Quy trình và kế hoạch kiểm thử\n3. Thiết kế test case và test data\n4. Unit test với NUnit/JUnit\n5. BDD và Gherkin\n6. Kiểm thử UI với Selenium IDE\n7. Kiểm thử API với Postman\n8. Thực thi, báo lỗi và hồi quy\n\nNGUỒN\nVEDU_KiemDinhPhanMem.zip\nKhóa học kiểm thử phần mềm https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK\nAPI Testing With Postman https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU\nReqnroll - SpecFlow end of life https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/\nNUnit Assertions https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html\nPostman tests and assertions https://learning.postman.com/docs/tests-and-scripts/write-scripts/postman-sandbox-reference/pm-test-expect\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/software-testing/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"Chuong 5. Thuc thi kiem thu va bao cao loi.pdf","type":"PDF","url":"vedu-file:b15b7841-a7fb-da9e-3e81-599df5539025.pdf"},{"title":"Chuong 1. Tong quan ve Kiem thu Phan mem.pdf","type":"PDF","url":"vedu-file:6ab8f655-5e10-97e2-856d-388bc4f73bae.pdf"},{"title":"Chuong 2. Qui trinh va Ke hoach kiem thu.pdf","type":"PDF","url":"vedu-file:9e5e128f-7435-cae1-4091-3e8a95d458f4.pdf"},{"title":"Thuc hanh Buoi 2. Quy trinh va ke hoach kiem thu.pdf","type":"PDF","url":"vedu-file:74c0da21-975d-bf2b-1576-a0d676b62f68.pdf"},{"title":"Chuong 3. Thiet ke cac truong hop kiem thu.pdf","type":"PDF","url":"vedu-file:6adfc217-7ee7-768c-2e45-f5c6a48e2eb7.pdf"},{"title":"Thuc hanh Buoi 3. Thiet ke truong hop kiem thu (1).pdf","type":"PDF","url":"vedu-file:536c195b-97f1-9df6-d7d2-19024717e486.pdf"},{"title":"Thuc hanh Buoi 4. Thiet ke truong hop kiem thu (2).pdf","type":"PDF","url":"vedu-file:a6438ccc-8014-d0b2-82ed-bc6c268e40c9.pdf"},{"title":"Thuc hanh Buoi 5. Thiet ke truong hop kiem thu (3).pdf","type":"PDF","url":"vedu-file:e9ccdc35-ac29-6a0a-bd51-081306482fe0.pdf"},{"title":"Thuc hanh Buoi 10. Kiem thu tu dong (4)_Posman.pdf","type":"PDF","url":"vedu-file:cef60ecd-b750-e3b2-3e87-14b5845294ce.pdf"},{"title":"Thuc hanh Buoi 7. Kiem thu tu dong (1).pdf","type":"PDF","url":"vedu-file:7ed97f4a-b373-8972-90f3-c70835778e20.pdf"},{"title":"Thuc hanh Buoi 8. Kiem thu tu dong (2)_Gherkin.pdf","type":"PDF","url":"vedu-file:32951f00-4c3e-909a-1ce0-e7b1ec31396f.pdf"},{"title":"Thuc hanh Buoi 9. Kiem thu tu dong (3).pdf","type":"PDF","url":"vedu-file:89a372ee-839a-2707-d62c-b1a607bb8693.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"}]},{"title":"01 · Tổng quan kiểm thử","content":"BÀI TẬP NHỎ\n\n1. Phân biệt error, defect, failure bằng một ví dụ nhập điểm sai. So sánh testing với debugging.\n\n2. Yêu cầu ghi “trang tải nhanh và dễ dùng”. Nêu điểm chưa kiểm thử được, đề xuất tiêu chí đo và đánh dấu đó là giả định cần thống nhất.\n\nTHỰC HÀNH\n\nReview tĩnh đặc tả LMS bên dưới: xác định ít nhất5 câu hỏi/rủi ro còn mở, phân loại mức kiểm thử phù hợp cho từng yêu cầu. Nộp biên bản review và danh sách vấn đề; không tự ghi Pass khi chưa chạy phần mềm.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]},{"title":"02 · Quy trình và kế hoạch kiểm thử","content":"BÀI TẬP NHỎ\n\n1. Sắp xếp các hoạt động: phân tích, thiết kế, chuẩn bị dữ liệu/môi trường, thực thi, theo dõi và kết thúc; nêu hoạt động có thể lặp lại.\n\n2. Phân biệt entry criteria, exit criteria và phạm vi ngoài kiểm thử. Đặt tiêu chí đề xuất cho kiểm thử chức năng nộp bài.\n\nTHỰC HÀNH\n\nLập test plan cho đăng nhập, ghi danh và nộp bài LMS: mục tiêu, phạm vi, rủi ro, môi trường, nhân sự, lịch, dữ liệu, tiêu chí vào/ra, sản phẩm và xử lý sự cố. Liên kết mỗi rủi ro với ít nhất một test case dự kiến.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]},{"title":"03 · Thiết kế test case và test data","content":"BÀI TẬP NHỎ\n\n1. Điểm nhập là số nguyên từ0 đến10. Liệt kê lớp tương đương và giá trị biên ba điểm tại hai đầu, thêm null/chuỗi/số thập phân.\n\n2. Điều kiện ghi danh: đã đăng nhập VÀ lớp mở VÀ chưa ghi danh. Lập bảng quyết định với8 tổ hợp; nêu expected result theo thứ tự kiểm tra quy định.\n\nTHỰC HÀNH\n\nThiết kế ít nhất18 test case cho đặc tả LMS, gồm phân hoạch tương đương, giá trị biên, bảng quyết định và chuyển trạng thái. Mỗi case có ID yêu cầu, tiền điều kiện, dữ liệu, bước, expected result. Lập RTM; actual/status để trống hoặc Not Run. Vẽ đồ thị nhân quả cho ba điều kiện ghi danh trước khi chuyển thành bảng quyết định.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]},{"title":"04 · Unit test với NUnit/JUnit","content":"BÀI TẬP NHỎ\n\n1. Hàm ValidScore nhận số nguyên và trả true khi0≤n≤10. Viết ca kiểm thử tham số hóa cho6 giá trị biên; nêu expected.\n\n2. Phân biệt Arrange, Act, Assert. Giải thích vì sao unit test nên độc lập và không phụ thuộc thứ tự chạy.\n\nTHỰC HÀNH\n\nHiện thực ValidScore bằng C# hoặc Java và viết NUnit hoặc JUnit tests cho giá trị hợp lệ/không hợp lệ. Cố ý đổi điều kiện n≤10 thành n<10 trong bản sao thử nghiệm để kiểm tra test bắt lỗi; phục hồi sau đó. Nộp code, phiên bản thư viện và log trước/sau thực chạy. Kiểm tra dữ liệu null/chuỗi ở tầng parse riêng, không ép vào hàm chỉ nhận int.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]},{"title":"05 · BDD và Gherkin","content":"BÀI TẬP NHỎ\n\n1. Viết Given/When/Then cho ghi danh thành công. Phân biệt trạng thái ban đầu, hành động và kết quả quan sát.\n\n2. Chuyển ba trường hợp ghi danh không hợp lệ thành Scenario Outline với Examples; tránh viết bước chỉ mô tả tọa độ click.\n\nTHỰC HÀNH\n\nTạo feature có ít nhất4 scenario cho REQ-ENR, ánh xạ binding C# hoặc framework tương ứng và assertion nghiệp vụ. Nộp feature, binding và log nếu đã chạy. SpecFlow trong lab gốc là công nghệ cũ; nếu dùng Reqnroll, ghi rõ thay thế kỹ thuật và phiên bản, không gọi đó là nội dung gốc của trường.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]},{"title":"06 · Kiểm thử UI với Selenium IDE","content":"BÀI TẬP NHỎ\n\n1. Phân biệt click/type với assert/verify. Một kịch bản record không có kiểm tra kết quả có chứng minh chức năng đúng không?\n\n2. Nêu rủi ro của locator theo vị trí và chờ cố định. Đề xuất locator ổn định và chờ điều kiện.\n\nTHỰC HÀNH\n\nVới LMS demo của nhóm trên môi trường test, tạo suite đăng nhập và ghi danh tối thiểu6 case, gồm cả âm. Mỗi case tự chuẩn bị trạng thái, có assertion và dọn dữ liệu nếu cần. Xuất .side và lưu log/ảnh thực chạy. Nếu chưa có ứng dụng, nộp thiết kế và ghi Blocked, không tạo ảnh kết quả giả.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]},{"title":"07 · Kiểm thử API với Postman","content":"BÀI TẬP NHỎ\n\n1. Liệt kê method, URL, headers, body và response cần kiểm tra cho đăng ký khóa học. Vì sao chỉ kiểm tra HTTP200 là chưa đủ?\n\n2. Phân biệt401,403,404 theo hợp đồng API của ứng dụng. Viết ý tưởng assertion cho response body và trạng thái lưu dữ liệu.\n\nTHỰC HÀNH\n\nTrên API test của nhóm, xây collection ít nhất6 request/case: thành công, thiếu xác thực, lớp không tồn tại, lớp đóng, ghi danh trùng, dữ liệu sai kiểu. Xác nhận status/body theo hợp đồng API thực tế trước khi chạy. Dùng environment cho baseUrl; export collection và environment không có token thật, kèm kết quả Collection Runner nếu đã chạy.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]},{"title":"08 · Thực thi, báo lỗi và hồi quy","content":"BÀI TẬP NHỎ\n\n1. Phân biệt severity với priority. Cho ví dụ một lỗi hiển thị ít ảnh hưởng nhưng cần sửa sớm do sắp demo.\n\n2. Phân biệt confirmation testing (retest lỗi đã sửa) và regression. Với sửa chức năng ghi danh, chọn phạm vi hồi quy có lý do.\n\nTHỰC HÀNH\n\nThực thi bộ case trên build xác định, ghi Actual, Status, Evidence. Tạo bug report cho lỗi thật với bước tái hiện và expected/actual. Nếu không phát hiện lỗi, ghi không phát hiện trong phạm vi; bài luyện viết bug dùng tình huống giả định phải gắn nhãn. Lập báo cáo tổng kết, retest và regression, liệt kê lỗi/rủi ro còn mở.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/software-testing/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:a963314b-9b08-ee29-bd48-8b3dc316bd06.pdf"},{"title":"DeCuongChiTiet_KDPM_2022_update 2025_3012._formatted_chuaky.pdf","type":"PDF","url":"vedu-file:62f183a5-cc33-ed37-61da-240c6ad1079a.pdf"},{"title":"Khóa học kiểm thử phần mềm","type":"LINK","url":"https://www.youtube.com/playlist?list=PLmGP0M1IXtjVek2qM5az_tLrf5bwiqOLK"},{"title":"API Testing With Postman","type":"LINK","url":"https://www.youtube.com/playlist?list=PLgcMOggxCIP1X0wyYsqzdAgYQJnsJAOKU"},{"title":"Reqnroll - SpecFlow end of life","type":"LINK","url":"https://reqnroll.net/news/2025/01/specflow-end-of-life-has-been-announced/"},{"title":"NUnit Assertions","type":"LINK","url":"https://docs.nunit.org/articles/nunit/writing-tests/assertions/assertions.html"}]}],"questions":[{"text":"Failure là gì?","options":["Hành vi hệ thống không đáp ứng yêu cầu khi vận hành","Mọi lỗi gõ bàn phím của lập trình viên","Tên một công cụ debug","Mọi bản ghi bug đều đã tái hiện"],"correct":0},{"text":"Trường tuổi cho phép 18–60, nhóm giá trị biên phù hợp là gì?","options":["17,18,19,59,60,61","20,30,40","Chỉ 18","Chỉ dữ liệu hợp lệ"],"correct":0},{"text":"Retest nhằm mục đích gì?","options":["Kiểm tra lỗi cụ thể đã được sửa","Tìm tác động phụ ở mọi tính năng khác","Thay thế mọi kiểm thử","Đánh giá bố cục báo cáo"],"correct":0},{"text":"Regression testing nhằm mục đích gì?","options":["Tìm tác động ngoài ý muốn sau thay đổi","Chỉ chạy lại một bug vừa sửa","Chỉ đo tốc độ mạng","Chỉ kiểm tra tên branch"],"correct":0},{"text":"Bug report có ích cần gì?","options":["Bước tái hiện, môi trường, kỳ vọng, kết quả thực và bằng chứng","Chỉ câu hệ thống bị lỗi","Mật khẩu thật của người dùng","Kết luận chưa chạy thử"],"correct":0},{"text":"Một test chưa chạy nên ghi trạng thái gì?","options":["Not Run hoặc Blocked theo nguyên nhân","Pass","Fail vì chưa chạy","Đã nghiệm thu"],"correct":0},{"text":"API test nên kiểm tra gì ngoài HTTP status?","options":["Nội dung đáp ứng và tác động nghiệp vụ","Chỉ màu giao diện","Chỉ tên URL","Không cần assertion"],"correct":0},{"text":"RTM giúp làm gì?","options":["Truy vết yêu cầu tới test case và kết quả","Tự sinh mọi mật khẩu","Thay thế code ứng dụng","Loại bỏ nhu cầu review"],"correct":0}]},{"key":"programming-techniques","name":"Kỹ thuật lập trình","topic":"Lập trình & Phát triển phần mềm","marker":"[VEDU-CURATED-v202611:programming-techniques]","summary":"Khóa tự học Kỹ thuật lập trình theo học liệu nhóm cung cấp, gồm 8 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Kiến thức CNTT nền tảng và máy tính để thực hành.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Kỹ thuật lập trình theo học liệu nhóm cung cấp, gồm 8 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nKiến thức CNTT nền tảng và máy tính để thực hành.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 8 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Phong cách lập trình, ngoại lệ và tập tin\n2. Mảng một chiều: tổng, đếm, tìm kiếm, min/max\n3. Sắp xếp, thêm và xóa phần tử\n4. Mảng hai chiều và ma trận\n5. Chuỗi cơ bản, chuẩn hóa và token\n6. Tìm kiếm, đếm và thay thế chuỗi con\n7. Đệ quy tuyến tính và nhị phân\n8. Đệ quy lồng, hỗ tương và ứng dụng\n\nNGUỒN\nVEDU_Kỹ Thuật Lập Trình.zip\nHowKteam — Lập trình C++ cơ bản https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM\nMicrosoft Learn - Exceptions and error handling https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170\nMicrosoft Learn - fstream https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170\nHow Kteam - Đệ quy trong C++ https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966\nBài 33 — Mảng một chiều https://www.youtube.com/watch?v=cgKiUF98fLo\nBài 34 — Thao tác mảng một chiều https://www.youtube.com/watch?v=b8-F1w25sVo\nBài 35 — Mảng hai chiều https://www.youtube.com/watch?v=gPzzRrQ5SfY\nBài 36 — Thao tác mảng hai chiều https://www.youtube.com/watch?v=gXhS1LI2Y1k\nBài 37 — Mảng ký tự https://www.youtube.com/watch?v=ktm1VCiBXq0\nBài 38 — Thao tác mảng ký tự https://www.youtube.com/watch?v=kdGweX-2Hck\nLàm việc với file text trong C++ — fstream https://www.youtube.com/watch?v=LekUWlASyMY\nXử lý ngoại lệ Try, Catch, Throw — Phần 1 https://www.youtube.com/watch?v=ifR8vbGIUZQ\nGiải thích cách hàm đệ quy hoạt động trong C++ https://www.youtube.com/watch?v=eQ3VpTtc9lE\nBản chất đệ quy — Bài toán Tháp Hà Nội https://www.youtube.com/watch?v=OeZvn35BUfY\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/programming-techniques/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Bai 06 - Mot so cau truc du lieu co ban.pdf","type":"PDF","url":"vedu-file:0123c3b8-9126-8673-b312-41f94cc5436d.pdf"},{"title":"GIAI THUAT VA LAP TRINH - DHSP HN (1).pdf","type":"PDF","url":"vedu-file:df6c87e4-177a-274e-1410-71c0b691cd20.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"Introduction.to.Algorithms.2nd.Edition (1).pdf","type":"PDF","url":"vedu-file:68fb8041-9da5-89c5-2f32-fb5e75e88baa.pdf"},{"title":"Kernighan_Ritchie_Language_C.pdf","type":"PDF","url":"vedu-file:94ed541a-f524-4891-8b11-ac6fb257a658.pdf"},{"title":"Ky_thuat_lap_trinh_8227.pdf","type":"PDF","url":"vedu-file:8e836e9f-cbd1-693f-3ee0-76525ffbabaa.pdf"},{"title":"lect10_pointer.pdf","type":"PDF","url":"vedu-file:db6a1827-7587-5b8b-47c9-1cb1fa7b5a5e.pdf"},{"title":"ĐỀ CƯƠNG HỌC PHẦN KỸ THUẬT LẬP TRÌNH.pdf","type":"PDF","url":"vedu-file:2f4baa7f-b7d6-fa2e-9129-d9ff16b0fd23.pdf"}]},{"title":"01 · Phong cách lập trình, ngoại lệ và tập tin","content":"Viết chương trình dễ kiểm tra; phân biệt dữ liệu không hợp lệ với lỗi thuật toán. ifstream/ofstream mặc định thường báo lỗi qua trạng thái stream, không tự ném ngoại lệ cho mọi lỗi. Kiểm tra trạng thái và throw rõ ràng; bắt const std::exception& ở nơi có thể xử lý.\n\nĐọc theo nguồn: Chương 1; giáo trình HUFI trang 5–21. Ngoại lệ cần đọc bổ sung R01; tập tin R02.\n\nBÀI TẬP NHỎ\n\n1. Viết hàm chia(a,b), từ chối b=0 bằng invalid_argument; kiểm thử 6/2 và 6/0.\n\n2. Đọc tệp số nguyên; phân biệt không mở được tệp với token không phải số. Không dùng while(!eof()) làm điều kiện đọc.\n\nTHỰC HÀNH\n\nĐọc input.txt gồm n (1..100) và đúng n số nguyên trong [-1000,1000], từ chối thiếu/thừa token. Tính tổng bằng long long, ghi output.txt. Nếu lỗi, báo lý do và không ghi kết quả thành công. Chia thành hàm đọc, xử lý, ghi; có try-catch.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]},{"title":"02 · Mảng một chiều: tổng, đếm, tìm kiếm, min/max","content":"Phân tích hợp đồng đầu vào trước vòng lặp. Khởi tạo min/max bằng phần tử đầu khi mảng không rỗng. Dùng một lượt duyệt khi các thống kê độc lập; độ phức tạp O(n) theo số phần tử.\n\nĐọc theo nguồn: Chương 2.1; giáo trình HUFI trang 22–32.\n\nBÀI TẬP NHỎ\n\n1. Với mảng [3,-2,3,0,7], tính tổng số dương và đếm số chẵn.\n\n2. Viết hàm tìm vị trí đầu tiên của x; trả -1 nếu không có, chỉ số tính từ 0.\n\nTHỰC HÀNH\n\nNhập n trong 1..100 và các số trong [-1000,1000]. Xuất tổng, số phần tử âm, min/max, mọi vị trí của x. Tách hàm và nêu độ phức tạp. Không dùng hàm thư viện thay toàn bộ thuật toán.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]},{"title":"03 · Sắp xếp, thêm và xóa phần tử","content":"Phân biệt độ dài đang dùng với sức chứa. Khi thêm phải dịch từ phải sang trái; khi xóa dịch từ trái sang phải. Dùng insertion sort để thể hiện quá trình sắp xếp; xét trường hợp dữ liệu đã có thứ tự.\n\nĐọc theo nguồn: Chương 2.1; giáo trình HUFI trang 33–34; nguồn V01.\n\nBÀI TẬP NHỎ\n\n1. Mô phỏng insertion sort cho [5,2,4,2].\n\n2. Với mảng sức chứa 100, viết hàm chèn x tại p (0..n), từ chối khi đầy hoặc p sai.\n\nTHỰC HÀNH\n\nTạo chương trình menu nhập, chèn, xóa tại p, sắp xếp tăng, in mảng. Dùng mảng tĩnh sức chứa 100, cho phép mảng rỗng. Không dùng std::sort. Kiểm tra mọi vị trí và không truy cập ngoài giới hạn.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]},{"title":"04 · Mảng hai chiều và ma trận","content":"Duyệt ma trận theo hàng/cột và tránh đếm hai lần giao điểm. Đường chéo chính i=j, phụ i+j=n-1 với chỉ số từ 0. Chỉ áp dụng đường chéo cho ma trận vuông khi đề yêu cầu.\n\nĐọc theo nguồn: Chương 2.2; giáo trình HUFI trang 35–50.\n\nBÀI TẬP NHỎ\n\n1. Tính tổng từng hàng và số phần tử âm của ma trận [[1,-2,3],[4,5,-6]].\n\n2. Với ma trận 3×3 chứa 1..9 theo hàng, tính tổng hợp hai đường chéo, mỗi ô tính một lần.\n\nTHỰC HÀNH\n\nNhập ma trận r×c, 1≤r,c≤20, phần tử [-1000,1000]. Tính tổng từng hàng, tìm max và tất cả vị trí, sắp xếp tăng riêng từng hàng bằng thuật toán tự viết. Nếu vuông, tính tổng hợp hai đường chéo không lặp ô.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]},{"title":"05 · Chuỗi cơ bản, chuẩn hóa và token","content":"Trong các bài mới, dùng chuỗi ASCII để định nghĩa ký tự rõ ràng. Token là dãy ký tự không phải dấu cách, ngăn bởi một hay nhiều dấu cách ASCII. Chuẩn hóa bỏ dấu cách đầu/cuối và gộp nhiều dấu cách thành một. Không tự đồng nhất byte UTF-8 với ký tự tiếng Việt.\n\nĐọc theo nguồn: Chương 3.1–3.3, 3.5; giáo trình HUFI trang 80–81 và nội dung bổ sung.\n\nBÀI TẬP NHỎ\n\n1. Viết hàm độ dài chuỗi char kết thúc bằng ký tự null; giải thích cần sức chứa thêm 1 byte.\n\n2. Chuẩn hóa chuỗi \"  lap   trinh C++  \" và liệt kê token.\n\nTHỰC HÀNH\n\nĐọc một dòng ASCII tối đa 200 ký tự. Xuất bản chuẩn hóa, số từ, từ dài nhất (chọn từ đầu nếu hòa), và bản đảo toàn bộ ký tự của chuỗi đã chuẩn hóa. Cho phép chuỗi rỗng; tự viết vòng lặp chuẩn hóa.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]},{"title":"06 · Tìm kiếm, đếm và thay thế chuỗi con","content":"Phải quy định có cho phép khớp chồng lấn hay không. Bài đếm dưới đây cho phép chồng lấn; bài thay thế dùng khớp không chồng lấn, quét trên chuỗi gốc từ trái sang phải. Không tìm lại trong chuỗi thay thế.\n\nĐọc theo nguồn: Chương 3.4; giáo trình HUFI trang 82–89. KMP/Boyer–Moore chỉ tham khảo mở rộng.\n\nBÀI TẬP NHỎ\n\n1. Liệt kê vị trí \"aa\" trong \"aaaa\" khi cho phép chồng lấn.\n\n2. Mô tả cách tìm mẫu bằng brute force và điều kiện giới hạn chỉ số.\n\nTHỰC HÀNH\n\nCho chuỗi ASCII s tối đa 200 ký tự, mẫu p dài 1..50, chuỗi thay thế r dài 0..50. Xuất mọi vị trí khớp (có chồng lấn), số lần khớp và kết quả thay thế không chồng lấn. Tự viết so khớp, không dùng find/replace cho phần thuật toán.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]},{"title":"07 · Đệ quy tuyến tính và nhị phân","content":"Mỗi hàm cần trường hợp cơ sở và lý do tiến tới điểm dừng. Đệ quy dùng stack; không phải luôn nhanh hơn vòng lặp. Fibonacci trực tiếp có hai lời gọi con và tính lại nhiều bài toán, dùng để phân tích chứ không tối ưu hiệu năng.\n\nĐọc theo nguồn: Chương 4.1–4.2; giáo trình HUFI trang 51–54, 59–64.\n\nBÀI TẬP NHỎ\n\n1. Viết tổng đệ quy S(n)=1+...+n cho 0≤n≤1000; nêu S(0).\n\n2. Vẽ cây lời gọi Fibonacci(4), với F(0)=0, F(1)=1; xác định phép tính bị lặp.\n\nTHỰC HÀNH\n\nViết hàm tổng mảng đệ quy với 0≤n≤100, phần tử [-1000,1000]; hàm Fibonacci trực tiếp cho 0≤k≤20. Viết phiên bản lặp để đối chiếu; đếm số lần gọi hàm Fibonacci (tính cả lần đầu).\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]},{"title":"08 · Đệ quy lồng, hỗ tương và ứng dụng","content":"Đệ quy hỗ tương là nhiều hàm gọi qua lại. Đệ quy lồng dùng kết quả một lời gọi làm đối số cho lời gọi khác, ví dụ McCarthy 91. Bài tập giới hạn dữ liệu để quan sát an toàn; không suy ra mọi đệ quy đều kết thúc.\n\nĐọc theo nguồn: Chương 4.2–4.3; giáo trình HUFI trang 55–79.\n\nBÀI TẬP NHỎ\n\n1. Viết isEven(n)/isOdd(n) gọi qua lại cho 0≤n≤100; xác định cơ sở tại n=0.\n\n2. Mô phỏng M(n)=n-10 nếu n>100, ngược lại M(M(n+11)), với n=99; chỉ dùng 90≤n≤110.\n\nTHỰC HÀNH\n\nViết chương trình minh họa chẵn/lẻ hỗ tương, McCarthy 91 trong miền đã cho, và Tháp Hà Nội cho 1≤n≤10. In từng bước chuyển đĩa và tổng bước; giải thích điểm dừng, không cần đo tốc độ.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/programming-techniques/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:6a9b61e2-f186-7174-a5e4-2d82ea29c076.pdf"},{"title":"Giao trinh KTLT _HUFI.pdf","type":"PDF","url":"vedu-file:58742a53-4447-9380-2ed0-29cd36efbb6d.pdf"},{"title":"HowKteam — Lập trình C++ cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xagFyyQPRcppjFKMQ7lvJM"},{"title":"Microsoft Learn - Exceptions and error handling","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/cpp/errors-and-exception-handling-modern-cpp?view=msvc-170"},{"title":"Microsoft Learn - fstream","type":"LINK","url":"https://learn.microsoft.com/en-us/cpp/standard-library/fstream?view=msvc-170"},{"title":"How Kteam - Đệ quy trong C++","type":"LINK","url":"https://howkteam.vn/course/khoa-hoc-lap-trinh-c-can-ban/de-quy-trong-c-recursion-3966"}]}],"questions":[{"text":"Đọc n số nguyên an toàn cần kiểm tra gì?","options":["Miền n, đủ token, đúng kiểu và dữ liệu thừa","Chỉ có mở được file","Chỉ ký tự đầu tiên","Không cần kiểm tra đầu vào"],"correct":0},{"text":"Vì sao không nên dùng while(!eof()) để đọc token?","options":["EOF có thể chỉ được đặt sau lần đọc thất bại","EOF luôn đúng từ đầu","Không thể đọc số nguyên","Vì vòng lặp luôn chỉ chạy một lần"],"correct":0},{"text":"Điều kiện cần cho binary search trên mảng thông thường?","options":["Mảng được sắp xếp theo thứ tự tương ứng","Mảng luôn có số phần tử chẵn","Mọi giá trị bằng nhau","Mảng không có phần tử đầu"],"correct":0},{"text":"Độ phức tạp tìm kiếm tuyến tính trong trường hợp xấu nhất?","options":["O(n)","O(1)","O(log n)","O(n!)"],"correct":0},{"text":"Hàm đệ quy cần gì để tránh gọi vô hạn?","options":["Điểm dừng và bước tiến tới điểm dừng","Chỉ tên hàm ngắn","Biến toàn cục","Không cần dữ liệu đầu vào"],"correct":0},{"text":"Tổng nhiều số nguyên có thể lớn nên làm gì?","options":["Chọn kiểu đủ rộng và xét giới hạn","Luôn dùng char","Bỏ các số lớn","Ép tất cả về Boolean"],"correct":0},{"text":"Truy cập a[n] trên mảng có n phần tử đánh số từ 0 là gì?","options":["Truy cập ngoài miền chỉ số hợp lệ","Phần tử cuối","Phần tử đầu","Luôn được C++ kiểm tra an toàn"],"correct":0},{"text":"Test tốt nên gồm gì?","options":["Trường hợp thường, biên và đầu vào không hợp lệ","Chỉ một ví dụ trong đề","Chỉ đầu vào đã biết đúng","Không cần kiểm tra kết quả"],"correct":0}]},{"key":"open-source","name":"Lập trình mã nguồn mở","topic":"Lập trình & Phát triển phần mềm","marker":"[VEDU-CURATED-v202611:open-source]","summary":"Khóa tự học Lập trình mã nguồn mở theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Sinh viên đã học OOP, Cơ sở dữ liệu và Thực hành OOP.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Lập trình mã nguồn mở theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nSinh viên đã học OOP, Cơ sở dữ liệu và Thực hành OOP.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 10 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. PHP và môi trường\n2. OOP trong PHP\n3. JavaScript, DOM và AJAX\n4. MySQL và PDO\n5. MySQL nâng cao\n6. Laravel và MVC\n7. Routing, Controller và Blade\n8. Migration, Eloquent và quan hệ\n9. Validation và phân quyền\n10. Website tin tức và triển khai\n\nNGUỒN\nVEDU_LapTrinhMaNguonMo.zip\nLaravel Framework 12 cơ bản https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B\nPHP cơ bản https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx\nOOP trong PHP https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D\nPHP Manual - PDO Prepared Statements https://www.php.net/manual/en/pdo.prepared-statements.php\nLaravel 12 - Validation https://laravel.com/docs/12.x/validation\nLaravel 12 - Authorization https://laravel.com/docs/12.x/authorization\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/open-source/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LapTrinhMaNguonMo_Decuong_v1.2.pdf","type":"PDF","url":"vedu-file:fb41e82e-903f-6a03-f815-f4e20013a16c.pdf"},{"title":"LTMNM_Chuong1.pptx","type":"SLIDE","url":"/course-materials/batch-assets/9ed37abb-5770-4b1d-a134-c0873e523f14.pptx"},{"title":"LTMNM_Chuong10.pdf","type":"PDF","url":"vedu-file:ea9a984d-747e-ee1c-51f7-60c633b43bfa.pdf"},{"title":"LTMNM_Chuong2.pdf","type":"PDF","url":"vedu-file:d8767e4d-577c-2a53-0255-ac24aebf45da.pdf"},{"title":"LTMNM_Chuong3.pdf","type":"PDF","url":"vedu-file:1fd2bfc9-f849-c674-7262-c665fd01fb84.pdf"},{"title":"LTMNM_Chuong4.pptx","type":"SLIDE","url":"/course-materials/batch-assets/98974ec2-1b56-15a4-c7d6-33bed1da7d28.pptx"},{"title":"LTMNM_Chuong5.pdf","type":"PDF","url":"vedu-file:3676628e-e6fb-cb9d-039a-9c685b0eca48.pdf"},{"title":"LTMNM_Chuong6.pdf","type":"PDF","url":"vedu-file:f344b198-287c-7d4c-f0ef-69bfda0d9417.pdf"},{"title":"LTMNM_Chuong7.pdf","type":"PDF","url":"vedu-file:ba414f49-8522-3449-4b14-54001a0afbe5.pdf"},{"title":"LTMNM_Chuong8.pdf","type":"PDF","url":"vedu-file:1d646770-6563-0b4c-dca6-068c56daa120.pdf"},{"title":"LTMNM_Chuong9.pdf","type":"PDF","url":"vedu-file:9d4de073-1419-6d87-f594-7208dfc61420.pdf"}]},{"title":"01 · PHP và môi trường","content":"BÀI TẬP NHỎ\n\n1. Viết hàm tính tổng giá trị 3 sản phẩm có giá 100, 200, 300.\n\n2. Tạo form tên người dùng; thử bỏ trống và nhập thẻ HTML.\n\nTHỰC HÀNH\n\nTạo trang danh sách sản phẩm PHP, form tìm tên bằng GET và form thêm bằng POST; lưu dữ liệu JSON cục bộ có kiểm tra lỗi. Thực hiện một tùy chọn giao diện bằng cookie, bộ đếm phiên bằng session và upload ảnh JPG/PNG tối đa 2 MB; kiểm tra phía server, sinh tên lưu mới và không cho chạy tệp tải lên.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong1.pptx","type":"SLIDE","url":"/course-materials/batch-assets/9ed37abb-5770-4b1d-a134-c0873e523f14.pptx"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"02 · OOP trong PHP","content":"BÀI TẬP NHỎ\n\n1. Tạo lớp Product với thuộc tính giá private và getter.\n\n2. Tạo interface Discountable và 2 lớp triển khai cách giảm giá khác nhau.\n\nTHỰC HÀNH\n\nXây Cart và Product, thêm/xóa/tính tổng; tách namespace, autoload qua Composer; từ chối số lượng âm hoặc 0, giá âm. Giải thích đóng gói, kế thừa, đa hình bằng chính mã của mình.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong2.pdf","type":"PDF","url":"vedu-file:d8767e4d-577c-2a53-0255-ac24aebf45da.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"03 · JavaScript, DOM và AJAX","content":"BÀI TẬP NHỎ\n\n1. Hiển thị số ký tự khi gõ vào input.\n\n2. Dùng fetch lấy JSON từ endpoint PHP và hiển thị trạng thái lỗi.\n\nTHỰC HÀNH\n\nThêm tìm kiếm sản phẩm không tải lại trang. API trả JSON; giao diện có đang tải, không có kết quả và lỗi máy chủ. Kiểm tra đầu vào tại server, hiển thị văn bản bằng textContent; tránh kết quả yêu cầu cũ ghi đè yêu cầu mới.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong3.pdf","type":"PDF","url":"vedu-file:1fd2bfc9-f849-c674-7262-c665fd01fb84.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"04 · MySQL và PDO","content":"BÀI TẬP NHỎ\n\n1. Thiết kế categories và products có khóa ngoại.\n\n2. Viết SELECT theo ID bằng placeholder PDO.\n\nTHỰC HÀNH\n\nLàm CRUD sản phẩm PHP/PDO với validation, tìm kiếm, phân trang 10 dòng, thứ tự ID ổn định. Chuẩn bị câu lệnh, bind giá trị, báo 404 khi thiếu bản ghi; backup và thử phục hồi vào CSDL thử nghiệm riêng.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong4.pptx","type":"SLIDE","url":"/course-materials/batch-assets/98974ec2-1b56-15a4-c7d6-33bed1da7d28.pptx"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"05 · MySQL nâng cao","content":"BÀI TẬP NHỎ\n\n1. Viết GROUP BY đếm sản phẩm mỗi danh mục, gồm cả danh mục rỗng.\n\n2. Phân biệt WHERE với HAVING bằng một ví dụ.\n\nTHỰC HÀNH\n\nTạo báo cáo số sản phẩm và giá trung bình mỗi danh mục bằng LEFT JOIN; lọc nhóm có >=2 sản phẩm. Thử transaction cập nhật hai sản phẩm, cố ý gây lỗi để rollback trên CSDL thử nghiệm.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong5.pdf","type":"PDF","url":"vedu-file:3676628e-e6fb-cb9d-039a-9c685b0eca48.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"06 · Laravel và MVC","content":"BÀI TẬP NHỎ\n\n1. Ghi phiên bản PHP, Composer, Laravel bằng lệnh kiểm tra.\n\n2. Tạo route /hello và view nhận tên từ controller.\n\nTHỰC HÀNH\n\nKhởi tạo dự án Laravel riêng, chạy trang danh sách sản phẩm giả lập theo MVC. Nộp README tái lập, .env.example không chứa bí mật và composer.lock.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong6.pdf","type":"PDF","url":"vedu-file:f344b198-287c-7d4c-f0ef-69bfda0d9417.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"07 · Routing, Controller và Blade","content":"BÀI TẬP NHỎ\n\n1. Liệt kê 7 hành động resource controller.\n\n2. Tạo layout Blade chung và 2 trang kế thừa.\n\nTHỰC HÀNH\n\nXây giao diện quản trị bằng resource routes có tên; menu, danh sách, form thêm/sửa. Dùng CSRF và method spoofing cho PUT/DELETE; chưa cần kết nối DB nếu làm riêng bài này.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong7.pdf","type":"PDF","url":"vedu-file:ba414f49-8522-3449-4b14-54001a0afbe5.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"08 · Migration, Eloquent và quan hệ","content":"BÀI TẬP NHỎ\n\n1. Tạo migration danh mục và sản phẩm có khóa ngoại.\n\n2. Tạo seeder 3 danh mục và 25 sản phẩm.\n\nTHỰC HÀNH\n\nHoàn thiện CRUD Eloquent, quan hệ belongsTo/hasMany, tìm kiếm và phân trang; dùng eager loading cho danh mục trong danh sách. Quy định không xóa danh mục đang có sản phẩm.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong8.pdf","type":"PDF","url":"vedu-file:1d646770-6563-0b4c-dca6-068c56daa120.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"09 · Validation và phân quyền","content":"BÀI TẬP NHỎ\n\n1. Soạn quy tắc tên bắt buộc tối đa 200 ký tự; giá không âm.\n\n2. Lập ma trận quyền khách, tác giả, quản trị.\n\nTHỰC HÀNH\n\nBổ sung đăng nhập, logout và policy: tác giả chỉ sửa bài của mình, quản trị sửa mọi bài. Thử gửi trực tiếp yêu cầu sửa bài người khác, thử payload đổi author_id/role. Ảnh upload giới hạn JPG/PNG 2 MB.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/09.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong9.pdf","type":"PDF","url":"vedu-file:9d4de073-1419-6d87-f594-7208dfc61420.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]},{"title":"10 · Website tin tức và triển khai","content":"BÀI TẬP NHỎ\n\n1. Thiết kế categories, posts, users và quan hệ.\n\n2. Viết 5 ca kiểm thử cho trạng thái nháp/xuất bản.\n\nTHỰC HÀNH\n\nHoàn thiện website tin tức: khách đọc bài xuất bản, tác giả quản lý bài mình, admin quản lý danh mục/bài. Tìm kiếm, phân trang, ảnh, trạng thái nháp, ngày đăng. Đóng gói README, migration/seeder, .env.example; trình diễn trên môi trường thử nghiệm và ghi rõ local/hosting.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/open-source/10.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:90474e92-2d4a-1ace-cd29-7aa1d9b69225.pdf"},{"title":"LTMNM_Chuong10.pdf","type":"PDF","url":"vedu-file:ea9a984d-747e-ee1c-51f7-60c633b43bfa.pdf"},{"title":"Laravel Framework 12 cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9Cur2QbfZbV0V8bjsJTsg0B"},{"title":"PHP cơ bản","type":"LINK","url":"https://www.youtube.com/playlist?list=PL8y3hWbcppt21UiT79eZNhGYHmVJVV4xx"},{"title":"OOP trong PHP","type":"LINK","url":"https://www.youtube.com/playlist?list=PL88QwC-jiH9C1dDqMBjbyY_QBMMZsAI5D"},{"title":"PHP Manual - PDO Prepared Statements","type":"LINK","url":"https://www.php.net/manual/en/pdo.prepared-statements.php"}]}],"questions":[{"text":"Dữ liệu từ form gửi bằng POST có tự động an toàn không?","options":["Không, server vẫn cần xác thực và kiểm tra","Có, vì không nằm trên URL","Có, nếu tên form ngắn","Chỉ cần kiểm tra ở trình duyệt"],"correct":0},{"text":"Cách giảm nguy cơ SQL injection khi truyền dữ liệu?","options":["Dùng truy vấn có tham số","Nối trực tiếp chuỗi đầu vào","Chỉ đổi tên bảng","Ẩn nút gửi"],"correct":0},{"text":"In dữ liệu người dùng ra HTML cần xử lý gì?","options":["Escape theo ngữ cảnh xuất","Luôn bỏ mọi dấu cách","Chỉ đổi chữ hoa","Không cần vì dữ liệu ở database"],"correct":0},{"text":"Session thường dùng để làm gì?","options":["Quản lý trạng thái phiên trên phía máy chủ","Lưu mật khẩu rõ trong URL","Chia sẻ mọi phiên cho tất cả người dùng","Thay thế phân quyền"],"correct":0},{"text":"Upload ảnh cần kiểm tra gì?","options":["Nội dung/loại tệp, dung lượng, tên lưu và quyền truy cập","Chỉ đuôi .jpg","Chỉ tên người gửi","Chỉ độ dài URL"],"correct":0},{"text":"Giấy phép mã nguồn mở có ý nghĩa gì?","options":["Quy định quyền và nghĩa vụ sử dụng/phân phối","Mặc định không còn bản quyền","Luôn cho xóa tên tác giả","Bảo đảm không có lỗi"],"correct":0},{"text":"MVC phân tách những phần nào?","options":["Dữ liệu/nghiệp vụ, hiển thị và điều phối","Chỉ ba tệp CSS","Chỉ ba tài khoản","Chỉ ba bảng dữ liệu"],"correct":0},{"text":"Mật khẩu tài khoản nên được lưu thế nào?","options":["Bằng hàm băm mật khẩu chuyên dụng có salt","Dạng văn bản rõ","Trong cookie công khai","Trong tên tệp avatar"],"correct":0}]},{"key":"python","name":"Lập trình Python cơ bản","topic":"Lập trình & Phát triển phần mềm","marker":"[VEDU-CURATED-v202611:python]","summary":"Khóa tự học Lập trình Python cơ bản theo học liệu nhóm cung cấp, gồm 9 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Kiến thức CNTT nền tảng và máy tính để thực hành.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Lập trình Python cơ bản theo học liệu nhóm cung cấp, gồm 9 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nKiến thức CNTT nền tảng và máy tính để thực hành.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 9 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Giới thiệu Python và lệnh in\n2. Biến và toán tử\n3. Điều kiện if/elif/else\n4. Vòng lặp for và while\n5. Hàm trong Python\n6. Chuỗi và thao tác chuỗi\n7. List và Tuple\n8. Dictionary và Module\n9. Class và thao tác tệp\n\nNGUỒN\nVEDU_LapTrinhPythonCoBan_9Bai_PDF_Video_BaiTap.zip\nPython Software Foundation - Python Tutorial https://docs.python.org/3/tutorial/\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/python/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:b683613d-78a6-6bb7-7526-62f4d4873ccf.pdf"},{"title":"Python rat la co ban - Vo Duy Tuan.pdf","type":"PDF","url":"vedu-file:8a7e01e4-25a8-4c3d-4d24-bdf493c7ca00.pdf"}]},{"title":"01 · Giới thiệu Python và lệnh in","content":"BÀI TẬP NHỎ\n\nTHỰC HÀNH\n\nViết chương trình minh họa Giới thiệu Python và lệnh in; ghi kết quả thực tế và ít nhất 5 ca kiểm thử. Không nộp dữ liệu cá nhân thật.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/python/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:b683613d-78a6-6bb7-7526-62f4d4873ccf.pdf"},{"title":"Python rat la co ban - Vo Duy Tuan.pdf","type":"PDF","url":"vedu-file:8a7e01e4-25a8-4c3d-4d24-bdf493c7ca00.pdf"},{"title":"Python Software Foundation - Python Tutorial","type":"LINK","url":"https://docs.python.org/3/tutorial/"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=QDKsQQr-1wA&list=PLu-LVHS6JzYgjXy3-Hc5b7eJibjaam3ie"}]},{"title":"02 · Biến và toán tử","content":"BÀI TẬP NHỎ\n\nTHỰC HÀNH\n\nViết chương trình minh họa Biến và toán tử; ghi kết quả thực tế và ít nhất 5 ca kiểm thử. Không nộp dữ liệu cá nhân thật.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/python/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:b683613d-78a6-6bb7-7526-62f4d4873ccf.pdf"},{"title":"Python rat la co ban - Vo Duy Tuan.pdf","type":"PDF","url":"vedu-file:8a7e01e4-25a8-4c3d-4d24-bdf493c7ca00.pdf"},{"title":"Python Software Foundation - Python Tutorial","type":"LINK","url":"https://docs.python.org/3/tutorial/"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=T0q5y4pRYgM&list=PLu-LVHS6JzYgjXy3-Hc5b7eJibjaam3ie&index=2"}]},{"title":"03 · Điều kiện if/elif/else","content":"BÀI TẬP NHỎ\n\nTHỰC HÀNH\n\nViết chương trình minh họa Điều kiện if/elif/else; ghi kết quả thực tế và ít nhất 5 ca kiểm thử. Không nộp dữ liệu cá nhân thật.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/python/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:b683613d-78a6-6bb7-7526-62f4d4873ccf.pdf"},{"title":"Python rat la co ban - Vo Duy Tuan.pdf","type":"PDF","url":"vedu-file:8a7e01e4-25a8-4c3d-4d24-bdf493c7ca00.pdf"},{"title":"Python Software Foundation - Python Tutorial","type":"LINK","url":"https://docs.python.org/3/tutorial/"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=4-yWlALTXJM&list=PLu-LVHS6JzYgjXy3-Hc5b7eJibjaam3ie&index=3"}]},{"title":"04 · Vòng lặp for và while","con