://docs.python.org/3/tutorial/"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=ln7gWlmUG30&list=PLu-LVHS6JzYgjXy3-Hc5b7eJibjaam3ie&index=7"}]},{"title":"08 · Dictionary và Module","content":"BÀI TẬP NHỎ\n\nTHỰC HÀNH\n\nViết chương trình minh họa Dictionary và Module; ghi kết quả thực tế và ít nhất 5 ca kiểm thử. Không nộp dữ liệu cá nhân thật.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/python/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:b683613d-78a6-6bb7-7526-62f4d4873ccf.pdf"},{"title":"Python rat la co ban - Vo Duy Tuan.pdf","type":"PDF","url":"vedu-file:8a7e01e4-25a8-4c3d-4d24-bdf493c7ca00.pdf"},{"title":"Python Software Foundation - Python Tutorial","type":"LINK","url":"https://docs.python.org/3/tutorial/"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=AKC31SWf8_w&list=PLu-LVHS6JzYgjXy3-Hc5b7eJibjaam3ie&index=8"}]},{"title":"09 · Class và thao tác tệp","content":"BÀI TẬP NHỎ\n\nTHỰC HÀNH\n\nViết chương trình minh họa Class và thao tác tệp; ghi kết quả thực tế và ít nhất 5 ca kiểm thử. Không nộp dữ liệu cá nhân thật.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/python/09.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:b683613d-78a6-6bb7-7526-62f4d4873ccf.pdf"},{"title":"Python rat la co ban - Vo Duy Tuan.pdf","type":"PDF","url":"vedu-file:8a7e01e4-25a8-4c3d-4d24-bdf493c7ca00.pdf"},{"title":"Python Software Foundation - Python Tutorial","type":"LINK","url":"https://docs.python.org/3/tutorial/"},{"title":"Video tham khảo theo gói học liệu - mở nguồn ngoài","type":"LINK","url":"https://www.youtube.com/watch?v=Ygw7akxNSHg&list=PLu-LVHS6JzYgjXy3-Hc5b7eJibjaam3ie&index=9"}]}],"questions":[{"text":"Lệnh nào in Hello trong Python 3?","options":["print(\"Hello\")","echo(\"Hello\")","printf(\"Hello\")","show(\"Hello\")"],"correct":0},{"text":"Phần mở rộng tệp mã nguồn Python là gì?","options":[".java",".py",".html",".exe"],"correct":1},{"text":"x=7; x+=2 thì x bằng?","options":["7","8","9","10"],"correct":2},{"text":"Kết quả 7 // 2 là?","options":["3","3.5","1","4"],"correct":0},{"text":"Nhánh nào chạy khi if False và else tồn tại?","options":["if","else","cả hai","không nhánh nào"],"correct":1},{"text":"Toán tử logic và là?","options":["&&","and","&","AND()"],"correct":1},{"text":"range(3) tạo ra các số nào?","options":["1,2,3","0,1,2","0,1,2,3","3"],"correct":1},{"text":"Lệnh thoát vòng lặp ngay là?","options":["stop","break","continue","return all"],"correct":1},{"text":"Từ khóa khai báo hàm là?","options":["func","function","def","lambda def"],"correct":2},{"text":"Hàm không có return tường minh trả về?","options":["0","False","None","chuỗi rỗng"],"correct":2},{"text":"len(\"Python\") bằng?","options":["5","6","7","8"],"correct":1},{"text":"\"abc\"[0] là?","options":["a","b","c","0"],"correct":0},{"text":"a=[1,2]; a.append(3) thì a là?","options":["[1,2]","[3,1,2]","[1,2,3]","[1,2,[3]]"],"correct":2},{"text":"Chỉ số phần tử đầu tiên của list là?","options":["0","1","-2","2"],"correct":0},{"text":"Dictionary lưu dữ liệu theo?","options":["chỉ số cố định","cặp khóa-giá trị","chỉ tuple","chỉ chuỗi"],"correct":1},{"text":"d={\"x\":5}; d[\"x\"] là?","options":["x","5","None","KeyError"],"correct":1},{"text":"Từ khóa khai báo lớp là?","options":["object","class","struct","type"],"correct":1},{"text":"Tên hàm khởi tạo thông dụng là?","options":["__start__","__newclass__","__init__","init"],"correct":2}]},{"key":"big-data","name":"Nhập môn Big Data","topic":"Khoa học dữ liệu & AI","marker":"[VEDU-CURATED-v202611:big-data]","summary":"Khóa tự học Nhập môn Big Data theo học liệu nhóm cung cấp, gồm 5 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Sinh viên CNTT/ATTT đã học Hệ cơ sở dữ liệu; học song hành Thực hành nhập môn Big Data.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Nhập môn Big Data theo học liệu nhóm cung cấp, gồm 5 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nSinh viên CNTT/ATTT đã học Hệ cơ sở dữ liệu; học song hành Thực hành nhập môn Big Data.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 5 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tổng quan dữ liệu lớn\n2. Phân tích liên kết: PageRank và HITS\n3. Cluster, DFS, sharding và replication\n4. MapReduce, Spark RDD, DataFrame và luồng\n5. Phân lớp, hồi quy, lọc cộng tác và phân tích\n\nNGUỒN\nVEDU_Nhập môn Bigdata.zip\nBigdata - Spark https://www.youtube.com/playlist?list=PLQGWFhybWxr6o1gIU6myyTXA0RoAwQs2O\nSpark RDD https://www.youtube.com/playlist?list=PLLr_PBm86prsHGuposUkiCa8kCOP7CPBB\nSpark SQL và DataFrame https://www.youtube.com/playlist?list=PLLr_PBm86prvN72CeX9aKqiE3zLValzKC\nHọc Bigdata - Hadoop https://www.youtube.com/playlist?list=PLQGWFhybWxr45tv9W508PJKldOF4-mlJ7\nKhai thác cấu trúc Web P1 - PageRank https://www.youtube.com/watch?v=KAFtnHNF114\nHadoop - Kiến trúc HDFS https://www.youtube.com/watch?v=KrCqp_XzmSg\nApache Hadoop - HDFS Architecture https://hadoop.apache.org/docs/stable/hadoop-project-dist/hadoop-hdfs/HdfsDesign.html\nApache Spark - SQL Guide https://spark.apache.org/docs/latest/sql-programming-guide.html\nApache Spark - MLlib Guide https://spark.apache.org/docs/latest/ml-guide.html\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/big-data/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:991f97f0-9872-6ea2-c19f-1502c5040c00.pdf"},{"title":"2019_Mining of Massive Datasets.pdf","type":"PDF","url":"vedu-file:4b2198f8-2e16-f84a-494e-36d17c7a8224.pdf"},{"title":"55. 01200057_Chi tiet_Nhap mon Big Data (Mau 9b).pdf","type":"PDF","url":"vedu-file:d80955ec-9d5d-c972-5543-0a7affc6653c.pdf"},{"title":"C1_Tong quan.pdf","type":"PDF","url":"vedu-file:d481e969-9d90-aac1-5ace-937ec810b203.pdf"},{"title":"C2_Links analysis.pdf","type":"PDF","url":"vedu-file:82c346e3-58a8-8dd9-195a-e3efc0962438.pdf"},{"title":"Chuong_4_Xu_ly_du_lieu_lon_tren_Apache_Spark.pdf","type":"PDF","url":"vedu-file:8c533cc4-c2dc-b7fd-876a-15f07a98a14b.pdf"},{"title":"spark-the-definitive-guide40www.bigdatabugs.com_.pdf","type":"PDF","url":"vedu-file:4ec07ad1-53e4-3abe-39bb-d8828405530a.pdf"}]},{"title":"01 · Tổng quan dữ liệu lớn","content":"Nhận diện Volume, Velocity, Variety qua bài toán cụ thể; dữ liệu lớn không chỉ là một ngưỡng dung lượng. Phân biệt dữ liệu có cấu trúc, bán cấu trúc và phi cấu trúc. Lựa chọn xử lý batch khi chấp nhận độ trễ, xử lý luồng khi cần cập nhật liên tục. Không suy ra cần Spark chỉ vì có nhiều dòng.\n\nĐọc theo nguồn: C1_Tong quan.pdf\n\nBÀI TẬP NHỎ\n\n1. Phân loại bảng đơn hàng, log JSON và ảnh sản phẩm; giải thích vì sao.\n\n2. Một cửa hàng có 10.000 đơn/ngày, mỗi đơn 2 KB (quy ước thập phân): tính dữ liệu 30 ngày, chưa tính bản sao.\n\nTHỰC HÀNH\n\nThiết kế luồng dữ liệu cho cửa hàng trực tuyến: nguồn, lưu trữ, xử lý, báo cáo. Nêu 3V, SLA độ trễ giả định, tiêu chí chọn batch/stream và một rủi ro chất lượng dữ liệu. Nộp sơ đồ và thuyết minh 1–2 trang.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/big-data/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:991f97f0-9872-6ea2-c19f-1502c5040c00.pdf"},{"title":"2019_Mining of Massive Datasets.pdf","type":"PDF","url":"vedu-file:4b2198f8-2e16-f84a-494e-36d17c7a8224.pdf"},{"title":"55. 01200057_Chi tiet_Nhap mon Big Data (Mau 9b).pdf","type":"PDF","url":"vedu-file:d80955ec-9d5d-c972-5543-0a7affc6653c.pdf"},{"title":"C1_Tong quan.pdf","type":"PDF","url":"vedu-file:d481e969-9d90-aac1-5ace-937ec810b203.pdf"},{"title":"C2_Links analysis.pdf","type":"PDF","url":"vedu-file:82c346e3-58a8-8dd9-195a-e3efc0962438.pdf"},{"title":"Chuong_4_Xu_ly_du_lieu_lon_tren_Apache_Spark.pdf","type":"PDF","url":"vedu-file:8c533cc4-c2dc-b7fd-876a-15f07a98a14b.pdf"},{"title":"spark-the-definitive-guide40www.bigdatabugs.com_.pdf","type":"PDF","url":"vedu-file:4ec07ad1-53e4-3abe-39bb-d8828405530a.pdf"},{"title":"Bigdata - Spark","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr6o1gIU6myyTXA0RoAwQs2O"},{"title":"Spark RDD","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prsHGuposUkiCa8kCOP7CPBB"},{"title":"Spark SQL và DataFrame","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prvN72CeX9aKqiE3zLValzKC"},{"title":"Học Bigdata - Hadoop","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr45tv9W508PJKldOF4-mlJ7"}]},{"title":"02 · Phân tích liên kết: PageRank và HITS","content":"PageRank chia điểm của nút cho các cạnh ra. Với ma trận M chuẩn hóa theo cột, p mới = dMp + (1-d)v. Nút không có cạnh ra phân phối lại theo v; cá nhân hóa thay v bằng phân phối ưu tiên có tổng 1. HITS cập nhật authority theo hub đi vào và hub theo authority đi ra, sau đó chuẩn hóa. Liên kết nhân tạo có thể thao túng xếp hạng; không đồng nhất nhiều liên kết với độ tin cậy.\n\nĐọc theo nguồn: C2_Links analysis.pdf\n\nBÀI TẬP NHỎ\n\n1. Cho A→B, A→C, B→C, C→A; p ban đầu=(1/3,1/3,1/3), d=0,85, v đều. Tính một bước PageRank.\n\n2. Nếu C mất toàn bộ cạnh ra, mô tả cách xử lý dangling node; so sánh với tự bỏ điểm của C.\n\nTHỰC HÀNH\n\nVới đồ thị trên, tính 3 bước PageRank và tổng điểm mỗi bước; so sánh v đều với v=(0,6;0,2;0,2). Tính một bước HITS từ hub=(1,1,1), chuẩn hóa L2 authority rồi cập nhật hub và chuẩn hóa L2. Giải thích link spam và một biện pháp giảm ảnh hưởng. Nộp bảng tính hoặc mã nguồn và báo cáo.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/big-data/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:991f97f0-9872-6ea2-c19f-1502c5040c00.pdf"},{"title":"2019_Mining of Massive Datasets.pdf","type":"PDF","url":"vedu-file:4b2198f8-2e16-f84a-494e-36d17c7a8224.pdf"},{"title":"55. 01200057_Chi tiet_Nhap mon Big Data (Mau 9b).pdf","type":"PDF","url":"vedu-file:d80955ec-9d5d-c972-5543-0a7affc6653c.pdf"},{"title":"C1_Tong quan.pdf","type":"PDF","url":"vedu-file:d481e969-9d90-aac1-5ace-937ec810b203.pdf"},{"title":"C2_Links analysis.pdf","type":"PDF","url":"vedu-file:82c346e3-58a8-8dd9-195a-e3efc0962438.pdf"},{"title":"Chuong_4_Xu_ly_du_lieu_lon_tren_Apache_Spark.pdf","type":"PDF","url":"vedu-file:8c533cc4-c2dc-b7fd-876a-15f07a98a14b.pdf"},{"title":"spark-the-definitive-guide40www.bigdatabugs.com_.pdf","type":"PDF","url":"vedu-file:4ec07ad1-53e4-3abe-39bb-d8828405530a.pdf"},{"title":"Bigdata - Spark","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr6o1gIU6myyTXA0RoAwQs2O"},{"title":"Spark RDD","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prsHGuposUkiCa8kCOP7CPBB"},{"title":"Spark SQL và DataFrame","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prvN72CeX9aKqiE3zLValzKC"},{"title":"Học Bigdata - Hadoop","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr45tv9W508PJKldOF4-mlJ7"}]},{"title":"03 · Cluster, DFS, sharding và replication","content":"Cluster gồm nhiều máy phối hợp. High availability hướng tới duy trì dịch vụ; load balancing phân phối tải, hai mục tiêu có thể cùng tồn tại. Trong cách phân loại truyền thống, symmetric có các nút hoạt động và giám sát lẫn nhau; asymmetric có vai trò chủ động/dự phòng. DFS cung cấp truy cập tệp qua nhiều nút. HDFS lưu metadata ở NameNode và block ở DataNode; replication tăng khả năng chịu lỗi nhưng tốn dung lượng. Sharding chia các phần dữ liệu khác nhau; replication giữ bản sao. Khóa shard lệch có thể tạo nút nóng. Song song không nhất thiết chạy trên nhiều máy; phân tán phải xét mạng và lỗi từng phần.\n\nĐọc theo nguồn: Chưa có slide chương 3 trong RAR\n\nBÀI TẬP NHỎ\n\n1. Vẽ phương án chia 12 bản ghi thành 3 shard theo id mod 3, mỗi shard có 2 bản sao trên 2 nút khác nhau.\n\n2. Dữ liệu gốc 120 GB, replication factor=3: tính dung lượng nội dung bản sao, bỏ qua metadata và nén.\n\nTHỰC HÀNH\n\nĐề xuất kiến trúc lưu log cho 3 nút, chỉ rõ khóa chia dữ liệu, vị trí các bản sao, đường đọc/ghi và phản ứng khi một nút hỏng. Phân biệt HA với backup, chỉ ra điểm lỗi đơn và giới hạn của mô hình. Nộp sơ đồ cùng bảng đánh đổi.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/big-data/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:991f97f0-9872-6ea2-c19f-1502c5040c00.pdf"},{"title":"2019_Mining of Massive Datasets.pdf","type":"PDF","url":"vedu-file:4b2198f8-2e16-f84a-494e-36d17c7a8224.pdf"},{"title":"55. 01200057_Chi tiet_Nhap mon Big Data (Mau 9b).pdf","type":"PDF","url":"vedu-file:d80955ec-9d5d-c972-5543-0a7affc6653c.pdf"},{"title":"C1_Tong quan.pdf","type":"PDF","url":"vedu-file:d481e969-9d90-aac1-5ace-937ec810b203.pdf"},{"title":"C2_Links analysis.pdf","type":"PDF","url":"vedu-file:82c346e3-58a8-8dd9-195a-e3efc0962438.pdf"},{"title":"Chuong_4_Xu_ly_du_lieu_lon_tren_Apache_Spark.pdf","type":"PDF","url":"vedu-file:8c533cc4-c2dc-b7fd-876a-15f07a98a14b.pdf"},{"title":"spark-the-definitive-guide40www.bigdatabugs.com_.pdf","type":"PDF","url":"vedu-file:4ec07ad1-53e4-3abe-39bb-d8828405530a.pdf"},{"title":"Bigdata - Spark","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr6o1gIU6myyTXA0RoAwQs2O"},{"title":"Spark RDD","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prsHGuposUkiCa8kCOP7CPBB"},{"title":"Spark SQL và DataFrame","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prvN72CeX9aKqiE3zLValzKC"},{"title":"Học Bigdata - Hadoop","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr45tv9W508PJKldOF4-mlJ7"}]},{"title":"04 · MapReduce, Spark RDD, DataFrame và luồng","content":"Map tạo cặp khóa–giá trị, shuffle nhóm theo khóa và reduce tổng hợp. Trong Spark, transformation thường xây kế hoạch; action kích hoạt tính toán. RDD biểu diễn tập dữ liệu phân tán; DataFrame có schema để hệ thống hiểu cấu trúc xử lý. Ví dụ dữ liệu bảng thường thuận tiện với DataFrame và SQL. Xử lý luồng cần phân biệt event time và processing time, xem xét dữ liệu đến trễ, checkpoint và ngữ nghĩa của sink; không mặc định mọi pipeline đều exactly-once.\n\nĐọc theo nguồn: Chuong_4_Xu_ly_du_lieu_lon_tren_Apache_Spark.pdf\n\nBÀI TẬP NHỎ\n\n1. Với sales.csv, viết các cặp (product, quantity×unit_price), nhóm và cộng; không dùng đơn vị tiền ngầm định.\n\n2. Phân loại filter/select và count/show thành transformation hoặc action; giải thích khi nào kết quả được tính.\n\nTHỰC HÀNH\n\nĐọc sales.csv bằng schema rõ ràng, kiểm tra quantity>0 và unit_price>=0, tính doanh thu theo sản phẩm bằng RDD hoặc mô phỏng MapReduce rồi DataFrame/Spark SQL. Đối chiếu kết quả. Thiết kế thêm cách xử lý dòng đến trễ theo event_time, nêu chính sách và checkpoint. Nộp mã, kết quả thực chạy, phiên bản môi trường; nếu chưa chạy Spark phải ghi rõ chỉ mô phỏng.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/big-data/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:991f97f0-9872-6ea2-c19f-1502c5040c00.pdf"},{"title":"2019_Mining of Massive Datasets.pdf","type":"PDF","url":"vedu-file:4b2198f8-2e16-f84a-494e-36d17c7a8224.pdf"},{"title":"55. 01200057_Chi tiet_Nhap mon Big Data (Mau 9b).pdf","type":"PDF","url":"vedu-file:d80955ec-9d5d-c972-5543-0a7affc6653c.pdf"},{"title":"C1_Tong quan.pdf","type":"PDF","url":"vedu-file:d481e969-9d90-aac1-5ace-937ec810b203.pdf"},{"title":"C2_Links analysis.pdf","type":"PDF","url":"vedu-file:82c346e3-58a8-8dd9-195a-e3efc0962438.pdf"},{"title":"Chuong_4_Xu_ly_du_lieu_lon_tren_Apache_Spark.pdf","type":"PDF","url":"vedu-file:8c533cc4-c2dc-b7fd-876a-15f07a98a14b.pdf"},{"title":"spark-the-definitive-guide40www.bigdatabugs.com_.pdf","type":"PDF","url":"vedu-file:4ec07ad1-53e4-3abe-39bb-d8828405530a.pdf"},{"title":"Bigdata - Spark","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr6o1gIU6myyTXA0RoAwQs2O"},{"title":"Spark RDD","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prsHGuposUkiCa8kCOP7CPBB"},{"title":"Spark SQL và DataFrame","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prvN72CeX9aKqiE3zLValzKC"},{"title":"Học Bigdata - Hadoop","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr45tv9W508PJKldOF4-mlJ7"}]},{"title":"05 · Phân lớp, hồi quy, lọc cộng tác và phân tích","content":"Phân lớp dự đoán nhãn rời rạc; hồi quy dự đoán số. Chia train/validation/test trước khi fit bước học từ dữ liệu để tránh rò rỉ. Với dữ liệu thời gian nên cân nhắc chia theo thời gian. Accuracy có thể gây hiểu nhầm khi lớp lệch; xem precision/recall/F1. Hồi quy có thể dùng MAE/RMSE. Lọc cộng tác học từ tương tác user–item, không tự giải quyết cold start; cần baseline và chiến lược dự phòng. Phân tích phải nêu cách làm sạch, nguồn dữ liệu và giới hạn suy luận.\n\nĐọc theo nguồn: Chưa có slide chương 5 trong RAR\n\nBÀI TẬP NHỎ\n\n1. Phân loại: dự báo doanh thu, phát hiện đơn gian lận, gợi ý sản phẩm. Chọn chỉ số đánh giá có lý do.\n\n2. Với TP=8, FP=2, FN=4, TN=86: tính accuracy, precision, recall, F1.\n\nTHỰC HÀNH\n\nĐề xuất một pipeline phân lớp/hồi quy hoặc gợi ý sản phẩm: mục tiêu, đặc trưng, chia dữ liệu, baseline, thuật toán, chỉ số và giới hạn. Dùng ratings.csv để minh họa ma trận tương tác và cold start; không tuyên bố chất lượng mô hình từ bộ dữ liệu tí hon. Nộp thiết kế và bảng kết quả thực nghiệm nếu có.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/big-data/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:991f97f0-9872-6ea2-c19f-1502c5040c00.pdf"},{"title":"2019_Mining of Massive Datasets.pdf","type":"PDF","url":"vedu-file:4b2198f8-2e16-f84a-494e-36d17c7a8224.pdf"},{"title":"55. 01200057_Chi tiet_Nhap mon Big Data (Mau 9b).pdf","type":"PDF","url":"vedu-file:d80955ec-9d5d-c972-5543-0a7affc6653c.pdf"},{"title":"C1_Tong quan.pdf","type":"PDF","url":"vedu-file:d481e969-9d90-aac1-5ace-937ec810b203.pdf"},{"title":"C2_Links analysis.pdf","type":"PDF","url":"vedu-file:82c346e3-58a8-8dd9-195a-e3efc0962438.pdf"},{"title":"Chuong_4_Xu_ly_du_lieu_lon_tren_Apache_Spark.pdf","type":"PDF","url":"vedu-file:8c533cc4-c2dc-b7fd-876a-15f07a98a14b.pdf"},{"title":"spark-the-definitive-guide40www.bigdatabugs.com_.pdf","type":"PDF","url":"vedu-file:4ec07ad1-53e4-3abe-39bb-d8828405530a.pdf"},{"title":"Bigdata - Spark","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr6o1gIU6myyTXA0RoAwQs2O"},{"title":"Spark RDD","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prsHGuposUkiCa8kCOP7CPBB"},{"title":"Spark SQL và DataFrame","type":"LINK","url":"https://www.youtube.com/playlist?list=PLLr_PBm86prvN72CeX9aKqiE3zLValzKC"},{"title":"Học Bigdata - Hadoop","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQGWFhybWxr45tv9W508PJKldOF4-mlJ7"}]}],"questions":[{"text":"Ba V thường dùng mô tả Big Data là gì?","options":["Volume, Velocity, Variety","Video, Voice, Version","Value, View, Vote","Variable, Vector, Volume"],"correct":0},{"text":"10.000 đơn/ngày, 2 KB/đơn, 30 ngày tạo bao nhiêu dữ liệu theo hệ thập phân?","options":["600 MB","60 MB","6 GB","600 GB"],"correct":0},{"text":"JSON thường được xếp vào loại dữ liệu nào?","options":["Bán cấu trúc","Luôn phi cấu trúc hoàn toàn","Chỉ cấu trúc bảng quan hệ","Không phải dữ liệu"],"correct":0},{"text":"Batch processing phù hợp khi nào?","options":["Có thể gom dữ liệu theo đợt và chấp nhận độ trễ","Bắt buộc xử lý từng sự kiện ngay lập tức","Không có dữ liệu đầu vào","Chỉ có một máy tính"],"correct":0},{"text":"HDFS nhân bản block nhằm mục đích gì?","options":["Tăng khả năng chịu lỗi","Tự bảo đảm không mất dữ liệu mọi tình huống","Thay thế mọi backup","Loại bỏ nhu cầu lưu trữ"],"correct":0},{"text":"Trong MapReduce, reduce thường làm gì?","options":["Tổng hợp các giá trị theo khóa","Chỉ đọc tên tệp","Tự gán nhãn chính xác","Chỉ vẽ biểu đồ"],"correct":0},{"text":"Spark transformation thường có đặc điểm gì?","options":["Được đánh giá lười khi có action phù hợp","Luôn chạy ngay mọi lần gọi","Không tạo kế hoạch tính toán","Luôn ghi ngay vào database"],"correct":0},{"text":"Chọn kiến trúc dữ liệu nên dựa vào đâu?","options":["Yêu cầu độ trễ, quy mô, chất lượng và chi phí","Chỉ chọn công nghệ nhiều người nhắc","Chỉ đếm số dòng CSV","Luôn dùng hệ phân tán"],"correct":0}]},{"key":"deep-learning-lab","name":"Thực hành Học sâu","topic":"Khoa học dữ liệu & AI","marker":"[VEDU-CURATED-v202611:deep-learning-lab]","summary":"Khóa tự học Thực hành Học sâu theo học liệu nhóm cung cấp, gồm 6 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Sinh viên đã học Học máy; học song hành Học sâu.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Thực hành Học sâu theo học liệu nhóm cung cấp, gồm 6 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nSinh viên đã học Học máy; học song hành Học sâu.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 6 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. NumPy, Pandas và TensorFlow\n2. ANN\n3. CNN\n4. Autoencoder\n5. RNN\n6. LSTM\n\nNGUỒN\nVEDU_TH Deep Learning.zip\nDeep Learning dành cho người mới bắt đầu https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB\nHướng dẫn lập trình với TensorFlow https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM\nAutoencoders: lý thuyết và thực nghiệm tái tạo hình ảnh https://www.youtube.com/watch?v=7MWng0n6ULE\nTensorFlow - Tensor https://www.tensorflow.org/guide/tensor\nTensorFlow - Autoencoder https://www.tensorflow.org/tutorials/generative/autoencoder\nTensorFlow - RNN https://www.tensorflow.org/guide/keras/working_with_rnns\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/deep-learning-lab/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e6c33e58-cce1-f827-d4f9-adedc0a4449c.pdf"},{"title":"52_Thuc hanh Hoc Sau_chi tiet_9b.pdf","type":"PDF","url":"vedu-file:860cd0e0-d2db-c268-0854-981836db0337.pdf"},{"title":"Lab_1_Numpy_Pandas_ver1.pdf","type":"PDF","url":"vedu-file:ca452bb3-bc9a-06cb-e000-0dc41735c7fa.pdf"},{"title":"Lab_1_Tensorflow.pdf","type":"PDF","url":"vedu-file:a426434b-2383-c482-096c-bf6a7a47ed8e.pdf"},{"title":"Lab_2_ANN.pdf","type":"PDF","url":"vedu-file:13e564db-c7dc-c1b9-02b4-10962b9a3a13.pdf"},{"title":"Lab_3_CNN.pdf","type":"PDF","url":"vedu-file:244e6664-dafd-2e00-c2ea-3fc3fde7d95a.pdf"},{"title":"Lab_4_AutoEncoder (1).pdf","type":"PDF","url":"vedu-file:b7f1c923-aacb-9a83-5822-5855cf42c115.pdf"},{"title":"Lab_5_RNN.pdf","type":"PDF","url":"vedu-file:8950bf7f-c382-b8b8-5d73-d123287ca7e9.pdf"},{"title":"Lab_6_LSTM_ver1.pdf","type":"PDF","url":"vedu-file:8fb46df8-68c2-98f7-0f85-fb0305163aa4.pdf"}]},{"title":"01 · NumPy, Pandas và TensorFlow","content":"BÀI TẬP NHỎ\n\n1. Tạo mảng 0..11, reshape (3,4), tính tổng từng hàng; báo shape và dtype.\n\n2. Tạo tensor float32 shape (2,3); phân biệt nhân từng phần với nhân ma trận và kiểm tra điều kiện kích thước.\n\nTHỰC HÀNH\n\nTự tạo CSV 12 dòng với cột id, x1, x2, label (0/1), có 1 ô thiếu x1. Tách train/validation trước khi tính giá trị điền thiếu; chỉ lấy trung bình train. Chuyển đặc trưng thành tensor float32. Nộp CSV, notebook, bảng trước/sau và giải thích chống rò rỉ dữ liệu.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning-lab/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e6c33e58-cce1-f827-d4f9-adedc0a4449c.pdf"},{"title":"Lab_1_Numpy_Pandas_ver1.pdf","type":"PDF","url":"vedu-file:ca452bb3-bc9a-06cb-e000-0dc41735c7fa.pdf"},{"title":"Lab_1_Tensorflow.pdf","type":"PDF","url":"vedu-file:a426434b-2383-c482-096c-bf6a7a47ed8e.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Autoencoders: lý thuyết và thực nghiệm tái tạo hình ảnh","type":"LINK","url":"https://www.youtube.com/watch?v=7MWng0n6ULE"},{"title":"TensorFlow - Tensor","type":"LINK","url":"https://www.tensorflow.org/guide/tensor"}]},{"title":"02 · ANN","content":"BÀI TẬP NHỎ\n\n1. Tính số tham số Dense(64) nhận 784 đặc trưng và Dense(10) nhận 64, có bias.\n\n2. Giải thích softmax 10 đầu ra đi với nhãn nguyên và sparse categorical crossentropy; phân biệt loss với accuracy.\n\nTHỰC HÀNH\n\nDùng Fashion-MNIST từ TensorFlow/Keras: giữ test riêng, chia 60.000 mẫu train thành 50.000 train và 10.000 validation với seed cố định. Chuẩn hóa /255; ANN Flatten–Dense(64,relu)–Dense(10,softmax). Huấn luyện tối đa 5 epoch ở lượt thử; chọn cấu hình bằng validation. Báo accuracy, macro-F1, confusion matrix trên test sau khi chốt mô hình; kèm learning curves và ít nhất 5 ảnh dự đoán sai.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning-lab/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e6c33e58-cce1-f827-d4f9-adedc0a4449c.pdf"},{"title":"Lab_2_ANN.pdf","type":"PDF","url":"vedu-file:13e564db-c7dc-c1b9-02b4-10962b9a3a13.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Autoencoders: lý thuyết và thực nghiệm tái tạo hình ảnh","type":"LINK","url":"https://www.youtube.com/watch?v=7MWng0n6ULE"},{"title":"TensorFlow - Tensor","type":"LINK","url":"https://www.tensorflow.org/guide/tensor"}]},{"title":"03 · CNN","content":"BÀI TẬP NHỎ\n\n1. Ảnh (28,28,1) qua Conv2D(16,3,stride=1,padding=valid) rồi MaxPool2D(2): xác định shape.\n\n2. Tính số tham số của Conv2D trên, gồm bias; so sánh với Dense.\n\nTHỰC HÀNH\n\nTrên cùng split Fashion-MNIST của ANN, thử CNN Input(28,28,1)–Conv2D(16,3,relu)–MaxPool2D(2)–Flatten–Dense(10,softmax). Giữ quy trình tiền xử lý và ngân sách thử nghiệm tương đương; so sánh tham số, thời gian thực đo, validation/test metrics. Chỉ áp dụng augmentation trên train nếu thử thêm; không kết luận CNN luôn tốt hơn ANN.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning-lab/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e6c33e58-cce1-f827-d4f9-adedc0a4449c.pdf"},{"title":"Lab_3_CNN.pdf","type":"PDF","url":"vedu-file:244e6664-dafd-2e00-c2ea-3fc3fde7d95a.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Autoencoders: lý thuyết và thực nghiệm tái tạo hình ảnh","type":"LINK","url":"https://www.youtube.com/watch?v=7MWng0n6ULE"},{"title":"TensorFlow - Tensor","type":"LINK","url":"https://www.tensorflow.org/guide/tensor"}]},{"title":"04 · Autoencoder","content":"BÀI TẬP NHỎ\n\n1. Vẽ luồng x→encoder→latent→decoder→x_hat; nêu target huấn luyện.\n\n2. Tính MSE giữa [0,1] và [0.2,0.8]; phân biệt reconstruction với classification.\n\nTHỰC HÀNH\n\nDùng Fashion-MNIST cùng split, Dense autoencoder 784→32→784 với đầu ra sigmoid trên ảnh [0,1]. Huấn luyện tái tạo với target chính ảnh đầu vào; đánh giá MSE và ảnh gốc/tái tạo. Thử latent 16 và 32 với cùng ngân sách. Nếu mở rộng phân loại, thêm classifier được huấn luyện bằng nhãn và báo metric riêng; không gọi ảnh tái tạo là nhãn dự đoán.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning-lab/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e6c33e58-cce1-f827-d4f9-adedc0a4449c.pdf"},{"title":"Lab_4_AutoEncoder (1).pdf","type":"PDF","url":"vedu-file:b7f1c923-aacb-9a83-5822-5855cf42c115.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Autoencoders: lý thuyết và thực nghiệm tái tạo hình ảnh","type":"LINK","url":"https://www.youtube.com/watch?v=7MWng0n6ULE"},{"title":"TensorFlow - Tensor","type":"LINK","url":"https://www.tensorflow.org/guide/tensor"}]},{"title":"05 · RNN","content":"BÀI TẬP NHỎ\n\n1. Với đầu vào (32,28,28), giải thích batch, timesteps, features.\n\n2. SimpleRNN(32) với 28 features: tính tham số; nêu shape đầu ra khi return_sequences True/False.\n\nTHỰC HÀNH\n\nBiểu diễn mỗi ảnh MNIST thành chuỗi 28 hàng, mỗi hàng 28 giá trị. Giữ test riêng, chia train/validation cố định. Huấn luyện SimpleRNN(32)–Dense(10,softmax); chuẩn hóa /255. Lưu split, seed, phiên bản thư viện, thời gian và learning curves để so sánh LSTM bài sau. Giải thích đây là cách biểu diễn ảnh thành chuỗi, không phải bài dự báo thời gian.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning-lab/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e6c33e58-cce1-f827-d4f9-adedc0a4449c.pdf"},{"title":"Lab_5_RNN.pdf","type":"PDF","url":"vedu-file:8950bf7f-c382-b8b8-5d73-d123287ca7e9.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Autoencoders: lý thuyết và thực nghiệm tái tạo hình ảnh","type":"LINK","url":"https://www.youtube.com/watch?v=7MWng0n6ULE"},{"title":"TensorFlow - Tensor","type":"LINK","url":"https://www.tensorflow.org/guide/tensor"}]},{"title":"06 · LSTM","content":"BÀI TẬP NHỎ\n\n1. Giải thích vai trò forget/input/output gate và cell state.\n\n2. LSTM(32), input 28 features, cấu hình Keras tiêu chuẩn có bias: tính tham số và so sánh SimpleRNN.\n\nTHỰC HÀNH\n\nThay SimpleRNN bằng LSTM(32) trên cùng split MNIST bài 5. So sánh loss/accuracy, macro-F1, số tham số và thời gian thực đo, tối đa 5 epoch lượt thử với cùng batch size. Phân tích ảnh sai, lưu mô hình và kiểm tra nạp lại để dự đoán. Không yêu cầu LSTM phải thắng RNN; kết luận dựa trên kết quả thật.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/deep-learning-lab/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:e6c33e58-cce1-f827-d4f9-adedc0a4449c.pdf"},{"title":"Lab_6_LSTM_ver1.pdf","type":"PDF","url":"vedu-file:8fb46df8-68c2-98f7-0f85-fb0305163aa4.pdf"},{"title":"Deep Learning dành cho người mới bắt đầu","type":"LINK","url":"https://www.youtube.com/playlist?list=PLMm4sOMuA2QI5x_0KlNT3LuKDi6-ByboB"},{"title":"Hướng dẫn lập trình với TensorFlow","type":"LINK","url":"https://www.youtube.com/playlist?list=PLj7lq9bPT1IYsDPoKrITUjMFCzC-jrYZM"},{"title":"Autoencoders: lý thuyết và thực nghiệm tái tạo hình ảnh","type":"LINK","url":"https://www.youtube.com/watch?v=7MWng0n6ULE"},{"title":"TensorFlow - Tensor","type":"LINK","url":"https://www.tensorflow.org/guide/tensor"}]}],"questions":[{"text":"Chuẩn hóa dữ liệu phải fit ở đâu?","options":["Tập train","Cả train và test","Chỉ test","Toàn bộ dữ liệu tương lai"],"correct":0},{"text":"Mảng có 12 phần tử reshape thành (3,4) có hợp lệ không?","options":["Có vì số phần tử được giữ nguyên","Không vì ma trận phải vuông","Có và tạo thêm 4 phần tử","Chỉ hợp lệ với chuỗi ký tự"],"correct":0},{"text":"Nhân ma trận (2,3) với (3,4) cho shape nào?","options":["(2,4)","(3,3)","(4,2)","(2,3,4)"],"correct":0},{"text":"Để tái lập notebook, cần lưu gì?","options":["Seed, phiên bản thư viện, cấu hình, dữ liệu và kết quả thực","Chỉ ảnh accuracy","Chỉ tên mô hình","Xóa các lần chạy thất bại"],"correct":0},{"text":"Autoencoder thường học mục tiêu gì?","options":["Tái tạo đầu vào qua biểu diễn trung gian","Luôn dự đoán nhãn phân lớp","Sắp xếp dữ liệu theo tên","Loại bỏ yêu cầu hàm loss"],"correct":0},{"text":"Khi mô hình chưa được chạy, báo cáo nên ghi gì?","options":["Chưa thực nghiệm, chưa có kết quả","Điền accuracy dự kiến như kết quả","Lấy số từ mô hình khác","Ghi accuracy 100%"],"correct":0},{"text":"LSTM thường phù hợp với kiểu dữ liệu nào?","options":["Dữ liệu chuỗi có phụ thuộc theo thời gian","Chỉ bảng không có thứ tự","Chỉ tên tệp","Chỉ ảnh một pixel"],"correct":0},{"text":"Đánh giá cuối cùng dùng tập test như thế nào?","options":["Giữ riêng đến khi chốt cấu hình","Chọn epoch bằng test mỗi lần","Trộn test vào train","Xóa mẫu test dự đoán sai"],"correct":0}]},{"key":"ai-lab","name":"Thực hành Trí tuệ nhân tạo","topic":"Khoa học dữ liệu & AI","marker":"[VEDU-CURATED-v202611:ai-lab]","summary":"Khóa tự học Thực hành Trí tuệ nhân tạo theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Kiến thức CNTT nền tảng và máy tính để thực hành.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Thực hành Trí tuệ nhân tạo theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nKiến thức CNTT nền tảng và máy tính để thực hành.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 10 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Python nền tảng\n2. BFS, DFS, UCS và giới hạn sâu\n3. Heuristic, AKT và A*\n4. Leo đồi và thuật toán di truyền\n5. Minimax và alpha-beta\n6. GTS và tô màu đồ thị\n7. Logic mệnh đề, Vương Hạo và Robinson\n8. Luật sinh và mạng ngữ nghĩa\n9. Học máy có giám sát\n10. Học không giám sát và K-means\n\nNGUỒN\nVEDU_TH_TriTueNhanTao.zip\nNhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr\nPython cơ bản - HowKteam https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg\nMachine learning cơ bản với Python - HowKteam https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_\nAIMA Python https://aimacode.github.io/aima-python/\nMachine Learning cơ bản - Vũ Hữu Tiệp https://machinelearningcoban.com/\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/ai-lab/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"}]},{"title":"01 · Python nền tảng","content":"Bổ trợ; PDF tuần1\n\nBÀI TẬP NHỎ\n\n1. Viết hàm kiểm tra số nguyên tố; kiểm thử n=-1,0,1,2,9,17.\n\n2. Biểu diễn đồ thị bằng dict các danh sách kề. Phân biệt list với set khi cần giữ thứ tự duyệt.\n\nTHỰC HÀNH\n\nViết chương trình đọc đồ thị từ JSON, kiểm tra đỉnh/chi phí và in danh sách kề. Tách hàm đọc, kiểm tra, hiển thị; thêm lớp Graph nếu phù hợp. Nộp mã, dữ liệu và ít nhất5 trường hợp kiểm thử gồm JSON sai và đỉnh cô lập.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"02 · BFS, DFS, UCS và giới hạn sâu","content":"Chương1; chưa có lab riêng\n\nBÀI TẬP NHỎ\n\n1. Đồ thị có hướng S→A,S→B,A→G,B→C,C→G; thứ tự kề theo chữ cái. Ghi đường đi BFS và DFS có visited.\n\n2. Gán chi phí S→A=1,A→G=9,S→B=2,B→C=2,C→G=2. So sánh đường ít cạnh và đường chi phí thấp nhất.\n\nTHỰC HÀNH\n\nCài BFS, DFS, depth-limited search và UCS. Trả path,cost,expanded; dùng đồ thị trên và thêm chu trình, đích không tới được, start=goal. Với giới hạn sâu, phân biệt cutoff và failure. Báo quy ước tính expanded và tie-break.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"03 · Heuristic, AKT và A*","content":"Chương1; PDF tuần2\n\nBÀI TẬP NHỎ\n\n1. Với đồ thị bài2, h(S)=5,h(A)=5,h(B)=4,h(C)=2,h(G)=0: tính f=g+h khi mở A,B từ S.\n\n2. Phân biệt heuristic admissible và consistent. Vì sao phát hiện goal khi sinh hàng xóm chưa đủ để dừng A*?\n\nTHỰC HÀNH\n\nCài A* có g-score, parent và priority queue; chỉ kết thúc khi lấy goal hợp lệ khỏi frontier, cập nhật đường tốt hơn và xử lý bản ghi cũ. So sánh với UCS khi h=0. Với AKT/AT, ghi rõ biến thể trong tài liệu đang dùng và bảng OPEN/CLOSED, không tự gán mọi tên thành cùng một thuật toán.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"04 · Leo đồi và thuật toán di truyền","content":"Chương1; chưa có lab riêng\n\nBÀI TẬP NHỎ\n\n1. Tối đa hóa f(x)=-(x-3)^2 với x nguyên0..6; chỉ đi sang hàng xóm±1. Từ x=0, ghi đường leo đồi.\n\n2. Nêu vai trò chromosome, fitness, selection, crossover, mutation và seed. Vì sao best fitness không chứng minh tối ưu toàn cục?\n\nTHỰC HÀNH\n\nCài leo đồi trên hàm đã cho và một ví dụ có cực trị địa phương do bạn định nghĩa. Cài GA nhỏ trên chuỗi8 bit với fitness là số bit1; cấu hình quần thể, số thế hệ, xác suất mutation và seed. So sánh5 seed, ghi fitness/số đánh giá thực chạy; không khẳng định mọi lần đạt tối ưu.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"05 · Minimax và alpha-beta","content":"Chương1; PDF tuần3\n\nBÀI TẬP NHỎ\n\n1. Cây gốc MAX có hai con MIN; lá nhánh trái[3,5], nhánh phải[2,9], duyệt trái sang phải. Tính minimax.\n\n2. Chỉ ra lá có thể bị cắt bởi alpha-beta và giải thích điều kiện alpha≥beta.\n\nTHỰC HÀNH\n\nCài minimax và alpha-beta trên cùng cây, đếm lá đã xét. Sau đó dùng cho Tic-tac-toe với terminal utility thắng1, hòa0, thua-1 theo MAX. Kiểm thử thắng ngay, chặn thua, hòa, bàn kết thúc. Nếu giới hạn depth, mô tả heuristic riêng và hạn chế.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"06 · GTS và tô màu đồ thị","content":"Chương2; chưa có lab riêng\n\nBÀI TẬP NHỎ\n\n1. Đồ thị tam giác A-B-C-A cần ít nhất mấy màu? Với2 màu, backtracking phải báo gì?\n\n2. Ma trận đối xứng: AB=2,AC=9,AD=10,BC=6,BD=4,CD=3. Chạy nearest-neighbor từA, hòa chọn chữ cái; tính chu trình.\n\nTHỰC HÀNH\n\nCài tô màu backtracking cho tam giác và chu trình4 đỉnh; kiểm tra cạnh hai đầu khác màu. Cài GTS tham lam theo quy ước nearest-neighbor nêu trên, thử mọi đỉnh xuất phát và đối chiếu vét cạn4 đỉnh. Phân biệt nghiệm khả thi, nghiệm tốt nhất tìm được và tối ưu chứng minh được.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"07 · Logic mệnh đề, Vương Hạo và Robinson","content":"Chương3; chưa có lab riêng\n\nBÀI TẬP NHỎ\n\n1. Chuyển P→Q thành CNF. Từ P và P→Q chứng minh Q bằng hợp giải với phủ định kết luận.\n\n2. Với sequent P,P→Q ⇒ Q, mô tả tách phép kéo theo bằng quy tắc Vương Hạo; phân biệt nhánh đóng và nhánh còn mở.\n\nTHỰC HÀNH\n\nCài bộ kiểm tra suy diễn bằng bảng chân trị cho tối đa4 biến làm đối chứng. Cài hợp giải mệnh đề và lưu các cặp clause sinh ra clause rỗng; minh họa Vương Hạo bằng cây quy tắc hoặc code. Kiểm thử suy diễn đúng, không suy diễn được và KB mâu thuẫn. Ghi rõ phạm vi mệnh đề, chưa phải hợp nhất logic vị từ đầy đủ.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"08 · Luật sinh và mạng ngữ nghĩa","content":"Chương3; chưa có lab riêng\n\nBÀI TẬP NHỎ\n\n1. Facts={A,B}; luật A∧B→C,C→D,D→C. Chạy suy diễn tiến và xác định điều kiện dừng.\n\n2. Tam giác có a=3,b=4,góc C=90 độ (giữa a,b). Xác định c, diện tích và các quan hệ dùng trong mạng ngữ nghĩa.\n\nTHỰC HÀNH\n\nCài suy diễn tiến/lùi với chống vòng lặp và ghi trace. Với bài tam giác, xây mạng quan hệ biến-công thức và bộ suy diễn khi đủ dữ kiện; kiểm tra miền hợp lệ, đơn vị góc và trường hợp thiếu dữ kiện. Thử loại một luật trùng rồi đối chiếu kết quả, phân biệt tối ưu tập luật với thay đổi ý nghĩa.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"09 · Học máy có giám sát","content":"Chương4; chưa có lab riêng\n\nBÀI TẬP NHỎ\n\n1. Phân biệt classification với regression; tại sao logistic regression thường dùng phân lớp?\n\n2. TP=8,FP=2,FN=1,TN=9: tính precision,recall và accuracy.\n\nTHỰC HÀNH\n\nDùng Iris để so sánh KNN, Gaussian Naive Bayes, Decision Tree và Logistic Regression: giữ test riêng, chọn tham số bằng validation/CV trên train, đặt scaler trong pipeline khi cần. Với OLS, dùng dữ liệu tự tạo y=2x+1 để kiểm chứng hệ số. Nộp code, seed, split, metric thật và phân tích; không dùng test để chọn mô hình.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/09.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]},{"title":"10 · Học không giám sát và K-means","content":"Chương4; chưa có lab riêng\n\nBÀI TẬP NHỎ\n\n1. Dữ liệu1D[1,2,8,9], tâm đầu1 và9,k=2: tính tâm sau bước cập nhật và SSE.\n\n2. Giải thích vì sao không chọn k chỉ bằng SSE nhỏ nhất và vì sao cần chuẩn hóa đặc trưng.\n\nTHỰC HÀNH\n\nCài k-means nhỏ từ đầu, có max_iter/tolerance/seed và quy tắc xử lý cụm rỗng. Kiểm chứng trên4 điểm, rồi thử dữ liệu2D tự tạo với vài seed. Báo tâm, nhãn cụm, SSE và biểu đồ thật. Nếu so sánh sklearn phải dùng điều kiện khởi tạo tương thích.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/ai-lab/10.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:8458238d-c85f-7e57-8f8b-5eabbee5cde7.pdf"},{"title":"Tuan1_Gioi thieu Python.docx.pdf","type":"PDF","url":"vedu-file:1f40cf0c-bdd4-508c-d43d-125397bdc345.pdf"},{"title":"Tuan2_Tim kiem theo AKT và A-star.pdf","type":"PDF","url":"vedu-file:8d9550fc-3a2c-5b18-2235-f77bbb65df10.pdf"},{"title":"Tuan3_Tim kiem doi khang.docx (1).pdf","type":"PDF","url":"vedu-file:3900c847-55ec-fb07-f1c9-a86c13fe5454.pdf"},{"title":"Nhập môn Trí tuệ nhân tạo - Trần Sỹ Hoàng","type":"LINK","url":"https://www.youtube.com/playlist?list=PLQTSNYJ7ollTV1JNmJcF4QD7xskd5HZxr"},{"title":"Python cơ bản - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1xczCv2BA0SaNJHu_VXsFtg"},{"title":"Machine learning cơ bản với Python - HowKteam","type":"LINK","url":"https://www.youtube.com/playlist?list=PL33lvabfss1zLDVHXW_YUJxhxBFap-vm_"},{"title":"AIMA Python","type":"LINK","url":"https://aimacode.github.io/aima-python/"}]}],"questions":[{"text":"BFS thường tối ưu tiêu chí nào khi cạnh có cùng chi phí?","options":["Số cạnh trên đường đi","Tổng trọng số âm","Số đỉnh trong toàn đồ thị","Bộ nhớ nhỏ nhất"],"correct":0},{"text":"UCS chọn nút tiếp theo theo gì?","options":["Chi phí tích lũy nhỏ nhất","Tên đỉnh tăng dần","Heuristic lớn nhất","Độ sâu lớn nhất"],"correct":0},{"text":"Trong A*, f(n) được tính thế nào?","options":["g(n) + h(n)","g(n) - h(n)","g(n) nhân h(n)","Chỉ bằng h(n)"],"correct":0},{"text":"Giá trị minimax tại gốc MAX có hai nút MIN chứa (3,5) và (2,9)?","options":["3","9","2","5"],"correct":0},{"text":"Tam giác cần ít nhất bao nhiêu màu để hai đỉnh kề khác màu?","options":["3","1","2","6"],"correct":0},{"text":"Với TP=8, FP=2, precision bằng bao nhiêu?","options":["0,8","0,2","0,5","1,0"],"correct":0},{"text":"K-means sử dụng nhãn lớp khi huấn luyện không?","options":["Không, đó là thuật toán gom cụm","Có, luôn cần nhãn lớp","Chỉ dùng nhãn test","Chỉ dùng nhãn có xác suất lớn"],"correct":0},{"text":"Một thuật toán ngẫu nhiên cho nghiệm tốt ở một lần chạy chứng minh gì?","options":["Chỉ là kết quả lần chạy đó; cần đánh giá thêm","Luôn tìm được tối ưu","Không cần ghi seed","Đã chứng minh mọi trường hợp"],"correct":0}]},{"key":"network-admin-lab","name":"Thực hành quản trị hệ thống mạng","topic":"Mạng máy tính","marker":"[VEDU-CURATED-v202611:network-admin-lab]","summary":"Khóa tự học Thực hành quản trị hệ thống mạng theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Sinh viên biết TCP/IP, Windows Server, AD DS và máy ảo","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Thực hành quản trị hệ thống mạng theo học liệu nhóm cung cấp, gồm 10 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nSinh viên biết TCP/IP, Windows Server, AD DS và máy ảo\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 10 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. DHCP nâng cao\n2. DNS nâng cao\n3. IPAM\n4. iSCSI và MPIO\n5. File Classification Infrastructure\n6. BranchCache\n7. Dynamic Access Control\n8. Work Folders\n9. Child domain và forest trust\n10. AD Sites, Subnets và Replication\n\nNGUỒN\nVEDU_THQuanTriHeThongMang.zip\nMCSA Tiếng Việt https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB\nMicrosoft: Windows Server2012/R2 end of support https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support\nMicrosoft: Install IPAM Server (2012/R2) https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)\nCTĐT An toàn thông tin2022 HUIT https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/network-admin-lab/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab01-Ex01-Configuring Advanced DHCP Settings-Template.pdf","type":"PDF","url":"vedu-file:36af74d6-5d23-0671-9bb3-aa8ad621f19a.pdf"},{"title":"20412D-Lab01-Ex02-Configuring Advanced DNS Settings-Template.pdf","type":"PDF","url":"vedu-file:837a3e29-17e3-a575-c56d-259bf50557fa.pdf"},{"title":"20412D-Lab01-Ex03-Configuring IPAM-Template.pdf","type":"PDF","url":"vedu-file:cb777041-1d9e-a5aa-73f5-f7fc2b6ad591.pdf"},{"title":"20412D-Lab02A-Ex01-Configuring iSCSI Storage-Template.pdf","type":"PDF","url":"vedu-file:76f23f2d-d8ef-65ce-7447-7e687a0e7506.pdf"},{"title":"20412D-Lab02A-Ex02-Configuring the File Classification Infrastructure-Template.pdf","type":"PDF","url":"vedu-file:4913584c-daf6-c210-ce8f-6ea0207c68b2.pdf"},{"title":"20412D-Lab02B-Ex01-Configuring the Main Office Servers for BranchCache-Template.pdf","type":"PDF","url":"vedu-file:284cbf2e-1ec9-93ea-041f-8b9cdb512cce.pdf"},{"title":"20412D-Lab02B-Ex02-Configuring the Branch Office Servers for BranchCache-Template.pdf","type":"PDF","url":"vedu-file:60e12548-458a-a3f6-a4f0-d285c78213b3.pdf"},{"title":"20412D-Lab02B-Ex03-Configuring Client Computers for BranchCache-Template.pdf","type":"PDF","url":"vedu-file:d24387d1-1f12-a7e6-48ef-6b760458b4f5.pdf"},{"title":"20412D-Lab02B-Ex04-Monitoring BranchCache-Template.pdf","type":"PDF","url":"vedu-file:c83acebb-867e-7745-8a22-f310f744fa53.pdf"},{"title":"20412D-Lab03-Ex01-Preparing for DAC Deployment-Template.pdf","type":"PDF","url":"vedu-file:7d0fa5bc-64fc-cbe8-1d3f-6c235e10fdef.pdf"},{"title":"20412D-Lab03-Ex02-Implementing DAC-Template.pdf","type":"PDF","url":"vedu-file:6acd7d65-9502-93c5-1e0d-8e01ed46c195.pdf"},{"title":"20412D-Lab03-Ex03-Validating and Remediating DAC-Template.pdf","type":"PDF","url":"vedu-file:1e0079e7-fd4b-2998-9503-e19375e45102.pdf"},{"title":"20412D-Lab03-Ex04-Implementing Work Folders-Template.pdf","type":"PDF","url":"vedu-file:b0bdea07-2c78-72a1-f597-868c5524f5f5.pdf"},{"title":"20412D-Lab04-Ex01-Implementing Child Domains in AD DS-Template.pdf","type":"PDF","url":"vedu-file:b8f38173-520d-7cac-e97b-f0ae93a5fc4f.pdf"},{"title":"20412D-Lab04-Ex02-Implementing Forest Trusts-Template.pdf","type":"PDF","url":"vedu-file:643c2ac1-919a-78a4-8a0b-a28147cb0607.pdf"},{"title":"20412D-Lab05-Ex01-Modifying the Default Site-Template.pdf","type":"PDF","url":"vedu-file:1097cfe2-234a-4ad5-b906-8c896a5a8eb4.pdf"},{"title":"20412D-Lab05-Ex02-Creating Additional Sites and Subnets-Template.pdf","type":"PDF","url":"vedu-file:91446aef-e087-58c4-5368-aa211dacc1c8.pdf"},{"title":"20412D-Lab05-Ex03-Configuring AD DS Replication-Template.pdf","type":"PDF","url":"vedu-file:fefead45-2c94-395c-8a6f-c12c819c9625.pdf"},{"title":"20412D-Lab05-Ex04-Monitoring and Troubleshooting AD DS Replication-Template.pdf","type":"PDF","url":"vedu-file:06a800e3-051f-3355-7ba0-c1cde0e4e3c3.pdf"}]},{"title":"01 · DHCP nâng cao","content":"BÀI TẬP NHỎ\n\n1. Phân biệt scope, superscope, exclusion và reservation. Vì sao superscope không tự tạo định tuyến giữa các subnet?\n\n2. Với dải192.168.0.50–192.168.0.100, có bao nhiêu địa chỉ tính cả hai đầu? Nếu loại.60–.69 thì còn bao nhiêu, chưa tính reservation?\n\nTHỰC HÀNH\n\nThực hiện các task superscope, name protection và failover theo PDF gốc. Ghi cấu hình hai DHCP partner, scope được đồng bộ, lease phía client. Trong mạng lab cô lập, dừng dịch vụ một partner theo kế hoạch, kiểm tra cấp/gia hạn lease và phục hồi; ghi trạng thái/timing thay vì kết luận chỉ từ ping.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab01-Ex01-Configuring Advanced DHCP Settings-Template.pdf","type":"PDF","url":"vedu-file:36af74d6-5d23-0671-9bb3-aa8ad621f19a.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"02 · DNS nâng cao","content":"BÀI TẬP NHỎ\n\n1. Giải thích DNSSEC bảo vệ tính xác thực/toàn vẹn dữ liệu DNS; có mã hóa nội dung truy vấn không?\n\n2. Phân biệt zone thông thường, GlobalNames, cache locking và socket pool; nêu mục tiêu của từng cơ chế.\n\nTHỰC HÀNH\n\nLập bảng trước/sau cho4 task DNSSEC, socket pool, cache locking, GlobalNames. Với DNSSEC, kiểm tra cấu hình ký zone và đường xác thực/trust anchor của resolver/client theo lab; không coi một lần resolve thành công là chứng minh validation. Nộp cấu hình, lệnh truy vấn, kết quả và diễn giải.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab01-Ex02-Configuring Advanced DNS Settings-Template.pdf","type":"PDF","url":"vedu-file:837a3e29-17e3-a575-c56d-259bf50557fa.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"03 · IPAM","content":"BÀI TẬP NHỎ\n\n1. Phân biệt IPAM với DHCP: dịch vụ nào cấp lease? Liệt kê dữ liệu IPAM thu thập/quản lý.\n\n2. IPAM hiển thị access blocked: đề xuất thứ tự kiểm tra discovery scope, GPO, quyền, firewall và refresh thay vì tắt toàn bộ firewall.\n\nTHỰC HÀNH\n\nCài IPAM trên member server phù hợp, cấu hình provisioning và discovery theo PDF. Ghi một server từ trạng thái blocked sang managed/access được; quản lý một block, một scope và reservation. Nộp bằng chứng quyền/GPO và dữ liệu lấy lại sau refresh, không chỉ ảnh cài feature xong.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab01-Ex03-Configuring IPAM-Template.pdf","type":"PDF","url":"vedu-file:cb777041-1d9e-a5aa-73f5-f7fc2b6ad591.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"04 · iSCSI và MPIO","content":"BÀI TẬP NHỎ\n\n1. Phân biệt target, initiator, virtual disk/LUN và MPIO. MPIO có thay thế backup không?\n\n2. Nêu khác biệt giữa lưu trữ block qua iSCSI với chia sẻ file SMB. Vì sao không tùy tiện mount ghi cùng một LUN trên hai máy độc lập?\n\nTHỰC HÀNH\n\nTạo virtual disk5GB theo lab, giới hạn initiator và kết nối trên máy được chỉ định. Kiểm tra disk trước khi initialize/format để tránh nhầm ổ. Nếu có đủ hai đường độc lập, cấu hình MPIO và kiểm tra mất một đường trong lab; nếu chỉ có một đường, ghi chưa kiểm chứng khả năng dự phòng. Nộp sơ đồ, session/path và thử ghi/đọc file.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab02A-Ex01-Configuring iSCSI Storage-Template.pdf","type":"PDF","url":"vedu-file:76f23f2d-d8ef-65ce-7447-7e687a0e7506.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"05 · File Classification Infrastructure","content":"BÀI TẬP NHỎ\n\n1. Phân biệt classification property, classification rule, file management task và file screening.\n\n2. Thiết kế3 file mẫu: khớp điều kiện, không khớp, thiếu thông tin. Dự đoán thuộc tính phân loại cho từng file.\n\nTHỰC HÀNH\n\nDùng bản sao dữ liệu thử: tạo property/rule và chạy classification theo PDF; lập bảng expected/actual. Thử file expiration trên thư mục lab riêng, ghi đường dẫn đích và kiểm tra khả năng tìm lại file. Nộp rule, báo cáo chạy task và bảng file trước/sau.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab02A-Ex02-Configuring the File Classification Infrastructure-Template.pdf","type":"PDF","url":"vedu-file:4913584c-daf6-c210-ce8f-6ea0207c68b2.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"06 · BranchCache","content":"BÀI TẬP NHỎ\n\n1. Phân biệt hosted cache với distributed cache. Nêu vai trò content server, cache server và client.\n\n2. Vì sao lần mở file thứ hai nhanh hơn chưa đủ chứng minh BranchCache hoạt động? Cần thu thập counter nào theo lab?\n\nTHỰC HÀNH\n\nTriển khai đủ4 PDF: main office, branch office, clients và monitoring. Đọc cùng file trên hai client theo trình tự lab, thu counter/cache statistics và thời gian thực đo trước/sau. Nếu dùng mô phỏng đường truyền chậm, ghi cấu hình và phục hồi. Nộp bảng đo, không tự đặt mức tăng tốc.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab02B-Ex01-Configuring the Main Office Servers for BranchCache-Template.pdf","type":"PDF","url":"vedu-file:284cbf2e-1ec9-93ea-041f-8b9cdb512cce.pdf"},{"title":"20412D-Lab02B-Ex02-Configuring the Branch Office Servers for BranchCache-Template.pdf","type":"PDF","url":"vedu-file:60e12548-458a-a3f6-a4f0-d285c78213b3.pdf"},{"title":"20412D-Lab02B-Ex03-Configuring Client Computers for BranchCache-Template.pdf","type":"PDF","url":"vedu-file:d24387d1-1f12-a7e6-48ef-6b760458b4f5.pdf"},{"title":"20412D-Lab02B-Ex04-Monitoring BranchCache-Template.pdf","type":"PDF","url":"vedu-file:c83acebb-867e-7745-8a22-f310f744fa53.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"07 · Dynamic Access Control","content":"BÀI TẬP NHỎ\n\n1. Phân biệt user/device claims, resource properties, central access rule và central access policy.\n\n2. Lập ma trận4 tình huống theo department người dùng và phân loại file; dự đoán quyền đọc, nêu thêm ảnh hưởng share/NTFS permissions.\n\nTHỰC HÀNH\n\nThực hiện chuẩn bị claims/phân loại, triển khai policy rồi xác minh bằng user được phép và không được phép. Ghi effective access, kết quả đăng nhập mới nếu claims cần cập nhật, và access-denied remediation. Nộp ma trận quyền/ảnh/log; không dùng tài khoản admin để thay mọi kiểm tra người dùng.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab03-Ex01-Preparing for DAC Deployment-Template.pdf","type":"PDF","url":"vedu-file:7d0fa5bc-64fc-cbe8-1d3f-6c235e10fdef.pdf"},{"title":"20412D-Lab03-Ex02-Implementing DAC-Template.pdf","type":"PDF","url":"vedu-file:6acd7d65-9502-93c5-1e0d-8e01ed46c195.pdf"},{"title":"20412D-Lab03-Ex03-Validating and Remediating DAC-Template.pdf","type":"PDF","url":"vedu-file:1e0079e7-fd4b-2998-9503-e19375e45102.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"08 · Work Folders","content":"BÀI TẬP NHỎ\n\n1. Phân biệt đồng bộ file với backup. File xóa hoặc thay đổi có thể lan truyền thế nào?\n\n2. Liệt kê tên DNS, chứng chỉ, quyền và tài khoản cần kiểm tra khi client không kết nối được HTTPS.\n\nTHỰC HÀNH\n\nTạo sync share theo lab và kết nối client bằng tài khoản thử. Tạo file, thay đổi nội dung và kiểm tra đồng bộ hai chiều theo cấu hình hỗ trợ. Ghi timestamp/hash hoặc nội dung trước/sau và xử lý lỗi chứng chỉ bằng trust/name đúng; không xem việc bỏ kiểm tra TLS là hoàn thành.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab03-Ex04-Implementing Work Folders-Template.pdf","type":"PDF","url":"vedu-file:b0bdea07-2c78-72a1-f597-868c5524f5f5.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"09 · Child domain và forest trust","content":"BÀI TẬP NHỎ\n\n1. Phân biệt child domain, domain tree và forest. Trust mặc định parent-child có giống mọi forest trust không?\n\n2. Vẽ chiều trust: forest tài nguyên A tin forest tài khoản B. Người dùng bên nào có khả năng được cấp quyền truy cập tài nguyên bên nào?\n\nTHỰC HÀNH\n\nTriển khai child domain trong forest lab, xác minh trust mặc định; ở bài forest trust, chuẩn bị forest thứ hai, DNS resolution và selective authentication. Thử user có và không có Allowed to authenticate cùng quyền tài nguyên phù hợp. Nộp sơ đồ chiều trust và ma trận truy cập, không coi tạo trust xong là đã có quyền file.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/09.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab04-Ex01-Implementing Child Domains in AD DS-Template.pdf","type":"PDF","url":"vedu-file:b8f38173-520d-7cac-e97b-f0ae93a5fc4f.pdf"},{"title":"20412D-Lab04-Ex02-Implementing Forest Trusts-Template.pdf","type":"PDF","url":"vedu-file:643c2ac1-919a-78a4-8a0b-a28147cb0607.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]},{"title":"10 · AD Sites, Subnets và Replication","content":"BÀI TẬP NHỎ\n\n1. Phân biệt domain với site; giải thích subnet-to-site mapping. Đổi tên site có đổi tên domain không?\n\n2. Phân biệt site-link cost, schedule và replication interval. Lệnh báo RPC unavailable có đủ chứng minh nguyên nhân là DNS không?\n\nTHỰC HÀNH\n\nTriển khai4 PDF module5: thêm DC, sites/subnets, site links, kiểm tra replication. Tạo đối tượng thử và xác minh xuất hiện trên DC khác, ghi thời gian. Script Mod05Ex4.ps1 không có trong ZIP: không đoán nội dung hoặc chạy bản tải không rõ nguồn; thay bằng bài chẩn đoán một DC lab tạm ngắt mạng, ghi rõ là bài bổ sung rồi phục hồi và kiểm tra hội tụ.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/network-admin-lab/10.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:5dac8464-9bb3-3366-9212-cf48510ab87c.pdf"},{"title":"20412D-Lab05-Ex01-Modifying the Default Site-Template.pdf","type":"PDF","url":"vedu-file:1097cfe2-234a-4ad5-b906-8c896a5a8eb4.pdf"},{"title":"20412D-Lab05-Ex02-Creating Additional Sites and Subnets-Template.pdf","type":"PDF","url":"vedu-file:91446aef-e087-58c4-5368-aa211dacc1c8.pdf"},{"title":"20412D-Lab05-Ex03-Configuring AD DS Replication-Template.pdf","type":"PDF","url":"vedu-file:fefead45-2c94-395c-8a6f-c12c819c9625.pdf"},{"title":"20412D-Lab05-Ex04-Monitoring and Troubleshooting AD DS Replication-Template.pdf","type":"PDF","url":"vedu-file:06a800e3-051f-3355-7ba0-c1cde0e4e3c3.pdf"},{"title":"MCSA Tiếng Việt","type":"LINK","url":"https://www.youtube.com/playlist?list=PLTpnojrd-61fPoALBxs7zW7-zaJN71nxB"},{"title":"Microsoft: Windows Server2012/R2 end of support","type":"LINK","url":"https://learn.microsoft.com/lifecycle/announcements/windows-server-2012-r2-end-of-support"},{"title":"Microsoft: Install IPAM Server (2012/R2)","type":"LINK","url":"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/jj878315(v=ws.11)"},{"title":"CTĐT An toàn thông tin2022 HUIT","type":"LINK","url":"https://huit.edu.vn/Images/Documents/N00CT/2022_ctdt-phu-luc-nganh-an-toan-thong-tin_1235_05092022_7480202.pdf"}]}],"questions":[{"text":"DHCP reservation nhằm mục đích gì?","options":["Gắn địa chỉ dự kiến cho client theo định danh cấu hình","Tự mã hóa mọi gói tin","Thay thế DNS","Cấp cùng một IP cho mọi máy"],"correct":0},{"text":"Dải .50 đến .100 tính cả hai đầu có bao nhiêu địa chỉ?","options":["51","50","49","100"],"correct":0},{"text":"DNS chủ yếu cung cấp chức năng nào?","options":["Phân giải tên và các bản ghi liên quan","Cấp mọi địa chỉ IP động","Nén file người dùng","Thay thế mật khẩu"],"correct":0},{"text":"Lab quản trị hệ thống nên thực hiện ở đâu?","options":["Mạng máy ảo cô lập được cho phép","Mạng sản xuất bất kỳ không xin phép","Máy cá nhân của người khác","Internet bằng quét ngẫu nhiên"],"correct":0},{"text":"Chỉ ping thành công đủ xác nhận DHCP failover chưa?","options":["Chưa, cần kiểm tra lease, trạng thái và phục hồi","Đủ trong mọi tình huống","Đủ nếu cùng subnet","Đủ nếu tên máy đúng"],"correct":0},{"text":"AD DS replication liên quan đến gì?","options":["Đồng bộ dữ liệu thư mục giữa domain controller","Sao chép mọi file video","Tự tạo tài khoản admin công khai","Thay thế mọi bản sao lưu"],"correct":0},{"text":"Kiểm tra quyền truy cập nên dùng tài khoản nào?","options":["Tài khoản thử có đúng nhóm quyền của tình huống","Luôn dùng Domain Admin cho mọi ca","Không cần đăng nhập","Chỉ kiểm tra tên thư mục"],"correct":0},{"text":"Kết quả lab nên ghi những gì?","options":["Cấu hình, bước kiểm chứng, kết quả thực và cách phục hồi","Chỉ ảnh màn hình thành công","Mật khẩu quản trị thật","Kết luận theo suy đoán"],"correct":0}]},{"key":"systems-lab","name":"Thực hành phân tích thiết kế hệ thống","topic":"Lập trình & Phát triển phần mềm","marker":"[VEDU-CURATED-v202611:systems-lab]","summary":"Khóa tự học Thực hành phân tích thiết kế hệ thống theo học liệu nhóm cung cấp, gồm 6 bài, bài tập và bài kiểm tra kiến thức cuối khóa.","preparation":"Kiến thức CNTT nền tảng và máy tính để thực hành.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nKhóa tự học Thực hành phân tích thiết kế hệ thống theo học liệu nhóm cung cấp, gồm 6 bài, bài tập và bài kiểm tra kiến thức cuối khóa.\n\nCHUẨN BỊ\nKiến thức CNTT nền tảng và máy tính để thực hành.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 6 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Khảo sát và mô hình nghiệp vụ\n2. Đối tượng nghiệp vụ, tuần tự và cộng tác\n3. Use case hệ thống và đặc tả\n4. Class diagram mức phân tích\n5. Tinh chế lớp và thiết kế dữ liệu\n6. Thiết kế chức năng ba tầng và bàn giao\n\nNGUỒN\nVEDU_Thực Hành Phân Tích Thiết Kế hệ thống.zip\ndraw.io - Use case diagrams https://www.drawio.com/docs/diagram-types/uml/use-case-diagrams/\nVisual Paradigm - Communication diagram https://www.visual-paradigm.com/tutorials/how-to-draw-communication-diagram.jsp\nOMG - UML 2.5.1 https://www.omg.org/spec/UML/2.5.1\nMicrosoft Learn - Filtered indexes https://learn.microsoft.com/en-us/sql/relational-databases/indexes/create-filtered-indexes?view=sql-server-ver17\nPhân tích thiết kế hệ thống — 10 bài https://www.youtube.com/playlist?list=PLVrHxivsV5nw7RErJ6eabmG_s7cAuvK0e\nPhân tích và thiết kế hệ thống — 9 video https://www.youtube.com/playlist?list=PLTREaQuki_OwAanKXxz5S5aCWbNS0jEgD\nUML — 15 video https://www.youtube.com/playlist?list=PLyxSzL3F7485EM8TCwTmZ7UnUbdRSUtXT\nActivity và đặc tả Use Case https://www.youtube.com/watch?v=Ir0OziDEudc\nLý thuyết sơ đồ tuần tự https://www.youtube.com/watch?v=0JRT2mMvaww\nPhân tích và vẽ sơ đồ lớp https://www.youtube.com/watch?v=lT5A6-Lg_QI\nUse Case và ví dụ https://www.youtube.com/watch?v=95U5gmR935g\nMô hình miền Domain Model https://www.youtube.com/watch?v=K6hfnVZ3X1A\nChuyển Class Diagram sang lược đồ quan hệ https://www.youtube.com/watch?v=PeNh8gvjfKc\nPhân tích và thiết kế sơ đồ tuần tự https://www.youtube.com/watch?v=KzOiOPglyso\nCài đặt Visual Paradigm Community https://www.youtube.com/watch?v=kaNa_yvGp0M\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/systems-lab/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:9bfda62f-30b5-6ff4-41f3-d2a31664d398.pdf"},{"title":"61. 01201063_Chi tiet_Thuc hanh Phan tich thiet ke he thong_Final.pdf","type":"PDF","url":"vedu-file:fedd6a93-89d2-cb00-3a92-ba2b9e179499.pdf"},{"title":"Bai giang TH PTTK HT_14DHTH.pdf","type":"PDF","url":"vedu-file:05e207b6-3812-6e81-1b4d-e464def11d6e.pdf"}]},{"title":"01 · Khảo sát và mô hình nghiệp vụ","content":"Xác định biên tổ chức là thư viện: độc giả là business actor; thủ thư là business worker trong biên nghiệp vụ. Khi chuyển sang phần mềm, thủ thư trở thành system actor. Không dùng cùng một biên cho cả hai sơ đồ.\n\nPDF trang 2–17; bài tập gốc chương 1 ở trang 31–36.\n\nTình huống luyện tập: TÌNH HUỐNG TỰ BIÊN SOẠN: Thư viện quản lý độc giả, đầu sách, từng cuốn sách vật lý, phiếu mượn và chi tiết mượn. Một đầu sách có nhiều cuốn; mỗi cuốn có mã duy nhất. Độc giả xuất trình thẻ, thủ thư kiểm tra thẻ đang hoạt động và chưa hết hạn tại ngày mượn, rồi chọn các cuốn. Mỗi phiếu có từ 1 đến 3 cuốn khác nhau; tổng số cuốn chưa trả của một độc giả không vượt quá 3. Chỉ cuốn không có lượt mượn chưa trả và còn sử dụng mới được mượn. Hạn trả là 14 ngày sau ngày mượn. Được trả từng cuốn, lưu thời điểm trả ở từng chi tiết. Thủ thư lập phiếu và ghi nhận trả; độc giả chỉ yêu cầu phục vụ tại quầy, chưa có tài khoản web. Quản trị quản lý tài khoản thủ thư. Không xét phí phạt, đặt chỗ, gia hạn hoặc mất sách. Thời điểm do máy chủ ghi nhận. Các quy tắc này dùng cho bài bổ sung, không thay thế tình huống gốc trong bài giảng.\n\nBÀI TẬP NHỎ\n\n1. Lập bảng 8 thuật ngữ và 5 quy tắc từ tình huống; phân biệt đầu sách với cuốn sách.\n\n2. Vẽ business use case Mượn sách và Trả sách; lập bảng vai trò Độc giả/Thủ thư/Quản trị.\n\nTHỰC HÀNH\n\nViết khảo sát giả lập 1–2 trang và vẽ business use case, activity có swimlane cho Mượn sách, có nhánh thẻ không hợp lệ, vượt giới hạn, cuốn không khả dụng. Gắn từng nhánh với một quy tắc.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems-lab/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:9bfda62f-30b5-6ff4-41f3-d2a31664d398.pdf"},{"title":"61. 01201063_Chi tiet_Thuc hanh Phan tich thiet ke he thong_Final.pdf","type":"PDF","url":"vedu-file:fedd6a93-89d2-cb00-3a92-ba2b9e179499.pdf"},{"title":"Bai giang TH PTTK HT_14DHTH.pdf","type":"PDF","url":"vedu-file:05e207b6-3812-6e81-1b4d-e464def11d6e.pdf"},{"title":"draw.io - Use case diagrams","type":"LINK","url":"https://www.drawio.com/docs/diagram-types/uml/use-case-diagrams/"},{"title":"Visual Paradigm - Communication diagram","type":"LINK","url":"https://www.visual-paradigm.com/tutorials/how-to-draw-communication-diagram.jsp"},{"title":"OMG - UML 2.5.1","type":"LINK","url":"https://www.omg.org/spec/UML/2.5.1"},{"title":"Microsoft Learn - Filtered indexes","type":"LINK","url":"https://learn.microsoft.com/en-us/sql/relational-databases/indexes/create-filtered-indexes?view=sql-server-ver17"}]},{"title":"02 · Đối tượng nghiệp vụ, tuần tự và cộng tác","content":"Ở mức nghiệp vụ dùng người thực hiện và thực thể như phiếu mượn, chưa đưa Repository hoặc SQL vào quy trình tổ chức. Sơ đồ cộng tác cần số thứ tự thông điệp và phải nhất quán với sơ đồ tuần tự.\n\nPDF trang 18–31; áp dụng tình huống gốc ở trang 31–36.\n\nTình huống luyện tập: TÌNH HUỐNG TỰ BIÊN SOẠN: Thư viện quản lý độc giả, đầu sách, từng cuốn sách vật lý, phiếu mượn và chi tiết mượn. Một đầu sách có nhiều cuốn; mỗi cuốn có mã duy nhất. Độc giả xuất trình thẻ, thủ thư kiểm tra thẻ đang hoạt động và chưa hết hạn tại ngày mượn, rồi chọn các cuốn. Mỗi phiếu có từ 1 đến 3 cuốn khác nhau; tổng số cuốn chưa trả của một độc giả không vượt quá 3. Chỉ cuốn không có lượt mượn chưa trả và còn sử dụng mới được mượn. Hạn trả là 14 ngày sau ngày mượn. Được trả từng cuốn, lưu thời điểm trả ở từng chi tiết. Thủ thư lập phiếu và ghi nhận trả; độc giả chỉ yêu cầu phục vụ tại quầy, chưa có tài khoản web. Quản trị quản lý tài khoản thủ thư. Không xét phí phạt, đặt chỗ, gia hạn hoặc mất sách. Thời điểm do máy chủ ghi nhận. Các quy tắc này dùng cho bài bổ sung, không thay thế tình huống gốc trong bài giảng.\n\nBÀI TẬP NHỎ\n\n1. Tạo object diagram ví dụ: dg01:DocGia, pm01:PhieuMuon, ct01:ChiTietMuon, c01:CuonSach; gán giá trị minh họa và các liên kết.\n\n2. Viết danh sách 6–8 thông điệp của kịch bản mượn hợp lệ, đánh số rồi chuyển sang sơ đồ cộng tác.\n\nTHỰC HÀNH\n\nVẽ object diagram, sequence nghiệp vụ và collaboration/communication cho cùng một kịch bản mượn hai cuốn. Nộp bảng đối chiếu thông điệp giữa hai sơ đồ và một kịch bản từ chối.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems-lab/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:9bfda62f-30b5-6ff4-41f3-d2a31664d398.pdf"},{"title":"61. 01201063_Chi tiet_Thuc hanh Phan tich thiet ke he thong_Final.pdf","type":"PDF","url":"vedu-file:fedd6a93-89d2-cb00-3a92-ba2b9e179499.pdf"},{"title":"Bai giang TH PTTK HT_14DHTH.pdf","type":"PDF","url":"vedu-file:05e207b6-3812-6e81-1b4d-e464def11d6e.pdf"},{"title":"draw.io - Use case diagrams","type":"LINK","url":"https://www.drawio.com/docs/diagram-types/uml/use-case-diagrams/"},{"title":"Visual Paradigm - Communication diagram","type":"LINK","url":"https://www.visual-paradigm.com/tutorials/how-to-draw-communication-diagram.jsp"},{"title":"OMG - UML 2.5.1","type":"LINK","url":"https://www.omg.org/spec/UML/2.5.1"},{"title":"Microsoft Learn - Filtered indexes","type":"LINK","url":"https://learn.microsoft.com/en-us/sql/relational-databases/indexes/create-filtered-indexes?view=sql-server-ver17"}]},{"title":"03 · Use case hệ thống và đặc tả","content":"Thủ thư tương tác với phần mềm để lập phiếu, ghi trả, quản lý độc giả và sách. Độc giả chỉ xuất trình thẻ tại quầy nên không tự động là actor của phần mềm trong phạm vi này. Đăng nhập có thể là tiền điều kiện; không bắt buộc chèn include/extend.\n\nPDF trang 37–42; phần bài tập bắt đầu ở trang 40.\n\nTình huống luyện tập: TÌNH HUỐNG TỰ BIÊN SOẠN: Thư viện quản lý độc giả, đầu sách, từng cuốn sách vật lý, phiếu mượn và chi tiết mượn. Một đầu sách có nhiều cuốn; mỗi cuốn có mã duy nhất. Độc giả xuất trình thẻ, thủ thư kiểm tra thẻ đang hoạt động và chưa hết hạn tại ngày mượn, rồi chọn các cuốn. Mỗi phiếu có từ 1 đến 3 cuốn khác nhau; tổng số cuốn chưa trả của một độc giả không vượt quá 3. Chỉ cuốn không có lượt mượn chưa trả và còn sử dụng mới được mượn. Hạn trả là 14 ngày sau ngày mượn. Được trả từng cuốn, lưu thời điểm trả ở từng chi tiết. Thủ thư lập phiếu và ghi nhận trả; độc giả chỉ yêu cầu phục vụ tại quầy, chưa có tài khoản web. Quản trị quản lý tài khoản thủ thư. Không xét phí phạt, đặt chỗ, gia hạn hoặc mất sách. Thời điểm do máy chủ ghi nhận. Các quy tắc này dùng cho bài bổ sung, không thay thế tình huống gốc trong bài giảng.\n\nBÀI TẬP NHỎ\n\n1. Vẽ use case hệ thống với Thủ thư và Quản trị, ít nhất 6 use case; giải thích vai trò Độc giả.\n\n2. Đặc tả UC-MUON: kích hoạt, tiền/hậu điều kiện, luồng chính và 4 ngoại lệ.\n\nTHỰC HÀNH\n\nNộp use case diagram toàn hệ thống, đặc tả Lập phiếu mượn và Ghi nhận trả từng cuốn. Viết 6 yêu cầu chức năng có mã và ánh xạ vào use case. Chỉ dùng include/extend khi đúng ngữ nghĩa.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems-lab/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:9bfda62f-30b5-6ff4-41f3-d2a31664d398.pdf"},{"title":"61. 01201063_Chi tiet_Thuc hanh Phan tich thiet ke he thong_Final.pdf","type":"PDF","url":"vedu-file:fedd6a93-89d2-cb00-3a92-ba2b9e179499.pdf"},{"title":"Bai giang TH PTTK HT_14DHTH.pdf","type":"PDF","url":"vedu-file:05e207b6-3812-6e81-1b4d-e464def11d6e.pdf"},{"title":"draw.io - Use case diagrams","type":"LINK","url":"https://www.drawio.com/docs/diagram-types/uml/use-case-diagrams/"},{"title":"Visual Paradigm - Communication diagram","type":"LINK","url":"https://www.visual-paradigm.com/tutorials/how-to-draw-communication-diagram.jsp"},{"title":"OMG - UML 2.5.1","type":"LINK","url":"https://www.omg.org/spec/UML/2.5.1"},{"title":"Microsoft Learn - Filtered indexes","type":"LINK","url":"https://learn.microsoft.com/en-us/sql/relational-databases/indexes/create-filtered-indexes?view=sql-server-ver17"}]},{"title":"04 · Class diagram mức phân tích","content":"Class diagram miền tập trung vào khái niệm dữ liệu, không trộn Form và Database vào đây. ChiTietMuon chứa hạn trả và ngày trả vì thư viện cho trả riêng từng cuốn. Bội số không diễn đạt được mọi điều kiện, cần ràng buộc văn bản.\n\nPDF trang 43–54; bài tập gốc ở trang 53–54.\n\nTình huống luyện tập: TÌNH HUỐNG TỰ BIÊN SOẠN: Thư viện quản lý độc giả, đầu sách, từng cuốn sách vật lý, phiếu mượn và chi tiết mượn. Một đầu sách có nhiều cuốn; mỗi cuốn có mã duy nhất. Độc giả xuất trình thẻ, thủ thư kiểm tra thẻ đang hoạt động và chưa hết hạn tại ngày mượn, rồi chọn các cuốn. Mỗi phiếu có từ 1 đến 3 cuốn khác nhau; tổng số cuốn chưa trả của một độc giả không vượt quá 3. Chỉ cuốn không có lượt mượn chưa trả và còn sử dụng mới được mượn. Hạn trả là 14 ngày sau ngày mượn. Được trả từng cuốn, lưu thời điểm trả ở từng chi tiết. Thủ thư lập phiếu và ghi nhận trả; độc giả chỉ yêu cầu phục vụ tại quầy, chưa có tài khoản web. Quản trị quản lý tài khoản thủ thư. Không xét phí phạt, đặt chỗ, gia hạn hoặc mất sách. Thời điểm do máy chủ ghi nhận. Các quy tắc này dùng cho bài bổ sung, không thay thế tình huống gốc trong bài giảng.\n\nBÀI TẬP NHỎ\n\n1. Đề xuất lớp và thuộc tính; giải thích vì sao ngày trả đặt ở ChiTietMuon.\n\n2. Ghi bội số hai đầu của DauSach–CuonSach, DocGia–PhieuMuon, PhieuMuon–ChiTietMuon và CuonSach–ChiTietMuon.\n\nTHỰC HÀNH\n\nVẽ mô hình gồm DocGia, NhanVien, DauSach, CuonSach, PhieuMuon, ChiTietMuon. Ghi ít nhất 5 bất biến, kiểm tra bằng kịch bản mượn 2 cuốn rồi trả 1 cuốn.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems-lab/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:9bfda62f-30b5-6ff4-41f3-d2a31664d398.pdf"},{"title":"61. 01201063_Chi tiet_Thuc hanh Phan tich thiet ke he thong_Final.pdf","type":"PDF","url":"vedu-file:fedd6a93-89d2-cb00-3a92-ba2b9e179499.pdf"},{"title":"Bai giang TH PTTK HT_14DHTH.pdf","type":"PDF","url":"vedu-file:05e207b6-3812-6e81-1b4d-e464def11d6e.pdf"},{"title":"draw.io - Use case diagrams","type":"LINK","url":"https://www.drawio.com/docs/diagram-types/uml/use-case-diagrams/"},{"title":"Visual Paradigm - Communication diagram","type":"LINK","url":"https://www.visual-paradigm.com/tutorials/how-to-draw-communication-diagram.jsp"},{"title":"OMG - UML 2.5.1","type":"LINK","url":"https://www.omg.org/spec/UML/2.5.1"},{"title":"Microsoft Learn - Filtered indexes","type":"LINK","url":"https://learn.microsoft.com/en-us/sql/relational-databases/indexes/create-filtered-indexes?view=sql-server-ver17"}]},{"title":"05 · Tinh chế lớp và thiết kế dữ liệu","content":"Chuyển 1–n thành khóa ngoại phía n. Với SQL Server, filtered unique index có thể chặn hai lượt mượn đang mở cho cùng cuốn. Giới hạn 3 cuốn và kiểm tra thẻ cần logic nghiệp vụ có giao dịch, không chỉ PK/FK.\n\nPDF trang 55–58; mục 4.2 của đề cương yêu cầu chuyển lớp thành bảng.\n\nTình huống luyện tập: TÌNH HUỐNG TỰ BIÊN SOẠN: Thư viện quản lý độc giả, đầu sách, từng cuốn sách vật lý, phiếu mượn và chi tiết mượn. Một đầu sách có nhiều cuốn; mỗi cuốn có mã duy nhất. Độc giả xuất trình thẻ, thủ thư kiểm tra thẻ đang hoạt động và chưa hết hạn tại ngày mượn, rồi chọn các cuốn. Mỗi phiếu có từ 1 đến 3 cuốn khác nhau; tổng số cuốn chưa trả của một độc giả không vượt quá 3. Chỉ cuốn không có lượt mượn chưa trả và còn sử dụng mới được mượn. Hạn trả là 14 ngày sau ngày mượn. Được trả từng cuốn, lưu thời điểm trả ở từng chi tiết. Thủ thư lập phiếu và ghi nhận trả; độc giả chỉ yêu cầu phục vụ tại quầy, chưa có tài khoản web. Quản trị quản lý tài khoản thủ thư. Không xét phí phạt, đặt chỗ, gia hạn hoặc mất sách. Thời điểm do máy chủ ghi nhận. Các quy tắc này dùng cho bài bổ sung, không thay thế tình huống gốc trong bài giảng.\n\nBÀI TẬP NHỎ\n\n1. Lập từ điển ít nhất 15 thuộc tính có kiểu dữ liệu, nullable và ràng buộc.\n\n2. Thiết kế PK/FK/UNIQUE cho PhieuMuon và ChiTietMuon; chỉ ra ràng buộc không thể hiện đủ bằng FK.\n\nTHỰC HÀNH\n\nNộp class diagram đã tinh chế, lược đồ quan hệ, script SQL Server tạo 6 bảng và một kịch bản kiểm thử. Nêu chiến lược ngăn hai thủ thư cùng cho mượn một cuốn hoặc làm độc giả vượt 3 cuốn.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems-lab/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:9bfda62f-30b5-6ff4-41f3-d2a31664d398.pdf"},{"title":"61. 01201063_Chi tiet_Thuc hanh Phan tich thiet ke he thong_Final.pdf","type":"PDF","url":"vedu-file:fedd6a93-89d2-cb00-3a92-ba2b9e179499.pdf"},{"title":"Bai giang TH PTTK HT_14DHTH.pdf","type":"PDF","url":"vedu-file:05e207b6-3812-6e81-1b4d-e464def11d6e.pdf"},{"title":"draw.io - Use case diagrams","type":"LINK","url":"https://www.drawio.com/docs/diagram-types/uml/use-case-diagrams/"},{"title":"Visual Paradigm - Communication diagram","type":"LINK","url":"https://www.visual-paradigm.com/tutorials/how-to-draw-communication-diagram.jsp"},{"title":"OMG - UML 2.5.1","type":"LINK","url":"https://www.omg.org/spec/UML/2.5.1"},{"title":"Microsoft Learn - Filtered indexes","type":"LINK","url":"https://learn.microsoft.com/en-us/sql/relational-databases/indexes/create-filtered-indexes?view=sql-server-ver17"}]},{"title":"06 · Thiết kế chức năng ba tầng và bàn giao","content":"Giao diện nhận thao tác; nghiệp vụ kiểm tra quy tắc; truy cập dữ liệu đọc/ghi. Sequence hiện thực hóa dùng đúng các lớp trong class diagram thiết kế. Khác với sequence nghiệp vụ ở TH02.\n\nPDF trang 56–63; bài tập hiện thực hóa ở trang 63.\n\nTình huống luyện tập: TÌNH HUỐNG TỰ BIÊN SOẠN: Thư viện quản lý độc giả, đầu sách, từng cuốn sách vật lý, phiếu mượn và chi tiết mượn. Một đầu sách có nhiều cuốn; mỗi cuốn có mã duy nhất. Độc giả xuất trình thẻ, thủ thư kiểm tra thẻ đang hoạt động và chưa hết hạn tại ngày mượn, rồi chọn các cuốn. Mỗi phiếu có từ 1 đến 3 cuốn khác nhau; tổng số cuốn chưa trả của một độc giả không vượt quá 3. Chỉ cuốn không có lượt mượn chưa trả và còn sử dụng mới được mượn. Hạn trả là 14 ngày sau ngày mượn. Được trả từng cuốn, lưu thời điểm trả ở từng chi tiết. Thủ thư lập phiếu và ghi nhận trả; độc giả chỉ yêu cầu phục vụ tại quầy, chưa có tài khoản web. Quản trị quản lý tài khoản thủ thư. Không xét phí phạt, đặt chỗ, gia hạn hoặc mất sách. Thời điểm do máy chủ ghi nhận. Các quy tắc này dùng cho bài bổ sung, không thay thế tình huống gốc trong bài giảng.\n\nBÀI TẬP NHỎ\n\n1. Phân công trách nhiệm cho LoanForm, LoanService, LoanRepository và các thực thể miền.\n\n2. Phác thảo giao diện mượn sách, thể hiện số đang mượn, danh sách cuốn, hạn trả và lỗi.\n\nTHỰC HÀNH\n\nNộp class diagram chi tiết và sequence cho Mượn sách, Trả từng cuốn; hai phác thảo giao diện, 6 ca kiểm thử và bảng FR→UC→lớp→bảng→test. Hoàn thiện báo cáo theo Word gốc, kèm nhật ký đóng góp nhóm.\n\nTỰ KIỂM TRA\n\nĐúng kiến thức và đầu ra: 4 điểm; xử lý biên/ngoại lệ: 2; kiểm thử có bằng chứng: 2; giải thích và nguồn: 2. Bài thực hành dùng luyện tập, chưa chấm sản phẩm tự động.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems-lab/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:9bfda62f-30b5-6ff4-41f3-d2a31664d398.pdf"},{"title":"61. 01201063_Chi tiet_Thuc hanh Phan tich thiet ke he thong_Final.pdf","type":"PDF","url":"vedu-file:fedd6a93-89d2-cb00-3a92-ba2b9e179499.pdf"},{"title":"Bai giang TH PTTK HT_14DHTH.pdf","type":"PDF","url":"vedu-file:05e207b6-3812-6e81-1b4d-e464def11d6e.pdf"},{"title":"draw.io - Use case diagrams","type":"LINK","url":"https://www.drawio.com/docs/diagram-types/uml/use-case-diagrams/"},{"title":"Visual Paradigm - Communication diagram","type":"LINK","url":"https://www.visual-paradigm.com/tutorials/how-to-draw-communication-diagram.jsp"},{"title":"OMG - UML 2.5.1","type":"LINK","url":"https://www.omg.org/spec/UML/2.5.1"},{"title":"Microsoft Learn - Filtered indexes","type":"LINK","url":"https://learn.microsoft.com/en-us/sql/relational-databases/indexes/create-filtered-indexes?view=sql-server-ver17"}]}],"questions":[{"text":"Trong bài toán thư viện, đầu sách và cuốn sách vật lý có quan hệ gì?","options":["Một đầu sách có thể có nhiều cuốn riêng biệt","Luôn là một đối tượng duy nhất","Mỗi cuốn có nhiều đầu sách cùng lúc","Không cần mã cuốn"],"correct":0},{"text":"Actor trong system use case là gì?","options":["Vai trò bên ngoài tương tác với hệ thống phần mềm","Mọi bảng trong database","Mọi lớp trong code","Chỉ quản trị viên"],"correct":0},{"text":"Activity diagram phù hợp để diễn đạt gì?","options":["Luồng hoạt động, quyết định và trách nhiệm","Chỉ danh sách bảng","Chỉ kiểu dữ liệu cột","Chỉ bố cục giao diện"],"correct":0},{"text":"Sequence diagram nhấn mạnh điều gì?","options":["Thứ tự tương tác giữa các đối tượng theo thời gian","Vị trí địa lý của người dùng","Chỉ quan hệ nhiều-nhiều","Chỉ số lượng trang"],"correct":0},{"text":"Khóa ngoại phục vụ mục đích gì?","options":["Bảo đảm quan hệ tham chiếu theo ràng buộc","Thay thế mọi quy tắc nghiệp vụ","Tự mã hóa dữ liệu","Tự cấp quyền truy cập"],"correct":0},{"text":"Muốn ngăn hai lượt mượn đang mở cùng một cuốn cần gì?","options":["Ràng buộc/giao dịch phù hợp và kiểm thử đồng thời","Chỉ ẩn nút trên giao diện","Chỉ đổi màu cuốn sách","Chỉ viết trong báo cáo"],"correct":0},{"text":"Truy vết yêu cầu giúp ích thế nào?","options":["Liên kết yêu cầu với mô hình, thiết kế và kiểm thử","Loại bỏ nhu cầu khảo sát","Tự chứng minh phần mềm không lỗi","Thay thế mọi sơ đồ"],"correct":0},{"text":"Khảo sát giả lập phải được trình bày thế nào?","options":["Ghi rõ giả lập và các giả định cần xác nhận","Ghi như phỏng vấn thực tế","Bỏ hết nguồn dữ liệu","Tự gán tên đơn vị khảo sát"],"correct":0}]},{"key":"word","name":"Word thực hành — Báo cáo và hồ sơ văn phòng","topic":"Tin học văn phòng","marker":"[VEDU-OFFICE-v1:word]","summary":"Tạo báo cáo nhóm, biên bản và hồ sơ có cấu trúc. Cần Word bản được cấp phép hoặc Writer miễn phí; các thao tác giao diện có thể khác nhau.","preparation":"Máy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nTạo báo cáo nhóm, biên bản và hồ sơ có cấu trúc. Cần Word bản được cấp phép hoặc Writer miễn phí; các thao tác giao diện có thể khác nhau.\n\nCHUẨN BỊ\nMáy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 7 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tạo tài liệu và quản lý phiên bản\n2. Cấu trúc báo cáo bằng Styles\n3. Thực hành: biên bản họp và bảng phân công\n4. Ôn tập: sửa năm lỗi thường gặp\n5. Thực hành có hướng dẫn tiếng Việt\n6. Dự án: hồ sơ đề xuất hoạt động nhóm\n7. Mở rộng: nhận xét và kiểm soát bản sửa\n\nNGUỒN\nTài liệu gốc và tham khảo trong sổ tự học.\nMicrosoft word - tài liệu tiếng Việt https://support.microsoft.com/vi-vn/word/\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/word/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"}]},{"title":"01 · Tạo tài liệu và quản lý phiên bản","content":"MỤC TIÊU\nTạo hồ sơ có thể tìm lại, mở lại và phân biệt bản sửa.\n\nTHỰC HIỆN\n1. Tạo thư mục BaoCaoNhom, bên trong có TaiLieuGoc, BanLamViec và BanNop.\n2. Trong Word/Writer tạo tài liệu có tên BaoCaoTienDo_v01, ghi ngày lập, người soạn và mục đích.\n3. Lưu bản làm việc ở định dạng chỉnh sửa; tạo bản xuất PDF riêng để gửi. Đóng rồi mở lại từ thư mục đã lưu.\n4. Sau khi sửa một đoạn, lưu thành v02 và viết một dòng nhật ký thay đổi. Không dùng tên chứa thông tin cá nhân nhạy cảm.\n\nTỰ KIỂM\nBạn có mở được đúng bản v02 mà không dựa vào danh sách Recent? PDF có mở được trên thiết bị khác?\n\nĐẦU RA\nMột thư mục gọn, hai phiên bản chỉnh sửa và một bản PDF. Bài tập được soạn riêng cho VEDU; đọc nguồn gốc bên dưới để đối chiếu thao tác.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTình huống Việt Nam: lập biên bản họp nhóm 3 người, bảng phân công có hạn nộp, báo cáo 3 mục bằng Heading, mục lục và bản PDF. Dùng tên và địa chỉ giả lập.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/word/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/word/"}]},{"title":"02 · Cấu trúc báo cáo bằng Styles","content":"BÀI TOÁN\nBáo cáo 6 trang thường bị lỗi mục lục nếu chỉ tăng cỡ chữ thủ công.\n\nTHỰC HIỆN\n1. Soạn ba phần: Mục tiêu, Kết quả, Kế hoạch tiếp theo. Áp Heading 1 cho các phần và Heading 2 cho hai mục nhỏ trong mỗi phần.\n2. Sửa kiểu Normal một lần để thống nhất nội dung, không bôi đen từng đoạn.\n3. Chèn ngắt trang trước phần Kết quả, đánh số trang và tạo mục lục tự động từ heading.\n4. Thêm một mục nhỏ rồi cập nhật mục lục; kiểm tra số trang.\n\nKIỂM TRA CHẤT LƯỢNG\nMục lục phải thay đổi khi cập nhật; các tiêu đề không được là đoạn Normal chỉ được tô đậm. Dùng Navigation/Outline để quan sát cấu trúc.\n\nĐẦU RA\nBáo cáo có cấu trúc, mục lục và số trang. Chưa cần thiết kế trang bìa cầu kỳ.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTình huống Việt Nam: lập biên bản họp nhóm 3 người, bảng phân công có hạn nộp, báo cáo 3 mục bằng Heading, mục lục và bản PDF. Dùng tên và địa chỉ giả lập.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/word/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/word/"}]},{"title":"03 · Thực hành: biên bản họp và bảng phân công","content":"TÌNH HUỐNG\nNhóm 3 người họp chuẩn bị ngày hội tuyển dụng. Cần biên bản để người vắng họp vẫn biết trách nhiệm.\n\nDỮ LIỆU BÀI TẬP\nAn: khảo sát 20 doanh nghiệp, hạn 20/10; Bình: làm poster, hạn 21/10; Chi: tổng hợp chi phí, hạn 22/10. Đây là nhân vật hư cấu phục vụ bài tập, không phải học viên thật.\n\nYÊU CẦU\nTạo bảng gồm Công việc, Phụ trách, Hạn, Trạng thái. Bên trên ghi thời gian, thành phần và ba quyết định họp. Cho hàng tiêu đề lặp lại nếu bảng sang trang. Không căn cột bằng phím Space.\n\nTỰ ĐÁNH GIÁ\nMỗi công việc phải có người chịu trách nhiệm và hạn; không có hàng bị cắt khó đọc. Xuất PDF và kiểm tra chữ tiếng Việt.\n\nĐẦU RA\nBienBanHop_v01.docx hoặc .odt và bản PDF.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTình huống Việt Nam: lập biên bản họp nhóm 3 người, bảng phân công có hạn nộp, báo cáo 3 mục bằng Heading, mục lục và bản PDF. Dùng tên và địa chỉ giả lập.","seconds":1500,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/word/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/word/"}]},{"title":"04 · Ôn tập: sửa năm lỗi thường gặp","content":"Tạo bản sao tài liệu rồi chủ động tạo 5 lỗi: tiêu đề dùng Normal, xuống trang bằng nhiều Enter, căn bảng bằng Space, ảnh không có mô tả và mục lục chưa cập nhật.\n\nVới mỗi lỗi, ghi ba cột: Dấu hiệu — Cách sửa — Cách kiểm chứng. Sau đó tự sửa trên bản sao. Không sửa/xóa file gốc duy nhất.\n\nĐáp án định hướng: dùng heading; dùng page break; dùng table/tab stop; bổ sung mô tả phù hợp; cập nhật trường mục lục. Việc đánh dấu đã đọc không thay thế đánh giá chất lượng sản phẩm.\n\nĐầu ra: bản sửa và checklist 5 dòng.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTình huống Việt Nam: lập biên bản họp nhóm 3 người, bảng phân công có hạn nộp, báo cáo 3 mục bằng Heading, mục lục và bản PDF. Dùng tên và địa chỉ giả lập.","seconds":600,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/word/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/word/"}]},{"title":"05 · Thực hành có hướng dẫn tiếng Việt","content":"Mở hướng dẫn Microsoft tiếng Việt trong mục Tài liệu. Xác định thanh lệnh, vùng làm việc, cách tạo và lưu tệp; thao tác lại trên máy rồi đóng và mở lại sản phẩm. Ghi 3 bước bằng lời của bạn, kèm một ảnh chụp không chứa dữ liệu cá nhân. Đối chiếu phiên bản phần mềm nếu giao diện khác tài liệu.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTình huống Việt Nam: lập biên bản họp nhóm 3 người, bảng phân công có hạn nộp, báo cáo 3 mục bằng Heading, mục lục và bản PDF. Dùng tên và địa chỉ giả lập.","seconds":282,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/word/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/word/"}]},{"title":"06 · Dự án: hồ sơ đề xuất hoạt động nhóm","content":"ĐỀ BÀI\nĐề xuất một buổi tập huấn kỹ năng số cho lớp hoặc phòng ban. Người nhận hồ sơ phải quyết định có phê duyệt hay không.\n\nSẢN PHẨM\nBáo cáo 4–6 trang gồm vấn đề, đối tượng, mục tiêu đo được, lịch hoạt động, bảng phân công, chi phí dự kiến và tài liệu tham khảo. Dùng dữ liệu tự tạo hoặc dữ liệu được phép sử dụng; ghi rõ phần giả định.\n\nCHECKLIST TỰ CHẤM /10\nCấu trúc heading/mục lục 2; thông tin đủ để ra quyết định 3; bảng rõ ràng 2; trình bày nhất quán 2; nguồn và phiên bản 1.\n\nCÁCH NỘP\nLưu file chỉnh sửa và PDF trong thư mục học tập của bạn; dùng Q&A để nhờ giảng viên nhận xét. Hiện ứng dụng chưa có chấm tự động sản phẩm Word, không nhận việc bấm hoàn thành là giảng viên đã chấm đạt.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTình huống Việt Nam: lập biên bản họp nhóm 3 người, bảng phân công có hạn nộp, báo cáo 3 mục bằng Heading, mục lục và bản PDF. Dùng tên và địa chỉ giả lập.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/word/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/word/"}]},{"title":"07 · Mở rộng: nhận xét và kiểm soát bản sửa","content":"Tạo bản sao hồ sơ. Bật theo dõi thay đổi, sửa hai đoạn và thêm một nhận xét yêu cầu làm rõ ngân sách. Kiểm tra bản hiển thị thay đổi và bản nội dung cuối trước khi chấp nhận/từ chối.\n\nKhông gửi hồ sơ thật hoặc thông tin riêng tư cho người lạ. Trong bài tập, trao đổi bản sao bằng kênh nội bộ đã được phép.\n\nĐầu ra: bảng nhật ký gồm người sửa, lý do và quyết định; một PDF cuối không còn nhận xét nội bộ ngoài ý muốn. Thử mở bằng Writer nếu không có Word, ghi lại điểm khác giao diện.\n\nTự kiểm: bản cuối có vô tình lộ nhận xét không? Người nhận có quyền chỉnh sửa quá mức cần thiết không?\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTình huống Việt Nam: lập biên bản họp nhóm 3 người, bảng phân công có hạn nộp, báo cáo 3 mục bằng Heading, mục lục và bản PDF. Dùng tên và địa chỉ giả lập.","seconds":1500,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/word/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:091b3c1b-1b35-050e-d699-b55a10981ec9.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/word/"}]}],"questions":[{"text":"Muốn mục lục tự cập nhật, cần làm gì?","options":["Dùng heading phù hợp và cập nhật mục lục","Chỉ tăng cỡ chữ tiêu đề"],"correct":0},{"text":"Cách tạo trang mới ổn định?","options":["Dùng ngắt trang","Nhấn Enter nhiều lần"],"correct":0},{"text":"Bản gửi để đọc trên nhiều máy nên kèm gì?","options":["PDF đã kiểm tra bố cục","Chỉ ảnh chụp màn hình"],"correct":0},{"text":"Nhận xét nội bộ trước khi bàn giao nên xử lý thế nào?","options":["Rà soát để tránh lộ thông tin ngoài ý muốn","Bỏ qua vì không ai có thể xem"],"correct":0},{"text":"Báo cáo dài cần mục lục cập nhật được. Nên dùng gì?","options":["Heading và mục lục tự động","Tăng cỡ chữ thủ công","Gõ số trang bằng tay","Chụp ảnh mục lục"],"correct":0},{"text":"Gửi hồ sơ chốt cho người chỉ cần đọc nên chọn gì?","options":["PDF đã kiểm tra bố cục","Chỉ file tạm chưa lưu","Mật khẩu email cá nhân","Ảnh mờ từng trang"],"correct":0},{"text":"Biên bản có 3 người phụ trách nên trình bày bằng gì?","options":["Bảng nhiệm vụ, người phụ trách, hạn và trạng thái","Một đoạn không xuống dòng","Ảnh chụp chat thay mọi dữ liệu","Chỉ danh sách tên"],"correct":0},{"text":"Trước khi gửi PDF cần làm gì?","options":["Mở lại kiểm tra chữ, trang, liên kết và dữ liệu nhạy cảm","Chỉ đổi đuôi tệp","Xóa file Word","Không cần kiểm tra"],"correct":0}]},{"key":"excel","name":"Excel thực hành — Quản lý chi phí và báo cáo bán hàng","topic":"Tin học văn phòng","marker":"[VEDU-OFFICE-v1:excel]","summary":"Làm bảng chi phí, công thức có tham chiếu, kiểm tra dữ liệu và báo cáo nhỏ. Có thể thực hành bằng Excel hoặc LibreOffice Calc.","preparation":"Máy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nLàm bảng chi phí, công thức có tham chiếu, kiểm tra dữ liệu và báo cáo nhỏ. Có thể thực hành bằng Excel hoặc LibreOffice Calc.\n\nCHUẨN BỊ\nMáy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 7 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Dữ liệu dạng bảng và kiểu dữ liệu\n2. Công thức, SUM và tham chiếu ô\n3. Thực hành: theo dõi ngân sách hoạt động\n4. Ôn tập: phát hiện lỗi bảng tính\n5. Thực hành có hướng dẫn tiếng Việt\n6. Dự án: báo cáo bán hàng mini có kiểm soát\n7. Mở rộng: tổng hợp theo nhóm và PivotTable\n\nNGUỒN\nTài liệu gốc và tham khảo trong sổ tự học.\nMicrosoft excel - tài liệu tiếng Việt https://support.microsoft.com/vi-vn/excel/\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/excel/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"}]},{"title":"01 · Dữ liệu dạng bảng và kiểu dữ liệu","content":"TẠO BẢNG\nNhập vào A1:D6 các cột: Mã, Mặt hàng, Số lượng, Đơn giá. Năm dòng lần lượt là SP01/Bút/12/5000; SP02/Vở/8/12000; SP03/Giấy/3/65000; SP04/Bìa/10/3000; SP05/Kẹp/5/15000. Các số liệu do VEDU tự tạo cho bài tập, không phải doanh số thật.\n\nNGUYÊN TẮC\nMột hàng là một bản ghi, một cột là một thuộc tính. Không gộp ô trong vùng dữ liệu. Định dạng tiền để hiển thị, không gõ chữ đồng vào giá trị số.\n\nTHỰC HÀNH\nLọc theo mặt hàng; sắp xếp đơn giá tăng dần và kiểm tra toàn bộ dòng cùng di chuyển. Lưu file gốc trước khi sắp xếp.\n\nĐẦU RA\nBảng 5 dòng có header, số lượng/giá là số và không mất liên kết mã–mặt hàng.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nDữ liệu giả lập cửa hàng: Vở A5 12.000 VND × 10; Bút bi 5.000 VND × 20; Bìa hồ sơ 8.000 VND × 5. Tính thành tiền, tổng 260.000 VND, lọc sản phẩm và vẽ biểu đồ; không dùng dữ liệu khách hàng thật.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/excel/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/excel/"}]},{"title":"02 · Công thức, SUM và tham chiếu ô","content":"TỪ BẢNG BÀI TRƯỚC\nThêm cột Thành tiền tại E. Nhập =C2*D2 rồi sao chép đến E6. Tổng tại E7 là =SUM(E2:E6). Kết quả tự kiểm lần lượt 60000, 96000, 195000, 30000, 75000; tổng 456000.\n\nTHỬ THAY ĐỔI\nĐổi số lượng Bút từ 12 thành 13. Tổng phải tăng 5000. Sau đó hoàn tác.\n\nTHAM CHIẾU\nGhi tỷ lệ dự phòng 10% ở H1. Dùng =E2*$H$1 rồi sao chép; kiểm tra địa chỉ H1 không dịch. Dấu phân cách hàm có thể khác tùy cài đặt vùng.\n\nĐỪNG LÀM\nKhông thay tổng bằng số gõ tay, không kéo công thức khi chưa kiểm tra hai hàng đầu.\n\nĐẦU RA\nBảng tính tự cập nhật và một ghi chú giải thích tham chiếu tương đối/tuyệt đối.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nDữ liệu giả lập cửa hàng: Vở A5 12.000 VND × 10; Bút bi 5.000 VND × 20; Bìa hồ sơ 8.000 VND × 5. Tính thành tiền, tổng 260.000 VND, lọc sản phẩm và vẽ biểu đồ; không dùng dữ liệu khách hàng thật.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/excel/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/excel/"}]},{"title":"03 · Thực hành: theo dõi ngân sách hoạt động","content":"Thêm các cột Ngân sách dự kiến và Chênh lệch vào bảng. Giả định ngân sách từng dòng là 70000, 100000, 200000, 35000, 80000. Tính chênh lệch = ngân sách - thành tiền; dùng IF để ghi Vượt nếu chênh lệch âm, còn lại Trong mức.\n\nThử một trường hợp vượt bằng cách tăng đơn giá Giấy, quan sát cảnh báo rồi khôi phục. Tạo biểu đồ so sánh dự kiến/thực chi có nhãn và đơn vị VND.\n\nĐầu ra: bảng có công thức, trường hợp kiểm thử và một biểu đồ. Không sử dụng biểu đồ 3D để che chênh lệch. Đây là bài tập giả định, không thay cho nghiệp vụ kế toán.\n\nTự kiểm: tổng chênh lệch có bằng tổng dự kiến trừ tổng thực chi không?\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nDữ liệu giả lập cửa hàng: Vở A5 12.000 VND × 10; Bút bi 5.000 VND × 20; Bìa hồ sơ 8.000 VND × 5. Tính thành tiền, tổng 260.000 VND, lọc sản phẩm và vẽ biểu đồ; không dùng dữ liệu khách hàng thật.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/excel/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/excel/"}]},{"title":"04 · Ôn tập: phát hiện lỗi bảng tính","content":"Tạo bản sao rồi thử: nhập một giá dưới dạng chuỗi; xóa công thức một hàng; đưa tổng vào phạm vi sắp xếp; sao chép công thức dùng H1 không khóa địa chỉ.\n\nVới mỗi lỗi, ghi dấu hiệu và cách phát hiện. Dùng tổng tính lại độc lập để đối chiếu, xem công thức thay vì chỉ nhìn kết quả.\n\nCâu hỏi tự kiểm: một ô hiển thị 0 có chắc dữ liệu gốc bằng 0? Chỉ dựa vào màu ô có đủ phát hiện lỗi không?\n\nĐầu ra: checklist lỗi và bản sửa có công thức kiểm soát.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nDữ liệu giả lập cửa hàng: Vở A5 12.000 VND × 10; Bút bi 5.000 VND × 20; Bìa hồ sơ 8.000 VND × 5. Tính thành tiền, tổng 260.000 VND, lọc sản phẩm và vẽ biểu đồ; không dùng dữ liệu khách hàng thật.","seconds":600,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/excel/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/excel/"}]},{"title":"05 · Thực hành có hướng dẫn tiếng Việt","content":"Mở hướng dẫn Microsoft tiếng Việt trong mục Tài liệu. Xác định thanh lệnh, vùng làm việc, cách tạo và lưu tệp; thao tác lại trên máy rồi đóng và mở lại sản phẩm. Ghi 3 bước bằng lời của bạn, kèm một ảnh chụp không chứa dữ liệu cá nhân. Đối chiếu phiên bản phần mềm nếu giao diện khác tài liệu.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nDữ liệu giả lập cửa hàng: Vở A5 12.000 VND × 10; Bút bi 5.000 VND × 20; Bìa hồ sơ 8.000 VND × 5. Tính thành tiền, tổng 260.000 VND, lọc sản phẩm và vẽ biểu đồ; không dùng dữ liệu khách hàng thật.","seconds":256,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/excel/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/excel/"}]},{"title":"06 · Dự án: báo cáo bán hàng mini có kiểm soát","content":"ĐỀ BÀI\nMột quầy văn phòng phẩm cần xem doanh thu của 5 mặt hàng. Từ bảng dữ liệu đã có, tạo sheet BaoCao nêu tổng doanh thu, mặt hàng doanh thu cao nhất và một biểu đồ.\n\nYÊU CẦU\nGiữ sheet DuLieuGoc không sửa; sheet TinhToan chứa công thức; sheet BaoCao chỉ trình bày chỉ số và kết luận. Thử thay một số lượng để chứng minh báo cáo cập nhật. Không suy ra lợi nhuận nếu chưa có giá vốn.\n\nCHECKLIST /10\nCông thức đúng 3; kiểm soát thay đổi 2; biểu đồ rõ 2; kết luận đúng phạm vi dữ liệu 2; ghi nguồn giả định 1.\n\nĐẦU RA\nFile .xlsx hoặc .ods và PDF báo cáo một trang. Hiện chưa có trình chấm file bảng tính tự động; dùng Q&A xin nhận xét của giảng viên.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nDữ liệu giả lập cửa hàng: Vở A5 12.000 VND × 10; Bút bi 5.000 VND × 20; Bìa hồ sơ 8.000 VND × 5. Tính thành tiền, tổng 260.000 VND, lọc sản phẩm và vẽ biểu đồ; không dùng dữ liệu khách hàng thật.","seconds":3000,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/excel/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/excel/"}]},{"title":"07 · Mở rộng: tổng hợp theo nhóm và PivotTable","content":"Tạo 10 dòng giao dịch giả định, thêm cột Nhóm hàng gồm Viết, Giấy, Phụ kiện. Mỗi dòng có ngày, số lượng và thành tiền. Tạo PivotTable tổng theo nhóm; Calc dùng Data Pivot Table với tên lệnh khác.\n\nĐối chiếu tổng Pivot với SUM của nguồn. Thêm một giao dịch mới, làm mới bảng tổng hợp và kiểm tra vùng dữ liệu có chứa dòng mới không. Không đưa thông tin khách hàng thật vào bài tập.\n\nĐầu ra: bảng tổng hợp kèm hai lần kiểm tra trước/sau thêm dữ liệu.\n\nMở rộng không bắt buộc cho phương án học nhanh; cần hoàn thành bài dữ liệu và công thức trước.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nDữ liệu giả lập cửa hàng: Vở A5 12.000 VND × 10; Bút bi 5.000 VND × 20; Bìa hồ sơ 8.000 VND × 5. Tính thành tiền, tổng 260.000 VND, lọc sản phẩm và vẽ biểu đồ; không dùng dữ liệu khách hàng thật.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/excel/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:31d0f80e-376c-c70e-e35b-26210b2c7d74.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/excel/"}]}],"questions":[{"text":"Tổng năm mặt hàng ở bài công thức là bao nhiêu?","options":["456000","45600"],"correct":0},{"text":"Sao chép công thức mà giữ H1 cố định dùng gì?","options":["$H$1","H1"],"correct":0},{"text":"Doanh thu có đồng nghĩa lợi nhuận không?","options":["Không; cần biết chi phí/giá vốn","Có; chỉ cần tổng bán hàng"],"correct":0},{"text":"Thêm dòng vào nguồn Pivot cần kiểm tra gì?","options":["Vùng nguồn và làm mới bảng tổng hợp","Chỉ đổi màu tiêu đề"],"correct":0},{"text":"B2=120000, C2=3, thành tiền tại D2 dùng gì?","options":["=B2*C2","=B2+C2","=B2-C2","=B2/C2"],"correct":0},{"text":"Sao chép công thức nhưng giữ tỷ lệ ở F1 cần dùng gì?","options":["Tham chiếu tuyệt đối $F$1","Chỉ F1 không khóa","Xóa ô F1","Gõ tỷ lệ vào mọi ô"],"correct":0},{"text":"Tổng doanh thu D2:D6 dùng công thức nào?","options":["=SUM(D2:D6)","=COUNT(D2:D6)","=MAX(D2:D6)","=MIN(D2:D6)"],"correct":0},{"text":"Số tiền VND nên lưu thế nào để tính toán?","options":["Giá trị số, định dạng tiền tệ khi hiển thị","Chuỗi có chữ đồng ở mọi ô","Ảnh chụp hóa đơn thay số","Chỉ màu ô"],"correct":0}]},{"key":"powerpoint","name":"PowerPoint thực hành — Thuyết trình dự án rõ ràng","topic":"Tin học văn phòng","marker":"[VEDU-OFFICE-v1:powerpoint]","summary":"Xây dựng một bài trình bày có thông điệp, biểu đồ và ghi chú nói. Có thể dùng PowerPoint hoặc LibreOffice Impress.","preparation":"Máy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nXây dựng một bài trình bày có thông điệp, biểu đồ và ghi chú nói. Có thể dùng PowerPoint hoặc LibreOffice Impress.\n\nCHUẨN BỊ\nMáy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 7 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Thông điệp và cấu trúc câu chuyện\n2. Bố cục, tương phản và nguồn hình ảnh\n3. Thực hành: biến bảng số thành thông điệp\n4. Ôn tập: giản lược slide quá tải\n5. Thực hành có hướng dẫn tiếng Việt\n6. Dự án: pitch đề xuất trong 300 giây\n7. Mở rộng: khả năng tiếp cận và bản bàn giao\n\nNGUỒN\nTài liệu gốc và tham khảo trong sổ tự học.\nMicrosoft powerpoint - tài liệu tiếng Việt https://support.microsoft.com/vi-vn/powerpoint/\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/powerpoint/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"}]},{"title":"01 · Thông điệp và cấu trúc câu chuyện","content":"BÀI TOÁN\nBạn có 300 giây để đề xuất một hoạt động cho lớp/phòng ban. Viết một câu duy nhất: người nghe cần hiểu và quyết định điều gì?\n\nLẬP DÀN Ý\nTạo 5 slide: vấn đề; đối tượng; giải pháp; nguồn lực; lời đề nghị. Mỗi slide có tiêu đề thể hiện một ý, không chép toàn bộ báo cáo Word.\n\nTỰ KIỂM\nChỉ đọc tiêu đề 5 slide, người nghe có nắm câu chuyện không? Dữ liệu nào là giả định phải được đánh dấu ngay.\n\nĐẦU RA\nStoryboard năm khung trên giấy hoặc trong file trình bày, chưa cần hiệu ứng.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nLàm 6 slide thuyết trình dự án học tập trong 5 phút: vấn đề, người dùng, giải pháp, minh chứng, giới hạn, kế hoạch. Ghi nguồn ảnh và dữ liệu.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/powerpoint/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/powerpoint/"}]},{"title":"02 · Bố cục, tương phản và nguồn hình ảnh","content":"Tạo một slide mẫu với tiêu đề, vùng nội dung và nguồn. Chọn tối đa hai font có tiếng Việt; kiểm tra cỡ chữ bằng cách xem ở kích thước trình chiếu thực tế.\n\nDùng canh hàng/lưới để đặt ba đối tượng thẳng nhau; giữ khoảng cách nhất quán. Chọn tương phản đủ rõ, không dùng mỗi màu để truyền đạt trạng thái.\n\nThử xuất PDF rồi đọc lại dấu tiếng Việt. Chỉ dùng ảnh do bạn tạo hoặc ảnh có quyền sử dụng; ghi nguồn, không lấy ảnh tìm kiếm bất kỳ rồi coi là miễn phí.\n\nĐầu ra: slide mẫu và một bản lỗi/đã sửa để giải thích lựa chọn thiết kế.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nLàm 6 slide thuyết trình dự án học tập trong 5 phút: vấn đề, người dùng, giải pháp, minh chứng, giới hạn, kế hoạch. Ghi nguồn ảnh và dữ liệu.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/powerpoint/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/powerpoint/"}]},{"title":"03 · Thực hành: biến bảng số thành thông điệp","content":"DỮ LIỆU GIẢ ĐỊNH\nBa phương án tập huấn A/B/C có số người tham gia 15/30/24 và chi phí 1500000/2400000/2160000 VND.\n\nNHIỆM VỤ\nTính chi phí/người rồi tạo biểu đồ cột để so sánh: 100000/80000/90000 VND. Tiêu đề slide phải nêu thông điệp, không chỉ ghi Biểu đồ. Trục có đơn vị; không cắt trục để phóng đại khác biệt.\n\nTỰ KIỂM\nPhương án B rẻ nhất/người nhưng có phải lựa chọn tốt nhất trong mọi điều kiện không? Nêu thêm giới hạn về ngân sách tổng và sức chứa.\n\nĐầu ra: một slide biểu đồ và một đoạn giải thích 3 câu.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nLàm 6 slide thuyết trình dự án học tập trong 5 phút: vấn đề, người dùng, giải pháp, minh chứng, giới hạn, kế hoạch. Ghi nguồn ảnh và dữ liệu.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/powerpoint/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/powerpoint/"}]},{"title":"04 · Ôn tập: giản lược slide quá tải","content":"Tạo một slide có đoạn văn dài rồi sửa thành một kết luận, ba bằng chứng và nguồn. Chuyển phần cần nói sang speaker notes.\n\nNhờ một người đọc slide trong 10 giây và kể lại thông điệp. Nếu chưa rõ, sửa tiêu đề trước khi thêm hình hoặc hiệu ứng. Đây là kiểm tra giao tiếp nhỏ, không phải đo chất lượng mô hình AI.\n\nĐầu ra: ảnh/bản slide trước và sau, kèm lý do bỏ từng thành phần.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nLàm 6 slide thuyết trình dự án học tập trong 5 phút: vấn đề, người dùng, giải pháp, minh chứng, giới hạn, kế hoạch. Ghi nguồn ảnh và dữ liệu.","seconds":600,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/powerpoint/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/powerpoint/"}]},{"title":"05 · Thực hành có hướng dẫn tiếng Việt","content":"Mở hướng dẫn Microsoft tiếng Việt trong mục Tài liệu. Xác định thanh lệnh, vùng làm việc, cách tạo và lưu tệp; thao tác lại trên máy rồi đóng và mở lại sản phẩm. Ghi 3 bước bằng lời của bạn, kèm một ảnh chụp không chứa dữ liệu cá nhân. Đối chiếu phiên bản phần mềm nếu giao diện khác tài liệu.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nLàm 6 slide thuyết trình dự án học tập trong 5 phút: vấn đề, người dùng, giải pháp, minh chứng, giới hạn, kế hoạch. Ghi nguồn ảnh và dữ liệu.","seconds":303,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/powerpoint/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/powerpoint/"}]},{"title":"06 · Dự án: pitch đề xuất trong 300 giây","content":"Xây dựng bài pitch 5–7 slide cho đề xuất tập huấn. Có vấn đề, đối tượng, giải pháp, một biểu đồ, lịch triển khai và quyết định cần xin.\n\nLuyện trình bày bằng đồng hồ 300 giây; ghi speaker notes thay vì đọc slide. Chuẩn bị một câu trả lời về chi phí và một câu về rủi ro.\n\nCHECKLIST /10\nThông điệp 3; bằng chứng/nguồn 2; thiết kế dễ đọc 2; đúng thời gian 2; lời đề nghị rõ 1.\n\nĐầu ra: file chỉnh sửa, PDF và bảng tự nhận xét. Chỉ tự quay video nếu bạn đồng ý, không quay người khác khi chưa được phép. Hiện ứng dụng không chấm tự động kỹ năng thuyết trình; xin giảng viên nhận xét qua Q&A.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nLàm 6 slide thuyết trình dự án học tập trong 5 phút: vấn đề, người dùng, giải pháp, minh chứng, giới hạn, kế hoạch. Ghi nguồn ảnh và dữ liệu.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/powerpoint/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/powerpoint/"}]},{"title":"07 · Mở rộng: khả năng tiếp cận và bản bàn giao","content":"Thêm mô tả cho hình/biểu đồ, kiểm tra thứ tự đọc, dùng tiêu đề riêng cho mỗi slide. Nếu có công cụ kiểm tra accessibility, xem từng cảnh báo rồi quyết định sửa; không coi hết cảnh báo là tài liệu chắc chắn tiếp cận hoàn hảo.\n\nXuất PDF, kiểm tra font và các liên kết. Chuẩn bị bản không phụ thuộc Internet để thuyết trình.\n\nĐầu ra: checklist bàn giao gồm file nguồn, PDF, nguồn tài nguyên và lưu ý thiết bị. Không phát hành lại tài nguyên bên ngoài khi chưa có quyền.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nLàm 6 slide thuyết trình dự án học tập trong 5 phút: vấn đề, người dùng, giải pháp, minh chứng, giới hạn, kế hoạch. Ghi nguồn ảnh và dữ liệu.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/powerpoint/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:040be991-732c-4e3b-6349-c3564c05fdd8.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.microsoft.com/vi-vn/powerpoint/"}]}],"questions":[{"text":"Trước khi thiết kế slide cần chốt gì?","options":["Thông điệp và quyết định muốn người nghe đưa ra","Hiệu ứng chuyển slide"],"correct":0},{"text":"Chi phí/người của phương án B là?","options":["80000 VND","2400000 VND"],"correct":0},{"text":"Nguồn số liệu giả định nên ghi thế nào?","options":["Ghi rõ là dữ liệu bài tập giả định","Gọi là khảo sát học viên thật"],"correct":0},{"text":"Phần lời nói chi tiết nên đặt đâu?","options":["Speaker notes","Dồn hết lên slide"],"correct":0},{"text":"Bài trình bày 5 phút nên ưu tiên gì?","options":["Một thông điệp chính, số liệu chọn lọc và diễn tập","Càng nhiều chữ càng tốt","Mỗi dòng một hiệu ứng","Đọc nguyên báo cáo 20 trang"],"correct":0},{"text":"Biểu đồ cần kèm gì?","options":["Đơn vị, nhãn và nguồn dữ liệu","Chỉ màu đẹp","Không cần trục","Bỏ mọi chú thích"],"correct":0},{"text":"Ảnh lấy từ bên ngoài cần gì?","options":["Quyền sử dụng phù hợp và ghi nguồn","Xóa watermark để dùng","Ghi là ảnh tự chụp","Chỉ đổi tên file"],"correct":0},{"text":"Trước thuyết trình nên kiểm tra gì?","options":["Font, liên kết, màn hình trình chiếu và thời lượng","Chỉ tên file","Chỉ số slide","Không cần mở thử"],"correct":0}]},{"key":"digital","name":"Kỹ năng số thực hành — Tệp, cộng tác và an toàn email","topic":"Kỹ năng số","marker":"[VEDU-OFFICE-v1:digital]","summary":"Tổ chức hồ sơ, chia sẻ có kiểm soát, xử lý email và tình huống lừa đảo. Chỉ dùng dữ liệu giả định, không yêu cầu cung cấp mật khẩu hoặc OTP.","preparation":"Máy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nTổ chức hồ sơ, chia sẻ có kiểm soát, xử lý email và tình huống lừa đảo. Chỉ dùng dữ liệu giả định, không yêu cầu cung cấp mật khẩu hoặc OTP.\n\nCHUẨN BỊ\nMáy tính và Microsoft Office có quyền sử dụng hoặc phần mềm tương đương; thực hành bằng dữ liệu giả lập.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 7 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tổ chức tệp và bản sao lưu\n2. Email công việc và nhận diện phishing\n3. Thực hành: ma trận quyền chia sẻ\n4. Ôn tập: phân loại năm tình huống số\n5. Tình huống: link tài liệu bị gửi nhầm\n6. Dự án: bộ quy tắc làm việc số cho nhóm\n7. Mở rộng: tối thiểu hóa dữ liệu và quyền riêng tư\n\nNGUỒN\nTài liệu gốc và tham khảo trong sổ tự học.\nGoogle Drive - tài liệu tiếng Việt https://support.google.com/drive/answer/7166529?hl=vi\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/digital/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"}]},{"title":"01 · Tổ chức tệp và bản sao lưu","content":"Tạo cấu trúc thư mục cho một dự án gồm Nguon, LamViec, BanGiao. Đặt tên file theo nội dung, ngày và phiên bản; tránh đặt tên chứa số giấy tờ cá nhân.\n\nLàm một bản sao vào vị trí khác được phép sử dụng. Thử phục hồi một file bài tập vào thư mục tạm, không xóa dữ liệu thật để thử.\n\nPhân biệt đồng bộ và sao lưu: việc xóa/ghi đè trong thư mục đồng bộ có thể lan sang bản khác. Hãy kiểm tra tính năng lịch sử phiên bản/thùng rác của dịch vụ đang dùng.\n\nĐầu ra: sơ đồ lưu trữ và một biên bản thử phục hồi. Không ghi khóa hoặc mật khẩu vào tài liệu này.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTạo thư mục nhóm, chia sẻ đúng người, phân biệt xem/nhận xét/sửa, tạo bản sao lưu và thử khôi phục một tệp giả lập.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.google.com/drive/answer/7166529?hl=vi"}]},{"title":"02 · Email công việc và nhận diện phishing","content":"SOẠN EMAIL\nViết email giả định gửi giảng viên xin góp ý báo cáo: tiêu đề rõ, giới thiệu ngắn, yêu cầu cụ thể, hạn mong muốn và tên tệp. Không gửi email thật trong bài tập.\n\nTÌNH HUỐNG\nMột email tự xưng bộ phận IT yêu cầu nhập OTP vào liên kết lạ trong 300 giây. Ghi lại các dấu hiệu cần xác minh: địa chỉ gửi, tên miền đích, yêu cầu bí mật và áp lực thời gian. Không mở liên kết hoặc gửi mã.\n\nXỬ LÝ\nXác minh bằng kênh chính thức đã biết, báo người phụ trách và không chuyển tiếp tệp nguy hiểm. Nếu đã lộ thông tin, làm theo hướng dẫn bảo vệ tài khoản của tổ chức.\n\nĐầu ra: email nháp và checklist đánh giá thông điệp đáng ngờ.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTạo thư mục nhóm, chia sẻ đúng người, phân biệt xem/nhận xét/sửa, tạo bản sao lưu và thử khôi phục một tệp giả lập.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.google.com/drive/answer/7166529?hl=vi"}]},{"title":"03 · Thực hành: ma trận quyền chia sẻ","content":"Cho ba vai trò: người soạn, người góp ý và người nhận bản cuối. Tạo ma trận Ai — Tài nguyên — Quyền — Hạn cần truy cập.\n\nChỉ dùng file bài tập không nhạy cảm. Đọc cài đặt chia sẻ của dịch vụ trước khi tạo link; ưu tiên người nhận xác định thay vì bất kỳ ai có link. Không thay đổi quyền của file thật khi chưa được chủ file cho phép.\n\nTự kiểm: người chỉ cần đọc có được quyền chỉnh sửa không? Nếu link bị chuyển tiếp có rủi ro gì? Khi kết thúc dự án cần rà soát quyền nào?\n\nĐầu ra: ma trận và kế hoạch thu hồi quyền. Với demo không cần thực sự gửi link cho người ngoài.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTạo thư mục nhóm, chia sẻ đúng người, phân biệt xem/nhận xét/sửa, tạo bản sao lưu và thử khôi phục một tệp giả lập.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.google.com/drive/answer/7166529?hl=vi"}]},{"title":"04 · Ôn tập: phân loại năm tình huống số","content":"Phân loại các tình huống thành An toàn có điều kiện / Cần xác minh / Không nên làm: gửi OTP cho người tự xưng hỗ trợ; gửi PDF đã rà soát qua kênh được phép; mở tệp thực thi từ email lạ; dùng cùng mật khẩu cho mọi dịch vụ; khôi phục file bài tập từ bản sao.\n\nGiải thích mỗi lựa chọn bằng một câu. Đáp án định hướng: OTP và tệp thực thi lạ không nên làm; PDF cần đúng quyền/người nhận; dùng lại mật khẩu làm tăng rủi ro; khôi phục bản sao cần kiểm tra nguồn.\n\nKhông đưa thông tin tài khoản thật vào phần trả lời.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTạo thư mục nhóm, chia sẻ đúng người, phân biệt xem/nhận xét/sửa, tạo bản sao lưu và thử khôi phục một tệp giả lập.","seconds":600,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.google.com/drive/answer/7166529?hl=vi"}]},{"title":"05 · Tình huống: link tài liệu bị gửi nhầm","content":"Bạn phát hiện một link tài liệu nhóm được gửi nhầm cho người không tham gia. Lập trình tự xử lý: ngừng phát tán thêm, báo chủ tài nguyên, rà soát quyền, điều chỉnh theo thẩm quyền, kiểm tra lịch sử nếu có và rút kinh nghiệm.\n\nKhông tự xóa dấu vết hoặc truy cập tài khoản người khác. Không hứa thu hồi quyền sẽ xóa mọi bản sao đã tải về.\n\nĐầu ra: sơ đồ quyết định bằng văn bản và một mẫu thông báo nội bộ không chứa dữ liệu nhạy cảm.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTạo thư mục nhóm, chia sẻ đúng người, phân biệt xem/nhận xét/sửa, tạo bản sao lưu và thử khôi phục một tệp giả lập.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.google.com/drive/answer/7166529?hl=vi"}]},{"title":"06 · Dự án: bộ quy tắc làm việc số cho nhóm","content":"Soạn quy tắc một trang cho nhóm 3 người: đặt tên file, lưu bản nguồn, sao lưu, chia sẻ, email, nhận diện liên kết đáng ngờ và xử lý sự cố.\n\nThêm ba tình huống diễn tập bằng dữ liệu hư cấu và kết quả mong đợi. Không cần thao tác trên tài khoản hoặc tài liệu thật của tổ chức.\n\nCHECKLIST /10\nQuy trình rõ 3; quyền tối thiểu 2; khôi phục được 2; nhận diện rủi ro 2; có người chịu trách nhiệm 1.\n\nĐầu ra: quy tắc, ma trận trách nhiệm và biên bản diễn tập. Dùng Q&A xin giảng viên góp ý; hiện chưa có chấm tự động dự án.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTạo thư mục nhóm, chia sẻ đúng người, phân biệt xem/nhận xét/sửa, tạo bản sao lưu và thử khôi phục một tệp giả lập.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.google.com/drive/answer/7166529?hl=vi"}]},{"title":"07 · Mở rộng: tối thiểu hóa dữ liệu và quyền riêng tư","content":"Rà soát biểu mẫu khảo sát giả định. Với từng trường, ghi mục đích thu thập, ai được xem và thời hạn giữ. Loại trường không cần cho mục đích học tập.\n\nThử thay tên bằng mã ẩn danh nhưng lưu ý mã ẩn danh vẫn có thể liên kết lại nếu giữ bảng đối chiếu. Không công khai log học tập có thể nhận diện người.\n\nĐầu ra: biểu mẫu tối giản và kế hoạch xóa/ẩn danh sau nghiên cứu. Đây là bài tập thực hành kỹ năng, không thay thế tư vấn pháp lý hoặc quy định của tổ chức.\n\nBÀI TẬP VẬN DỤNG VIỆT NAM\nTạo thư mục nhóm, chia sẻ đúng người, phân biệt xem/nhận xét/sửa, tạo bản sao lưu và thử khôi phục một tệp giả lập.","seconds":1200,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:2c933dc6-b50a-1d34-03fb-d71c3bc6b60b.pdf"},{"title":"Tài liệu hướng dẫn tiếng Việt tại nguồn chính thức","type":"LINK","url":"https://support.google.com/drive/answer/7166529?hl=vi"}]}],"questions":[{"text":"Người tự xưng IT yêu cầu OTP qua link lạ, nên làm gì?","options":["Không gửi mã; xác minh qua kênh chính thức","Gửi ngay vì có hạn thời gian"],"correct":0},{"text":"Người chỉ cần đọc bản cuối nên có quyền gì?","options":["Quyền đọc phù hợp phạm vi cần thiết","Quyền sửa mọi file dự án"],"correct":0},{"text":"Đồng bộ có luôn thay cho sao lưu không?","options":["Không; xóa/ghi đè có thể đồng bộ sang nơi khác","Có, không cần kiểm tra phục hồi"],"correct":0},{"text":"Thu hồi link có chắc xóa mọi bản đã tải không?","options":["Không","Có"],"correct":0},{"text":"Người chỉ cần góp ý nên được cấp quyền gì?","options":["Nhận xét khi phù hợp nhu cầu","Sửa mọi tài liệu công khai","Quản trị tài khoản","Không cần xác định người nhận"],"correct":0},{"text":"Lỡ chia sẻ nhầm tệp nội bộ, bước đầu hợp lý là gì?","options":["Thu hồi quyền và thông báo người phụ trách","Xóa nhật ký để che lỗi","Chia sẻ tiếp cho mọi người","Bỏ qua vì đã gửi"],"correct":0},{"text":"Tên tệp nào dễ quản lý phiên bản?","options":["BaoCaoNhom_2026-11-01_v02.docx","moi_nhat_cuoi_cung_that.docx","1.docx","file khong ten.docx"],"correct":0},{"text":"Muốn kiểm tra backup có ích cần làm gì?","options":["Thử phục hồi và mở dữ liệu","Chỉ nhìn dung lượng thư mục","Chỉ chụp màn hình ổ đĩa","Không cần kiểm tra"],"correct":0}]},{"key":"digital-literacy","name":"Kỹ năng số — Tìm kiếm, đánh giá thông tin và sử dụng AI có trách nhiệm","topic":"Kỹ năng số","marker":"[VEDU-CURATED-v202611:digital-literacy]","summary":"Tìm và kiểm chứng thông tin, đọc số liệu, ghi nguồn, sử dụng công cụ hỗ trợ có trách nhiệm qua tình huống học tập tiếng Việt.","preparation":"Trình duyệt và công cụ soạn thảo; không yêu cầu dịch vụ AI trả phí.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\nTìm và kiểm chứng thông tin, đọc số liệu, ghi nguồn, sử dụng công cụ hỗ trợ có trách nhiệm qua tình huống học tập tiếng Việt.\n\nCHUẨN BỊ\nTrình duyệt và công cụ soạn thảo; không yêu cầu dịch vụ AI trả phí.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 6 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tìm kiếm thông tin có mục tiêu\n2. Đánh giá nguồn và thời điểm công bố\n3. Trích dẫn và sử dụng hình ảnh\n4. Đọc bảng dữ liệu và biểu đồ\n5. Sử dụng công cụ AI có kiểm chứng\n6. Bài thực hành: hồ sơ thông tin đáng tin cậy\n\nNGUỒN\nTài liệu gốc và tham khảo trong sổ tự học.\nGoogle Drive - Tìm kiếm tệp, tiếng Việt https://support.google.com/drive/answer/2375114?hl=vi\nGoogle Drive - quyền truy cập, tiếng Việt https://support.google.com/drive/answer/7166529?hl=vi\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/digital-literacy/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ddc8b1a1-9f23-eeef-63e3-1be55cc137e7.pdf"}]},{"title":"01 · Tìm kiếm thông tin có mục tiêu","content":"KIẾN THỨC VÀ MỤC TIÊU\nĐặt câu hỏi cụ thể; phân biệt kết quả tìm kiếm với bằng chứng.\n\nTHỰC HÀNH\nTìm hướng dẫn chia sẻ Google Drive bằng tiếng Việt; ghi 3 truy vấn và chọn trang trợ giúp chính thức, nêu lý do.\n\nTỰ KIỂM TRA\nĐúng thông tin: 4 điểm; có nguồn: 2; sản phẩm mở được: 2; giải thích giới hạn: 2.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital-literacy/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ddc8b1a1-9f23-eeef-63e3-1be55cc137e7.pdf"}]},{"title":"02 · Đánh giá nguồn và thời điểm công bố","content":"KIẾN THỨC VÀ MỤC TIÊU\nKiểm tra tác giả, đơn vị xuất bản, ngày cập nhật, bằng chứng và đối chiếu độc lập.\n\nTHỰC HÀNH\nSo sánh một bài quảng cáo với tài liệu nhà cung cấp; đánh dấu phát biểu nào có căn cứ và phát biểu nào chưa xác minh.\n\nTỰ KIỂM TRA\nĐúng thông tin: 4 điểm; có nguồn: 2; sản phẩm mở được: 2; giải thích giới hạn: 2.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital-literacy/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ddc8b1a1-9f23-eeef-63e3-1be55cc137e7.pdf"}]},{"title":"03 · Trích dẫn và sử dụng hình ảnh","content":"KIẾN THỨC VÀ MỤC TIÊU\nGhi tác giả/tổ chức, tiêu đề, URL, ngày truy cập; kiểm tra giấy phép trước khi sao chép.\n\nTHỰC HÀNH\nLập bảng nguồn cho báo cáo 2 trang với 3 tham khảo; ghi nguồn của từng hình thay vì chỉ ghi Google.\n\nTỰ KIỂM TRA\nĐúng thông tin: 4 điểm; có nguồn: 2; sản phẩm mở được: 2; giải thích giới hạn: 2.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital-literacy/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ddc8b1a1-9f23-eeef-63e3-1be55cc137e7.pdf"}]},{"title":"04 · Đọc bảng dữ liệu và biểu đồ","content":"KIẾN THỨC VÀ MỤC TIÊU\nPhân biệt số lượng và tỷ lệ; kiểm tra mẫu, đơn vị và phạm vi trước khi kết luận.\n\nTHỰC HÀNH\nDữ liệu giả: 20/50 học viên hoàn thành tuần 1, 30/60 tuần 2. Tính 40% và 50%, giải thích không chỉ so số tuyệt đối.\n\nTỰ KIỂM TRA\nĐúng thông tin: 4 điểm; có nguồn: 2; sản phẩm mở được: 2; giải thích giới hạn: 2.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital-literacy/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ddc8b1a1-9f23-eeef-63e3-1be55cc137e7.pdf"}]},{"title":"05 · Sử dụng công cụ AI có kiểm chứng","content":"KIẾN THỨC VÀ MỤC TIÊU\nCông cụ hỗ trợ có thể sai; không xem nội dung sinh tự động là nguồn khoa học và không gửi dữ liệu nhạy cảm.\n\nTHỰC HÀNH\nĐánh dấu 3 phát biểu cần kiểm chứng trong một bản tóm tắt; tìm nguồn gốc và ghi rõ phần chưa có bằng chứng.\n\nTỰ KIỂM TRA\nĐúng thông tin: 4 điểm; có nguồn: 2; sản phẩm mở được: 2; giải thích giới hạn: 2.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital-literacy/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ddc8b1a1-9f23-eeef-63e3-1be55cc137e7.pdf"}]},{"title":"06 · Bài thực hành: hồ sơ thông tin đáng tin cậy","content":"KIẾN THỨC VÀ MỤC TIÊU\nTổ chức tài liệu, bảng nguồn, phân quyền và bản nộp có thể mở lại.\n\nTHỰC HÀNH\nNộp báo cáo 2 trang về một công cụ học tập, 3 nguồn chính thức, bảng kiểm chứng và thư mục chia sẻ quyền xem; dữ liệu cá nhân phải là giả lập.\n\nTỰ KIỂM TRA\nĐúng thông tin: 4 điểm; có nguồn: 2; sản phẩm mở được: 2; giải thích giới hạn: 2.","seconds":900,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/digital-literacy/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ddc8b1a1-9f23-eeef-63e3-1be55cc137e7.pdf"}]}],"questions":[{"text":"Một câu trả lời AI có thể dùng như nguồn khoa học đã xác minh không?","options":["Không, cần đối chiếu nguồn gốc","Có vì văn phong rõ ràng","Có nếu câu trả lời dài","Có nếu không nêu tên công cụ"],"correct":0},{"text":"Nguồn tham khảo tốt cần ghi gì?","options":["Tác giả/đơn vị, tiêu đề, URL và ngày truy cập","Chỉ ghi Internet","Chỉ ghi Google","Chỉ chụp màn hình không rõ nguồn"],"correct":0},{"text":"20/50 người hoàn thành tương ứng tỷ lệ nào?","options":["40%","20%","50%","70%"],"correct":0},{"text":"30/60 người hoàn thành tương ứng tỷ lệ nào?","options":["50%","30%","60%","90%"],"correct":0},{"text":"Tài liệu của một phần mềm đã đổi giao diện cần kiểm tra gì?","options":["Phiên bản và ngày cập nhật","Chỉ lượt thích","Chỉ màu trang","Chỉ độ dài bài viết"],"correct":0},{"text":"Ảnh tìm trên mạng có mặc định được tự do sử dụng không?","options":["Không, cần kiểm tra quyền sử dụng","Có với mọi ảnh","Có nếu xóa tên tác giả","Có nếu đổi màu"],"correct":0},{"text":"Thông tin chưa có bằng chứng nên trình bày thế nào?","options":["Ghi chưa xác minh và tiếp tục đối chiếu","Ghi như kết quả chắc chắn","Tự tạo tên bài báo","Bỏ nguồn để dễ đọc"],"correct":0},{"text":"Khi dùng ví dụ dữ liệu học viên nên chọn gì?","options":["Dữ liệu giả lập không nhận diện người thật","Danh sách mật khẩu thật","Hồ sơ cá nhân của lớp","OTP nhận được trên điện thoại"],"correct":0}]},{"key":"oop","name":"Lập trình hướng đối tượng","topic":"Lập trình & Phát triển phần mềm","marker":"[VEDU-COMPUTING-v1:oop]","summary":"10 bài C# từ lớp, đối tượng, đóng gói đến kế thừa, đa hình, interface, ba lớp và mẫu thiết kế. Học qua PDF gốc, bài tập lập trình và tình huống thực hành.","preparation":"Lập trình cơ bản; máy có C#/.NET để thực hành console (Visual Studio hoặc VS Code).","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\n10 bài C# từ lớp, đối tượng, đóng gói đến kế thừa, đa hình, interface, ba lớp và mẫu thiết kế. Học qua PDF gốc, bài tập lập trình và tình huống thực hành.\n\nCHUẨN BỊ\nLập trình cơ bản; máy có C#/.NET để thực hành console (Visual Studio hoặc VS Code).\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 10 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Ôn C# và phương pháp hướng đối tượng\n2. Lớp đối tượng và đóng gói\n3. Constructor nạp chồng và thành phần tĩnh\n4. Danh sách generic XML và mô hình lớp\n5. Kế thừa và quan hệ giữa các lớp\n6. Đa hình và lớp trừu tượng\n7. Interface và hợp đồng hành vi\n8. Tổ chức ứng dụng theo ba lớp\n9. Nguyên lý đóng mở Liskov và đảo phụ thuộc\n10. Ba nhóm mẫu thiết kế\n\nNGUỒN\nTài liệu gốc và tham khảo trong sổ tự học.\nLập trình OOP với C# https://howkteam.vn/course/lap-trinh-oop-voi-c-32\nClass trong lập trình hướng đối tượng https://howkteam.vn/course/lap-trinh-oop-voi-c/class-trong-lap-trinh-huong-doi-tuong-1370\nTừ khóa static trong OOP https://howkteam.vn/course/lap-trinh-oop-voi-c/tu-khoa-static-trong-lap-trinh-huong-doi-tuong-1374\nKế thừa trong lập trình hướng đối tượng https://howkteam.vn/course/class-trong-lap-trinh-huong-doi-tuong/ke-thua-trong-lap-trinh-huong-doi-tuong-1379\nĐa hình trong lập trình hướng đối tượng https://howkteam.vn/course/class-trong-lap-trinh-huong-doi-tuong/da-hinh-trong-lap-trinh-huong-doi-tuong-1380\nGiới thiệu mô hình 3 lớp https://howkteam.vn/course/gioi-thieu-design-patern-singleton-phan-mem-quan-ly-quan-cafe-voi-c-winform/gioi-thieu-mo-hinh-3-lop-3-layers-1233\nSOLID Design Patterns https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/solid-design-patterns\nDesign Patterns Factories https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/design-patterns-factories\nDesign Patterns Strategy https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/design-patterns-strategy\nDesign Patterns Adapter and Facade https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/design-patterns-adapterfaade\nObject Oriented Programming C# https://learn.microsoft.com/en-us/dotnet/csharp/fundamentals/tutorials/oop\nArchitectural principles https://learn.microsoft.com/en-us/dotnet/architecture/modern-web-apps-azure/architectural-principles\nDangers of Violating SOLID Principles in C# https://learn.microsoft.com/en-us/archive/msdn-magazine/2014/may/csharp-best-practices-dangers-of-violating-solid-principles-in-csharp\nInterface trong lập trình hướng đối tượng https://howkteam.vn/course/class-trong-lap-trinh-huong-doi-tuong/interface-trong-lap-trinh-huong-doi-tuong-1396\nWorking with Collections https://learn.microsoft.com/en-us/shows/csharp-fundamentals-for-absolute-beginners/working-with-collections\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/oop/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"}]},{"title":"01 · Ôn C# và phương pháp hướng đối tượng","content":"MỤC TIÊU\nPhân biệt cách tổ chức theo hàm và theo đối tượng; dùng vòng lặp và kiểm tra dữ liệu.\n\nKIẾN THỨC\nMột lớp mô tả trạng thái và hành vi của một nhóm đối tượng. Tách dữ liệu học viên khỏi thao tác nhập xuất giúp thay đổi giao diện mà không viết lại phép tính. Với dữ liệu điểm, dùng TryParse và kiểm tra miền 0 đến 10.\n\nBÀI TẬP\nNhập các số nguyên tới khi gặp 0. Tính trung bình chỉ các số dương; nếu không có số dương thì thông báo rõ, không chia cho 0.\nVới ứng dụng mượn sách, nêu 3 lớp cùng ít nhất 2 thuộc tính và 1 hành vi mỗi lớp. Phân biệt lớp với một đối tượng cụ thể.\n\nTHỰC HÀNH\nThiết kế ứng dụng quản lý điểm một học viên: mã, họ tên, ba điểm từ 0 đến 10. Nêu lớp và hành vi, viết chương trình nhập dữ liệu hợp lệ, tính trung bình và xếp Đạt khi trung bình từ 5 trở lên. Nộp mã nguồn và 3 ca thử.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Lập trình OOP với C#","type":"LINK","url":"https://howkteam.vn/course/lap-trinh-oop-voi-c-32"}]},{"title":"02 · Lớp đối tượng và đóng gói","content":"MỤC TIÊU\nXây dựng lớp với property có kiểm tra; bảo vệ trạng thái hợp lệ.\n\nKIẾN THỨC\nDữ liệu nội bộ có thể để private. Property công khai kiểm tra trước khi gán. this chỉ đối tượng hiện hành; không dùng this trong phương thức static. Constructor cần đảm bảo đối tượng hợp lệ ngay khi được tạo.\n\nBÀI TẬP\nTạo HinhChuNhat có chiều dài, rộng dương; tính chu vi và diện tích.\nTạo SanPham có Ma không rỗng và DonGia không âm. Thử gán giá âm và giải thích vì sao cần chặn.\n\nTHỰC HÀNH\nXây dựng TaiKhoan với Ma, ChuTaiKhoan và SoDu chỉ đọc từ bên ngoài. Constructor nhận số dư ban đầu không âm. Nap nhận số dương. Rut nhận số dương không vượt số dư và báo thất bại nếu không hợp lệ. Nộp lớp và chương trình thử.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Class trong lập trình hướng đối tượng","type":"LINK","url":"https://howkteam.vn/course/lap-trinh-oop-voi-c/class-trong-lap-trinh-huong-doi-tuong-1370"}]},{"title":"03 · Constructor nạp chồng và thành phần tĩnh","content":"MỤC TIÊU\nThiết kế constructor và overload; phân biệt thành phần lớp với thành phần đối tượng.\n\nKIẾN THỨC\nOverload khác danh sách tham số, không chỉ khác kiểu trả về. Static dùng chung ở mức kiểu. Finalizer do bộ thu gom rác gọi không xác định thời điểm; không dùng finalizer để lưu dữ liệu nghiệp vụ. Với tài nguyên cần giải phóng đúng lúc, tìm hiểu IDisposable và using.\n\nBÀI TẬP\nTạo LopHoc có constructor mặc định và constructor nhận tên lớp. Tên mặc định là ChuaDatTen.\nTạo lớp TinhToan có Cong(int,int) và Cong(double,double). Cho ví dụ gọi mỗi phiên bản.\n\nTHỰC HÀNH\nXây dựng NhanVien có Ma, Ten, HeSoLuong > 0. MucLuongCoSo là thuộc tính static > 0, ban đầu 2000000. Constructor mặc định tạo NV00/ChuaDatTen/hệ số 1; constructor đầy đủ nhận ba trường. TinhLuong bằng hệ số nhân mức cơ sở. Tạo hai nhân viên và thay mức cơ sở thành 2500000.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Class trong lập trình hướng đối tượng","type":"LINK","url":"https://howkteam.vn/course/lap-trinh-oop-voi-c/class-trong-lap-trinh-huong-doi-tuong-1370"},{"title":"Từ khóa static trong OOP","type":"LINK","url":"https://howkteam.vn/course/lap-trinh-oop-voi-c/tu-khoa-static-trong-lap-trinh-huong-doi-tuong-1374"}]},{"title":"04 · Danh sách generic XML và mô hình lớp","content":"MỤC TIÊU\nQuản lý danh sách có kiểu và biểu diễn quan hệ lớp; lưu và đọc dữ liệu.\n\nKIẾN THỨC\nList<T> kiểm tra kiểu ở thời điểm biên dịch; ArrayList lưu object nên cần ép kiểu. Đề cương ghi ArrayList, quy định lớp ghi List: nhận diện cả hai và chọn List cho bài bổ sung. UML mô tả tên, thuộc tính, phương thức và quan hệ. Lớp lồng nhau khai báo bên trong lớp khác nhưng không tự có tham chiếu tới đối tượng bao ngoài. Operator overload cần giữ ý nghĩa trực giác.\n\nBÀI TẬP\nTạo List<int> chứa 3, 1, 3; tìm tổng và số lần xuất hiện của 3.\nVẽ UML KhoHang chứa danh sách SanPham. Giải thích nên dùng quan hệ chứa thay vì cho KhoHang kế thừa SanPham.\n\nTHỰC HÀNH\nViết QuanLySinhVien lưu List<SinhVien> với Ma duy nhất, Ten không rỗng và Diem từ 0 đến 10. Có Them, TimTheoMa, LayDanhSachDat (điểm >= 5), LuuXml và DocXml. File chưa tồn tại phải trả danh sách rỗng; XML hỏng phải báo lỗi và giữ danh sách cũ. Bổ sung lớp PhanSo có toán tử + cho hai phân số mẫu khác 0.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Working with Collections","type":"LINK","url":"https://learn.microsoft.com/en-us/shows/csharp-fundamentals-for-absolute-beginners/working-with-collections"}]},{"title":"05 · Kế thừa và quan hệ giữa các lớp","content":"MỤC TIÊU\nDùng base để khởi tạo dữ liệu chung; phân biệt is-a và has-a.\n\nKIẾN THỨC\nChỉ kế thừa khi lớp con thực sự là một dạng của lớp cha và tuân theo hợp đồng lớp cha. Composition phù hợp quan hệ sở hữu hoặc sử dụng. Constructor lớp con gọi base(...) để khởi tạo phần dữ liệu chung.\n\nBÀI TẬP\nMô hình Xe, XeBus và DongCo: xác định quan hệ nào là kế thừa, quan hệ nào là chứa.\nViết Nguoi có Ten, SinhVien kế thừa Nguoi có MaSV. Khởi tạo Ten qua base.\n\nTHỰC HÀNH\nXây dựng abstract ChuyenXe với Ma, TaiXe, DoanhThu >= 0; hai lớp NoiThanh thêm SoKm > 0 và NgoaiThanh thêm SoNgay > 0. Nhập/tạo ít nhất hai đối tượng mỗi loại trong List<ChuyenXe>, tính tổng doanh thu từng loại. Nộp UML và mã nguồn.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Kế thừa trong lập trình hướng đối tượng","type":"LINK","url":"https://howkteam.vn/course/class-trong-lap-trinh-huong-doi-tuong/ke-thua-trong-lap-trinh-huong-doi-tuong-1379"}]},{"title":"06 · Đa hình và lớp trừu tượng","content":"MỤC TIÊU\nCài đặt override và gọi hành vi qua kiểu lớp cha.\n\nKIẾN THỨC\nPhương thức virtual cho phép lớp con override. Phương thức abstract yêu cầu lớp con cụ thể cài đặt. Lệnh gọi qua tham chiếu cha dùng triển khai override của kiểu thực tế; new che phương thức có quy tắc khác. Lớp abstract không thể tạo trực tiếp.\n\nBÀI TẬP\nCho A.F() virtual trả 1, B : A override F() trả 2. A x = new B(); x.F() trả gì? Giải thích.\nTạo abstract Hinh với abstract DienTich(); cài đặt HinhVuong và HinhTron.\n\nTHỰC HÀNH\nXây dựng abstract PhongTro có Ma, SoDien và SoNuoc không âm, abstract TinhTien(). PhongA tính 1400 + 2*SoDien + 8*SoNuoc + 50*SoLuotKhach; PhongB tính 2000 + 2*SoDien + 8*SoNuoc + 5*KgGiat. Các số tiền tính bằng nghìn đồng. Dùng List<PhongTro> để in và tính tổng, không dùng if theo loại trong vòng lặp tính tiền.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Đa hình trong lập trình hướng đối tượng","type":"LINK","url":"https://howkteam.vn/course/class-trong-lap-trinh-huong-doi-tuong/da-hinh-trong-lap-trinh-huong-doi-tuong-1380"}]},{"title":"07 · Interface và hợp đồng hành vi","content":"MỤC TIÊU\nTách khả năng dùng chung thành interface; sử dụng kiểu interface trong chương trình.\n\nKIẾN THỨC\nInterface biểu diễn hợp đồng hành vi. Một lớp có thể triển khai nhiều interface. Với bài cơ bản, khai báo phương thức rồi cài đặt public tại lớp. Abstract class phù hợp khi cần chia sẻ trạng thái và triển khai. Tránh ép mọi lớp phải hỗ trợ hành vi không có ý nghĩa.\n\nBÀI TẬP\nKhai báo IInDuoc có string TaoNoiDung(); cho HoaDon triển khai. Viết hàm in nhận IInDuoc.\nMột chương trình cần sắp xếp học viên theo điểm. Nêu cách dùng IComparer<SinhVien> và quy tắc xử lý đồng điểm.\n\nTHỰC HÀNH\nXây dựng interface IHoTro có decimal TinhHoTro(). CaPheHat và CaPheXay triển khai IHoTro, CaPheHoaTan không triển khai. Mỗi loại có SoLuong không âm. Hỗ trợ cho hạt là 10*SoLuong, cho xay là 12*SoLuong (nghìn đồng). Tính tổng hỗ trợ qua kiểm tra item is IHoTro, không ép kiểu thiếu kiểm tra.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Interface trong lập trình hướng đối tượng","type":"LINK","url":"https://howkteam.vn/course/class-trong-lap-trinh-huong-doi-tuong/interface-trong-lap-trinh-huong-doi-tuong-1396"}]},{"title":"08 · Tổ chức ứng dụng theo ba lớp","content":"MỤC TIÊU\nTách nhập xuất, nghiệp vụ và lưu trữ; kiểm thử nghiệp vụ độc lập.\n\nKIẾN THỨC\nPresentation nhận dữ liệu và hiển thị kết quả. Business kiểm tra quy tắc và điều phối. Data Access đọc/ghi dữ liệu. Có thể dùng console, danh sách trong bộ nhớ và interface repository để minh họa, chưa cần cơ sở dữ liệu. Ba lớp logic không đồng nghĩa ba máy chủ.\n\nBÀI TẬP\nPhân loại ba thao tác: hiển thị lỗi, kiểm tra mã trùng, ghi XML vào lớp phù hợp.\nNêu hậu quả nếu nút bấm vừa kiểm tra điều kiện vừa ghép SQL vừa cập nhật giao diện.\n\nTHỰC HÀNH\nTạo ứng dụng quản lý sản phẩm console: Product, IProductRepository (Find, Add), MemoryProductRepository, ProductService và Program. Service từ chối mã trùng, mã rỗng, giá âm. Program chỉ đọc/in, repository chỉ lưu/tìm. Viết sơ đồ phụ thuộc và ba ca thử service.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/08.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Giới thiệu mô hình 3 lớp","type":"LINK","url":"https://howkteam.vn/course/gioi-thieu-design-patern-singleton-phan-mem-quan-ly-quan-cafe-voi-c-winform/gioi-thieu-mo-hinh-3-lop-3-layers-1233"}]},{"title":"09 · Nguyên lý đóng mở Liskov và đảo phụ thuộc","content":"MỤC TIÊU\nNhận diện ba nguyên lý trong tình huống thay đổi yêu cầu.\n\nKIẾN THỨC\nĐóng mở: mở rộng hành vi qua abstraction thay vì sửa liên tục mã ổn định. Liskov: lớp con dùng thay cha mà vẫn giữ hợp đồng quan sát được. Đảo phụ thuộc: phần nghiệp vụ phụ thuộc abstraction, phần cụ thể cũng hiện thực abstraction đó. Dependency injection là cách cung cấp dependency, không đồng nghĩa toàn bộ nguyên lý DIP.\n\nBÀI TẬP\nCheckout có if loại giảm giá tăng dần theo từng chương trình. Đề xuất interface IDiscount và hai cách tính.\nBird có Fly(), Penguin kế thừa rồi ném lỗi ở Fly(). Chỉ ra hợp đồng sai và thiết kế lại.\n\nTHỰC HÀNH\nThiết kế Checkout nhận IDiscount và IOrderStore qua constructor. NoDiscount giữ giá, TenPercentDiscount giảm 10%. Giỏ hàng không âm. InMemoryOrderStore lưu kết quả. Thêm FixedDiscount(amount) với số tiền giảm không âm và tổng sau giảm không dưới 0 mà không sửa Checkout. Giải thích OCP, DIP và một điều kiện Liskov.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/09.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"SOLID Design Patterns","type":"LINK","url":"https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/solid-design-patterns"}]},{"title":"10 · Ba nhóm mẫu thiết kế","content":"MỤC TIÊU\nPhân biệt mẫu khởi tạo, cấu trúc và hành vi; chọn mẫu theo vấn đề.\n\nKIẾN THỨC\nFactory Method thuộc nhóm khởi tạo; lớp creator cho phép lớp con quyết định loại sản phẩm. Adapter thuộc nhóm cấu trúc, chuyển đổi giao diện không tương thích. Strategy thuộc nhóm hành vi, tách thuật toán để thay thế lúc chạy. Simple Factory dùng một hàm chọn loại khác với Factory Method theo phân cấp creator.\n\nBÀI TẬP\nPhân loại Factory Method, Adapter, Strategy; nêu một tình huống cho mỗi mẫu.\nAPI cũ GetAmountInCents() trả số cent; ứng dụng mới cần decimal GetAmount() theo đơn vị tiền. Viết quy tắc chuyển đổi và nêu vai trò Adapter.\n\nTHỰC HÀNH\nThiết kế tính phí vận chuyển bằng IShippingStrategy: Standard = 20000, Express = 40000 với đơn hợp lệ. ShippingService nhận strategy và tính Tổng = GiaHang + Phi. Đổi strategy mà không sửa service. Vẽ thêm mô hình Factory Method gồm ShippingCreator.Create() và hai creator cụ thể. Nêu một Adapter cho API vận chuyển cũ.","seconds":1800,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/oop/10.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:656098c1-9847-afdf-01f7-83b5983b7a45.pdf"},{"title":"0101101962_DCCT_LTHDT.pdf","type":"PDF","url":"vedu-file:3a509392-ba22-e087-fdda-2a4434482e37.pdf"},{"title":"Chuong 00_Tong quan_CSharp_SV.pdf","type":"PDF","url":"vedu-file:de591cca-3b7f-6899-1ae1-55d5e8692323.pdf"},{"title":"Chuong 01_PhuongPhapLapTrinhHDT_SV.pdf","type":"PDF","url":"vedu-file:ea7a97b6-dae5-5a0b-90e2-67b145c8ba50.pdf"},{"title":"Chuong 02. Lop_DoiTuong_SV.pdf","type":"PDF","url":"vedu-file:eff0c0bb-211d-c006-e37e-36787a1cd2e0.pdf"},{"title":"Chuong 03_KeThuaVaDaHinh_SV.pdf","type":"PDF","url":"vedu-file:daca8dde-125e-6ffe-ded1-aa6d1f0e0fae.pdf"},{"title":"Chuong4. MoHinh3tang.pdf","type":"PDF","url":"vedu-file:347d7c41-f920-4df1-60dd-c46573880f93.pdf"},{"title":"QuyDinhHocPhan.pdf","type":"PDF","url":"vedu-file:e47aa138-f98d-c68e-d374-213714bdb6b4.pdf"},{"title":"[1.1]. Semon Kendal, Object Oriented Programming using C# (2nd edition).pdf","type":"PDF","url":"vedu-file:025b6f84-fcfd-ae30-ccec-02714b4582ab.pdf"},{"title":"Design Patterns Factories","type":"LINK","url":"https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/design-patterns-factories"},{"title":"Design Patterns Strategy","type":"LINK","url":"https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/design-patterns-strategy"},{"title":"Design Patterns Adapter and Facade","type":"LINK","url":"https://learn.microsoft.com/en-us/shows/visual-studio-toolbox/design-patterns-adapterfaade"}]}],"questions":[{"text":"Một đối tượng khác lớp ở điểm nào?","options":["Đối tượng là một thể hiện cụ thể của lớp","Đối tượng luôn là hàm static","Lớp không có hành vi","Mỗi lớp chỉ tạo được một đối tượng"],"correct":0},{"text":"Nhập điểm từ chuỗi an toàn cần kiểm tra gì?","options":["TryParse thành công và điểm nằm trong khoảng 0 đến 10","Chỉ kiểm tra chuỗi khác null","Chỉ ép kiểu trực tiếp","Mọi số nguyên đều là điểm hợp lệ"],"correct":0},{"text":"Thiết kế số dư tài khoản nào bảo vệ trạng thái tốt hơn?","options":["Số dư không cho gán công khai; nạp/rút kiểm tra quy tắc","Một field public bất kỳ mã nào cũng sửa được","Cho phép rút số âm","Bỏ kiểm tra số dư khi rút"],"correct":0},{"text":"Từ khóa this trong phương thức instance tham chiếu tới gì?","options":["Đối tượng hiện hành","Mọi đối tượng của lớp","Lớp cha trong mọi trường hợp","Một biến toàn cục"],"correct":0},{"text":"Hai phương thức overload phải khác nhau ở đâu?","options":["Danh sách tham số","Chỉ kiểu trả về","Chỉ tên tham số","Chỉ phạm vi public/private"],"correct":0},{"text":"Mức lương cơ sở dùng chung cho mọi nhân viên phù hợp với thành phần nào?","options":["Thành phần static của lớp","Một biến cục bộ luôn bằng 0","Một field riêng không đồng bộ ở từng nhân viên","Finalizer"],"correct":0},{"text":"List<SinhVien> có ưu điểm gì so với ArrayList trong bài cơ bản?","options":["Kiểm tra kiểu phần tử tại thời điểm biên dịch","Luôn cho phép mọi kiểu không cần kiểm tra","Không thể duyệt bằng foreach","Tự động lưu XML"],"correct":0},{"text":"Đọc XML bị hỏng nên xử lý thế nào để tránh mất dữ liệu hiện hành?","options":["Báo lỗi và chỉ thay danh sách sau khi đọc/kiểm tra thành công","Xóa dữ liệu cũ trước khi đọc","Coi tệp hỏng là tệp hợp lệ","Bỏ mọi ngoại lệ và lưu danh sách rỗng đè tệp"],"correct":0},{"text":"Quan hệ KhoHang chứa nhiều SanPham thường nên biểu diễn bằng gì?","options":["Composition/association chứa danh sách, tùy vòng đời","KhoHang kế thừa SanPham","SanPham bắt buộc kế thừa KhoHang","Hai lớp bắt buộc là một"],"correct":0},{"text":"Constructor lớp con dùng base(...) để làm gì?","options":["Gọi constructor lớp cha","Tạo một interface","Tự động ghi cơ sở dữ liệu","Bỏ qua mọi kiểm tra lớp cha"],"correct":0},{"text":"A.F() virtual trả 1; B : A override F() trả 2. A x = new B(); x.F() trả gì?","options":["2, vì dùng triển khai override của kiểu thực tế","1 vì biến có kiểu A","0 vì không gọi được override","Lỗi biên dịch trong mọi trường hợp"],"correct":0},{"text":"Phát biểu nào đúng về abstract class?","options":["Không thể tạo trực tiếp bằng new","Không được có phương thức đã cài đặt","Không được có trạng thái","Không thể có lớp con"],"correct":0},{"text":"Vì sao hàm in nhận IInDuoc thay vì chỉ nhận HoaDon?","options":["Cho phép nhiều lớp tuân theo cùng hợp đồng tạo nội dung","Để bỏ kiểm tra kiểu","Để bắt buộc mọi lớp kế thừa HoaDon","Để tự động ghi log vào SQL"],"correct":0},{"text":"Một lớp C# có thể triển khai bao nhiêu interface?","options":["Nhiều interface","Chỉ đúng một","Không thể triển khai interface","Tối đa hai trong mọi trường hợp"],"correct":0},{"text":"Kiểm tra mã sản phẩm trùng nên thuộc thành phần nào trong bài ba lớp?","options":["Business/service","Chỉ nút bấm giao diện","Mã CSS","Chỉ tên tệp"],"correct":0},{"text":"Ba lớp logic có bắt buộc chạy trên ba máy chủ không?","options":["Không, có thể chạy trên cùng một máy","Có, luôn bắt buộc ba máy","Chỉ chạy được khi có SQL Server","Không thể kiểm thử service độc lập"],"correct":0},{"text":"Checkout nhận IDiscount qua constructor minh họa điều gì?","options":["Nghiệp vụ phụ thuộc abstraction, cách cấp dependency qua constructor","Mọi thay đổi giảm giá đều phải sửa Checkout","Chỉ dùng được một cách giảm giá","Không thể viết test"],"correct":0},{"text":"Penguin kế thừa Bird.Fly() rồi ném lỗi vì không bay được gây vấn đề gì?","options":["Vi phạm hợp đồng thay thế nếu Bird cam kết mọi thể hiện bay được","Luôn đúng nguyên lý Liskov","Lỗi do thiếu static","Chỉ cần đổi tên Penguin"],"correct":0},{"text":"Nhóm đúng của Factory Method, Adapter, Strategy lần lượt là gì?","options":["Khởi tạo, cấu trúc, hành vi","Hành vi, khởi tạo, cấu trúc","Cấu trúc, hành vi, khởi tạo","Cả ba đều là mẫu cơ sở dữ liệu"],"correct":0},{"text":"API cũ trả 1250 cent, adapter cần trả số tiền theo đơn vị chính. Kết quả là gì?","options":["12.50 với phép chia thập phân cho 100","125000","1250 không đổi","12 do buộc chia nguyên"],"correct":0}]},{"key":"systems","name":"Phân tích thiết kế hệ thống","topic":"Phân tích & Thiết kế hệ thống","marker":"[VEDU-COMPUTING-v1:systems]","summary":"7 chương từ khảo sát yêu cầu đến mô hình nghiệp vụ, use case, lớp, dữ liệu và thiết kế chức năng bằng UML. Thực hành xuyên suốt với tình huống quản lý giao–nộp–chấm bài trên LMS.","preparation":"Lập trình hướng đối tượng và cơ sở dữ liệu; công cụ vẽ UML hoặc giấy để thực hành.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU\n7 chương từ khảo sát yêu cầu đến mô hình nghiệp vụ, use case, lớp, dữ liệu và thiết kế chức năng bằng UML. Thực hành xuyên suốt với tình huống quản lý giao–nộp–chấm bài trên LMS.\n\nCHUẨN BỊ\nLập trình hướng đối tượng và cơ sở dữ liệu; công cụ vẽ UML hoặc giấy để thực hành.\n\nCÁCH HỌC\nĐọc đề cương và sổ tự học, học tuần tự 7 bài, đọc tài liệu gốc, làm bài tập và lưu sản phẩm. Video tham khảo mở tại nguồn, không dùng để tính thời gian xem trong VEDU.\n\nĐÁNH GIÁ\nHoàn thành tất cả bài học; đạt bài kiểm tra kiến thức cuối khóa từ 7/10, tối đa 3 lượt. Bài thực hành và đề tự luận dùng để luyện tập, chưa tự chấm sản phẩm. Chứng nhận VEDU là chứng nhận hoàn thành khóa tự học, không phải chứng chỉ MOS hoặc chứng chỉ của đơn vị nguồn.\n\nĐỀ CƯƠNG\n1. Tổng quan về hệ thống thông tin\n2. Xác định yêu cầu\n3. Mô hình hóa nghiệp vụ\n4. Mô hình hóa chức năng\n5. Mô hình hóa cấu trúc\n6. Thiết kế lớp và dữ liệu\n7. Thiết kế chức năng hệ thống\n\nNGUỒN\nTài liệu gốc và tham khảo trong sổ tự học.\nNPTEL – System Analysis and Design https://nptel.ac.in/courses/106108103\nLucid – Use case diagram tutorial https://lucid.co/diagram/uml/use-case-diagram-tutorial\nVisual Paradigm – Synchronizing Object Model and Data Model https://circle.visual-paradigm.com/docs/database-design-engineering/database-designers-guide/synchronizing-object-model-and-data-model/\nOMG – UML 2.5.1 https://www.omg.org/spec/UML/2.5.1\nLucid – Activity diagram tutorial https://lucid.co/diagram/uml/activity-diagram-tutorial\nLucid – Class diagram tutorial https://lucid.co/diagram/uml/class-diagram-tutorial\nLucid – Sequence diagram tutorial https://lucid.co/diagram/uml/sequence-diagram-tutorial\nLucidchart – Diagramming tutorials https://www.youtube.com/playlist?list=PLUoebdZqEHTxpGCwKrb82cIvHNoNaBb4R\nKteam – Giới thiệu mô hình 3 lớp https://howkteam.vn/course/gioi-thieu-design-patern-singleton-phan-mem-quan-ly-quan-cafe-voi-c-winform/gioi-thieu-mo-hinh-3-lop-3-layers-1233\nChưa có xác nhận thẩm định độc lập của giảng viên.","seconds":300,"resources":[{"title":"Hướng dẫn và chuẩn đầu ra","type":"LINK","url":"/course-materials/systems/00.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"}]},{"title":"01 · Tổng quan về hệ thống thông tin","content":"MỤC TIÊU\nPhân biệt thành phần hệ thống thông tin và giải thích các giai đoạn phát triển.\n\nKIẾN THỨC\nHệ thống thông tin gồm con người, quy trình, dữ liệu và công nghệ. Với LMS, xác định vấn đề nghiệp vụ trước khi chọn công cụ. Các giai đoạn kế hoạch, phân tích, thiết kế, hiện thực cần đầu ra có thể kiểm tra.\n\nBÀI TẬP\nLiệt kê 5 thành phần của LMS; với mỗi thành phần cho một ví dụ cụ thể.\nLập bảng 4 giai đoạn phát triển, mỗi giai đoạn nêu 2 công việc và 1 sản phẩm bàn giao.\n\nTHỰC HÀNH\nViết bản phạm vi LMS 1–2 trang: vấn đề, 3 nhóm người dùng, mục tiêu đo được, chức năng trong/ngoài phạm vi, giả định và 3 rủi ro.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems/01.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"},{"title":"NPTEL – System Analysis and Design","type":"LINK","url":"https://nptel.ac.in/courses/106108103"}]},{"title":"02 · Xác định yêu cầu","content":"MỤC TIÊU\nThu thập, phân loại và viết yêu cầu kiểm chứng được.\n\nKIẾN THỨC\nPhân biệt yêu cầu chức năng với yêu cầu chất lượng. Phỏng vấn, quan sát, tài liệu có sẵn và nguyên mẫu bổ sung cho nhau. Không tự coi giả định của nhóm là yêu cầu đã được người dùng xác nhận.\n\nBÀI TẬP\nSoạn 6 câu phỏng vấn: 2 cho sinh viên, 2 cho giảng viên, 2 cho quản trị; nêu mục đích của từng câu.\nViết 6 yêu cầu chức năng và 3 yêu cầu phi chức năng của LMS, đặt mã FR/NFR và tiêu chí nghiệm thu.\n\nTHỰC HÀNH\nNộp đặc tả 2–3 trang gồm bảng bên liên quan, 8 FR, 3 NFR đo được, độ ưu tiên, phương pháp thu thập, 3 vấn đề cần xác nhận và ma trận yêu cầu–kiểm thử.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems/02.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"},{"title":"NPTEL – System Analysis and Design","type":"LINK","url":"https://nptel.ac.in/courses/106108103"}]},{"title":"03 · Mô hình hóa nghiệp vụ","content":"MỤC TIÊU\nMô tả mục tiêu nghiệp vụ và luồng công việc bằng UML.\n\nKIẾN THỨC\nMô hình nghiệp vụ mô tả cách tổ chức làm việc, chưa đồng nhất với thao tác màn hình. Activity diagram dùng nút bắt đầu/kết thúc, hành động, điều kiện rẽ nhánh và luồng; swimlane thể hiện trách nhiệm.\n\nBÀI TẬP\nLập bảng thuật ngữ 8 mục và phân biệt tác nhân nghiệp vụ với nhân sự thực hiện trong quy trình giao–nộp–chấm.\nVẽ activity diagram quy trình nộp bài, có nhánh đúng hạn/quá hạn, tệp hợp lệ/không hợp lệ.\n\nTHỰC HÀNH\nNộp mô hình nghiệp vụ giao–nộp–chấm gồm phạm vi tổ chức, business use case mức khái quát và activity diagram có swimlane Sinh viên, Bộ phận giảng dạy/LMS, Giảng viên. Giải thích 3 quy tắc nghiệp vụ.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems/03.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"},{"title":"Lucid – Activity diagram tutorial","type":"LINK","url":"https://lucid.co/diagram/uml/activity-diagram-tutorial"}]},{"title":"04 · Mô hình hóa chức năng","content":"MỤC TIÊU\nXác định actor, use case và đặc tả luồng chính/ngoại lệ.\n\nKIẾN THỨC\nUse case thể hiện mục tiêu có giá trị của actor. Include dùng cho hành vi được gọi bắt buộc, extend cho hành vi bổ sung có điều kiện tại điểm mở rộng. Không bắt buộc sử dụng cả hai. Đăng nhập có thể là tiền điều kiện thay vì include cho mọi chức năng.\n\nBÀI TẬP\nVẽ use case diagram cho 3 actor, ít nhất 8 use case; giải thích ranh giới hệ thống.\nĐặc tả UC-NOP: actor, tiền điều kiện, kích hoạt, luồng chính, 4 ngoại lệ và hậu điều kiện.\n\nTHỰC HÀNH\nHoàn thiện sơ đồ use case và đặc tả Nộp bài, Chấm bài; ánh xạ từng use case vào FR. Chỉ thêm include/extend khi chứng minh được ngữ nghĩa.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems/04.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"},{"title":"Lucid – Use case diagram tutorial","type":"LINK","url":"https://lucid.co/diagram/uml/use-case-diagram-tutorial"},{"title":"Lucidchart – Diagramming tutorials","type":"LINK","url":"https://www.youtube.com/playlist?list=PLUoebdZqEHTxpGCwKrb82cIvHNoNaBb4R"}]},{"title":"05 · Mô hình hóa cấu trúc","content":"MỤC TIÊU\nXây dựng mô hình lớp miền với thuộc tính và bội số hợp lý.\n\nKIẾN THỨC\nMô hình miền mô tả khái niệm nghiệp vụ, không cần chứa các lớp giao diện hoặc cơ sở dữ liệu. Enrollment là lớp liên kết Student–CourseClass. Chỉ dùng composition khi có quan hệ sở hữu và vòng đời phù hợp.\n\nBÀI TẬP\nTừ tình huống, đề xuất 7 lớp miền và giải thích vì sao không chọn MànHìnhNộpBài làm lớp miền.\nVẽ các liên kết và bội số Student–Enrollment–CourseClass, Assignment–Submission; nêu 3 bất biến.\n\nTHỰC HÀNH\nNộp class diagram có Student, Teacher, CourseClass, Enrollment, Assignment, Submission, Grade; thêm thuộc tính chính, bội số hai đầu và 4 ràng buộc nghiệp vụ. Phân biệt class diagram phân tích với lớp thiết kế.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems/05.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"},{"title":"Lucid – Class diagram tutorial","type":"LINK","url":"https://lucid.co/diagram/uml/class-diagram-tutorial"}]},{"title":"06 · Thiết kế lớp và dữ liệu","content":"MỤC TIÊU\nChuyển lớp và liên kết sang lược đồ quan hệ, xác định toàn vẹn dữ liệu.\n\nKIẾN THỨC\nLiên kết 1–n thường ánh xạ bằng khóa ngoại ở phía n; n–n bằng bảng kết hợp. Khóa ngoại chỉ kiểm tra tham chiếu, không tự bảo đảm tất cả quy tắc nghiệp vụ như đúng hạn hoặc thuộc đúng lớp.\n\nBÀI TẬP\nChuyển 7 lớp chương 5 thành bảng, đánh dấu PK, FK và UNIQUE.\nViết 5 trường hợp dữ liệu bị từ chối: trùng ghi danh, trùng bài nộp, thiếu bài tập, điểm ngoài khoảng và nộp sai lớp.\n\nTHỰC HÀNH\nNộp lược đồ quan hệ và từ điển dữ liệu ít nhất 12 trường; nêu cách bảo đảm nộp một lần khi hai yêu cầu đến đồng thời, cùng cách xử lý quy tắc đúng lớp/đúng hạn.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems/06.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"},{"title":"Visual Paradigm – Synchronizing Object Model and Data Model","type":"LINK","url":"https://circle.visual-paradigm.com/docs/database-design-engineering/database-designers-guide/synchronizing-object-model-and-data-model/"},{"title":"Lucidchart – Diagramming tutorials","type":"LINK","url":"https://www.youtube.com/playlist?list=PLUoebdZqEHTxpGCwKrb82cIvHNoNaBb4R"}]},{"title":"07 · Thiết kế chức năng hệ thống","content":"MỤC TIÊU\nHiện thực hóa use case bằng lớp thiết kế và biểu đồ tương tác ba tầng.\n\nKIẾN THỨC\nPresentation nhận thao tác và hiển thị kết quả; Business thực thi quy tắc; Data Access truy cập dữ liệu. Các tầng không thay thế kiểm tra phân quyền. Không để UI gọi thẳng bảng dữ liệu rồi bỏ qua nghiệp vụ.\n\nBÀI TẬP\nPhân công trách nhiệm cho SubmissionPage, SubmissionService, SubmissionRepository và FileStore.\nVẽ sequence diagram UC-NOP với nhánh thành công, quá hạn và trùng bài.\n\nTHỰC HÀNH\nNộp sequence diagram, class diagram thiết kế tối thiểu 4 lớp, phác thảo UI và 6 ca kiểm thử UC-NOP. Chỉ ra FR→use case→service→bảng→test.","seconds":2700,"resources":[{"title":"Phiếu thực hành tiếng Việt","type":"LINK","url":"/course-materials/systems/07.html"},{"title":"Sổ tự học, đề cương và bài tập tham khảo - bản 2026.11","type":"PDF","url":"vedu-file:ce81b905-fb01-8ef2-5451-8a8cda763898.pdf"},{"title":"60. 01200062_Chi tiet_Phan tich thiet ke he thong.pdf","type":"PDF","url":"vedu-file:b7bcd46b-826b-4824-8d16-fdedeb428fc7.pdf"},{"title":"Chuong 1_PTTKHTTT_Tong quan ve HTTT.pdf","type":"PDF","url":"vedu-file:3d5488ae-b74d-28f5-4150-e729b32cc40d.pdf"},{"title":"Chuong 2_PTTKHTTT_Xac dinh yeu cau.pdf","type":"PDF","url":"vedu-file:9810bd4f-fb73-fc46-27ae-e1195ea4bba8.pdf"},{"title":"Chuong 3_PTTKHTTT_Mo hinh hoa nghiep vu.pdf","type":"PDF","url":"vedu-file:9ce71489-8257-5352-58d0-2c7ded1ea084.pdf"},{"title":"Chuong 4_PTTKHTTT_Mo hinh hoa chuc nang.pdf","type":"PDF","url":"vedu-file:b9c9b494-37c2-04ab-947f-4a2a6686ec29.pdf"},{"title":"Chuong 5_PTTKHTTT_Mo hinh hoa cau truc.pdf","type":"PDF","url":"vedu-file:6f8641cb-a775-7074-15f1-061f2eaea0fc.pdf"},{"title":"Chuong 6_PTTKHTTT_Thiet ke lop du lieu.pdf","type":"PDF","url":"vedu-file:090274d7-1ebd-494b-4065-4b2508633114.pdf"},{"title":"Chuong 7_PTTKHTTT_Thiet ke chuc nang he thong - Copy.pdf","type":"PDF","url":"vedu-file:6f53bf01-b9a9-ba70-bc3b-1a94bc730a3a.pdf"},{"title":"Lucid – Sequence diagram tutorial","type":"LINK","url":"https://lucid.co/diagram/uml/sequence-diagram-tutorial"},{"title":"Kteam – Giới thiệu mô hình 3 lớp","type":"LINK","url":"https://howkteam.vn/course/gioi-thieu-design-patern-singleton-phan-mem-quan-ly-quan-cafe-voi-c-winform/gioi-thieu-mo-hinh-3-lop-3-layers-1233"}]}],"questions":[{"text":"Phân tích LMS nên bắt đầu từ đâu?","options":["Vấn đề, mục tiêu nghiệp vụ và bên liên quan","Chọn màu giao diện trước khi biết yêu cầu","Tạo mọi bảng theo phỏng đoán","Chỉ chọn framework"],"correct":0},{"text":"Đầu ra nào giúp kiểm soát phạm vi?","options":["Danh sách chức năng trong/ngoài phạm vi và giả định cần xác nhận","Chỉ tên dự án","Chỉ ảnh logo","Chỉ số dòng mã"],"correct":0},{"text":"Yêu cầu phi chức năng nào kiểm chứng được?","options":["95% yêu cầu đọc danh sách trả trong 2 giây ở tải thử được quy định","Ứng dụng thật nhanh","Giao diện phải hoàn hảo","Hệ thống không bao giờ có lỗi"],"correct":0},{"text":"Một giả định từ nhóm phát triển nên được xử lý thế nào?","options":["Ghi rõ và xác nhận với bên liên quan","Coi ngay là yêu cầu đã phê duyệt","Bỏ khỏi tài liệu","Dùng thay mọi cuộc phỏng vấn"],"correct":0},{"text":"Swimlane trong activity diagram thể hiện gì?","options":["Trách nhiệm của từng bên tham gia","Màu của cơ sở dữ liệu","Số lượng máy chủ","Kiểu dữ liệu của thuộc tính"],"correct":0},{"text":"Theo tình huống khóa học, sinh viên gửi bài quá hạn cần nhánh nào?","options":["Từ chối nộp dựa trên thời gian máy chủ","Chấp nhận nếu đồng hồ máy sinh viên còn sớm","Tự động gia hạn cho mọi người","Bỏ kiểm tra ghi danh"],"correct":0},{"text":"Use case nên mô tả điều gì?","options":["Mục tiêu có giá trị của actor qua tương tác với hệ thống","Mỗi nút CSS là một use case bắt buộc","Chỉ các bảng dữ liệu","Mỗi câu lệnh SQL"],"correct":0},{"text":"Phát biểu nào đúng về đăng nhập trong đặc tả use case?","options":["Có thể là tiền điều kiện, không bắt buộc include vào mọi use case","Luôn bắt buộc extend từ mọi use case","Không bao giờ là tiền điều kiện","Tự động bảo đảm mọi quyền sở hữu"],"correct":0},{"text":"Enrollment thường dùng để làm gì trong mô hình LMS?","options":["Biểu diễn ghi danh liên kết sinh viên và lớp học phần","Thay thế mọi bài tập","Lưu CSS của màn hình","Là lớp con của mọi sinh viên"],"correct":0},{"text":"Lớp nào phù hợp mô hình miền hơn?","options":["Submission mô tả bài nộp","MauNutBam","TrangCSS","KetNoiTrinhDuyet"],"correct":0},{"text":"Liên kết n–n thường được ánh xạ sang mô hình quan hệ bằng gì?","options":["Bảng kết hợp có các khóa ngoại","Một cột chứa chuỗi tùy ý luôn đủ","Xóa một phía liên kết","Chỉ một chỉ mục giao diện"],"correct":0},{"text":"Đảm bảo mỗi sinh viên nộp tối đa một lần cho mỗi bài khi có hai yêu cầu đồng thời cần gì?","options":["Ràng buộc UNIQUE(student_id,assignment_id) và xử lý lỗi trong giao dịch","Chỉ vô hiệu hóa nút bằng JavaScript","Chỉ kiểm tra trước bằng SELECT không có ràng buộc","Chỉ đổi tên tệp"],"correct":0},{"text":"Trách nhiệm kiểm tra ghi danh, hạn nộp và quyền sở hữu thuộc đâu?","options":["Phía máy chủ trong nghiệp vụ cùng ràng buộc dữ liệu phù hợp","Chỉ CSS","Chỉ thông báo trên giao diện","Chỉ mô tả trong báo cáo"],"correct":0},{"text":"Chuỗi truy vết hợp lý là gì?","options":["FR → use case → service → bảng dữ liệu → ca kiểm thử","Logo → màu → ảnh nền","Chỉ service → tên biến","Chỉ sơ đồ → trang bìa"],"correct":0}]},{"key":"discrete","name":"Cấu trúc rời rạc","topic":"Toán học & Tin học","marker":"[VEDU-COMPUTING-v1:discrete]","summary":"14 bài nền tảng về đồ thị, logic, phép đếm và quan hệ. Tóm tắt, slide HTML và bài tập gốc VEDU; liên kết học liệu theo bộ nguồn nhóm cung cấp.\nKhóa tự học do VEDU biên soạn bổ trợ, không phải khóa/chứng chỉ chính thức của đơn vị nguồn.","preparation":"Kiến thức nền tảng theo hướng dẫn đầu khóa.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU — Cấu trúc rời rạc\n\nMục tiêu: 14 bài nền tảng về đồ thị, logic, phép đếm và quan hệ. Tóm tắt, slide HTML và bài tập gốc VEDU; liên kết học liệu theo bộ nguồn nhóm cung cấp.\n\nChuẩn bị: trình duyệt, sổ ghi chép; kiến thức toán phổ thông, tập hợp và thao tác số học cơ bản.\n\nCách học:\n1. Đọc đề cương và học lần lượt 14 bài theo danh sách.\n2. Trong mỗi bài: đọc tóm tắt → mở slide HTML VEDU → đọc slide/tài liệu gốc ở liên kết nguồn → làm bài tập nhỏ → mở gợi ý sau khi tự làm.\n3. Bấm “Tôi đã đọc tài liệu” để xác nhận tự học. Đây là xác nhận của bạn, không phải bằng chứng hệ thống đã chấm bài thực hành.\n4. Thi cuối khóa mở sau khi hoàn thành các bài; 14 câu gốc VEDU, 840 giây, đạt 7/10, tối đa 5 lượt.\n5. Đạt tất cả quiz → Bảng điều khiển → Chứng chỉ → cấp và tải PDF.\n\nVideo tham khảo: danh mục gốc chỉ cung cấp một playlist chung; chưa xác minh từng video theo bài. Playlist được giữ dưới dạng liên kết tham khảo, không dùng để đo thời gian xem hay làm điều kiện hoàn thành.\n\nĐề cương:\n1. Tổng quan về đồ thị\n2. Biểu diễn đồ thị\n3. Các bài toán về đồ thị (phần 1)\n4. Các bài toán về đồ thị (phần 2)\n5. Bài toán tìm đường đi ngắn nhất\n6. Bài toán tìm cây khung nhỏ nhất\n7. Logic học – Mệnh đề và dạng mệnh đề\n8. Logic học – Các luật suy diễn\n9. Logic học – Vị từ\n10. Phương pháp đếm – Tập hợp – Ánh xạ\n11. Phương pháp đếm – Phép đếm – Giải tích tổ hợp\n12. Phương pháp đếm\n13. Quan hệ (phần 1)\n14. Quan hệ (phần 2)\n\nNguồn và giới hạn: các slide PDF bên ngoài mở tại máy chủ tác giả; có thể cần Internet hoặc bị nguồn thay đổi. Slide HTML/tóm tắt và câu hỏi VEDU là học liệu bổ trợ tự biên soạn, cần giảng viên thẩm định trước khi dùng đánh giá chính thức. Chứng nhận VEDU không thay thế văn bằng/chứng chỉ chính thức.","seconds":240,"resources":[{"title":"Hướng dẫn & đề cương — VEDU","type":"LINK","url":"/course-materials/discrete/00.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"},{"title":"Playlist từ danh mục gốc — chưa đối chiếu video từng bài","type":"LINK","url":"https://www.youtube.com/watch?v=JCDs2_1TLnc&list=PLf5IPckgFwFUcvOrXAO9DD9OstQwSf0zM"}]},{"title":"01 · Tổng quan về đồ thị","content":"MỤC TIÊU\nHiểu và vận dụng tổng quan về đồ thị qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nĐồ thị vô hướng G=(V,E) mô tả các đối tượng và liên kết hai chiều. Bậc của đỉnh là số cạnh kề; tổng bậc bằng hai lần số cạnh. Phân biệt đồ thị đơn, đa đồ thị và đồ thị có hướng trước khi áp dụng định lý.\n\nVÍ DỤ\nTam giác có ba đỉnh, ba cạnh. Mỗi đỉnh bậc 2; tổng bậc 6 = 2×3.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nVẽ đồ thị có V={A,B,C,D}, E={AB,AC,BC,CD}. Tính bậc từng đỉnh và kiểm tra định lý bắt tay.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nĐồ thị vô hướng đơn có 5 cạnh. Tổng bậc của các đỉnh bằng bao nhiêu?\nA. 10\nB. 5\nC. 20\nD. Không xác định\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/01.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"02 · Biểu diễn đồ thị","content":"MỤC TIÊU\nHiểu và vận dụng biểu diễn đồ thị qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nMa trận kề lưu quan hệ cạnh giữa mọi cặp đỉnh. Danh sách kề chỉ lưu láng giềng hiện có. Với đồ thị đơn vô hướng, ma trận đối xứng và đường chéo bằng 0; danh sách kề thường tiết kiệm hơn khi đồ thị thưa.\n\nVÍ DỤ\nĐường A–B–C có các danh sách A:[B], B:[A,C], C:[B].\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nLập ma trận kề và danh sách kề cho bốn đỉnh với các cạnh AB,AC,CD. So sánh bộ nhớ khi có n đỉnh, m cạnh.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nĐặc điểm nào đúng với ma trận kề của đồ thị đơn vô hướng?\nA. Đối xứng qua đường chéo chính\nB. Mọi phần tử đều bằng 1\nC. Luôn có kích thước m×m\nD. Chỉ lưu trọng số âm\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/02.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"03 · Các bài toán về đồ thị (phần 1)","content":"MỤC TIÊU\nHiểu và vận dụng các bài toán về đồ thị (phần 1) qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nMột đường đi nối dãy đỉnh qua các cạnh. Đồ thị liên thông nếu mọi cặp đỉnh đều có đường đi. BFS dùng hàng đợi, xét theo lớp; DFS đi sâu và quay lui. BFS tìm đường ít cạnh nhất trong đồ thị không trọng số.\n\nVÍ DỤ\nBFS từ A, với A kề B,C và B kề D, có các lớp {A},{B,C},{D}.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nChạy BFS từ A trên E={AB,AC,BD,CD,DE}; ghi hàng đợi sau mỗi lượt. Tìm khoảng cách A đến E.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nCấu trúc dữ liệu cơ bản nào dùng trong BFS?\nA. Hàng đợi\nB. Ngăn xếp duy nhất\nC. Cây cân bằng bắt buộc\nD. Bảng định tuyến\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/03.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"04 · Các bài toán về đồ thị (phần 2)","content":"MỤC TIÊU\nHiểu và vận dụng các bài toán về đồ thị (phần 2) qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nĐường Euler đi qua mỗi cạnh đúng một lần; đường Hamilton đi qua mỗi đỉnh đúng một lần. Với đồ thị vô hướng liên thông có cạnh, chu trình Euler tồn tại khi mọi đỉnh đều có bậc chẵn. Sắp xếp topo chỉ áp dụng cho đồ thị có hướng không chu trình.\n\nVÍ DỤ\nTam giác có chu trình Euler; đường gồm ba đỉnh nối liên tiếp có đúng hai đỉnh bậc lẻ nên có đường Euler mở.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nCho chu trình A–B–C–D–A và cạnh AC. Có chu trình Euler không? Có đường Euler mở không? Giải thích.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nĐiều kiện cần để một đồ thị có sắp xếp topo là gì?\nA. Có hướng và không có chu trình\nB. Vô hướng và đầy đủ\nC. Có mọi đỉnh bậc chẵn\nD. Có cạnh trọng số âm\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/04.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"05 · Bài toán tìm đường đi ngắn nhất","content":"MỤC TIÊU\nHiểu và vận dụng bài toán tìm đường đi ngắn nhất qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nBài toán tối thiểu hóa tổng trọng số cạnh trên đường đi. Dijkstra chốt đỉnh có khoảng cách tạm thời nhỏ nhất và yêu cầu trọng số không âm. Với cạnh âm, cân nhắc Bellman–Ford và kiểm tra chu trình âm có thể đi tới.\n\nVÍ DỤ\nA→B trọng số 2, B→C trọng số 3, A→C trọng số 9: khoảng cách ngắn nhất A→C là 5.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nThêm B→D=4, C→D=1. Tính khoảng cách ngắn nhất từ A đến từng đỉnh, ghi bước cập nhật.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nThuật toán Dijkstra chuẩn yêu cầu điều kiện nào?\nA. Tất cả trọng số cạnh không âm\nB. Tất cả cạnh đều âm\nC. Đồ thị luôn là cây\nD. Mọi đỉnh bậc 2\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/05.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"06 · Bài toán tìm cây khung nhỏ nhất","content":"MỤC TIÊU\nHiểu và vận dụng bài toán tìm cây khung nhỏ nhất qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nCây khung nối toàn bộ n đỉnh bằng n−1 cạnh và không có chu trình. Cây khung nhỏ nhất tối thiểu hóa tổng trọng số. Kruskal chọn cạnh từ nhỏ đến lớn nếu không tạo chu trình; Prim mở rộng từ một tập đỉnh đã nối.\n\nVÍ DỤ\nTam giác có trọng số AB=1, BC=2, AC=5: cây khung nhỏ nhất chọn AB,BC, tổng bằng 3.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nTìm MST với AB=1, AC=4, BC=2, BD=5, CD=3. Ghi cạnh được chọn theo Kruskal.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nCây khung của đồ thị liên thông có n đỉnh chứa bao nhiêu cạnh?\nA. n−1\nB. n\nC. n+1\nD. 2n\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/06.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"07 · Logic học – Mệnh đề và dạng mệnh đề","content":"MỤC TIÊU\nHiểu và vận dụng logic học – mệnh đề và dạng mệnh đề qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nMệnh đề có giá trị đúng hoặc sai xác định. Phủ định ¬p đảo giá trị; hội p∧q chỉ đúng khi cả hai đúng; tuyển p∨q đúng nếu có ít nhất một đúng. Kéo theo p→q chỉ sai khi p đúng và q sai.\n\nVÍ DỤ\nNếu p đúng, q sai thì p∧q sai, p∨q đúng và p→q sai.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nLập bảng chân trị bốn dòng cho (p→q) và (¬p∨q). Kiểm tra chúng có tương đương không.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nKhi nào p→q sai?\nA. p đúng và q sai\nB. p sai và q đúng\nC. p sai và q sai\nD. p đúng và q đúng\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/07.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"08 · Logic học – Các luật suy diễn","content":"MỤC TIÊU\nHiểu và vận dụng logic học – các luật suy diễn qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nSuy diễn hợp lệ bảo toàn tính đúng từ tiền đề tới kết luận. Modus ponens: p và p→q suy ra q. Modus tollens: ¬q và p→q suy ra ¬p. Không được đảo chiều kéo theo nếu chưa có điều kiện tương đương.\n\nVÍ DỤ\nNếu hoàn thành bài thì được dự thi. Lan hoàn thành bài. Suy ra Lan được dự thi; không suy ngược từ được dự thi ra đã hoàn thành bài chỉ từ một tiền đề.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nCho p→q, q→r, p. Viết chuỗi suy diễn r; chỉ rõ quy tắc ở từng bước.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nTừ p→q và ¬q, kết luận hợp lệ nào?\nA. ¬p\nB. p\nC. q\nD. p∧q\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/08.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"09 · Logic học – Vị từ","content":"MỤC TIÊU\nHiểu và vận dụng logic học – vị từ qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nVị từ P(x) phụ thuộc biến và miền xác định. ∀x P(x) yêu cầu mọi phần tử thỏa mãn; ∃x P(x) chỉ cần một phần tử. Phủ định đổi lượng từ: ¬∀x P(x) tương đương ∃x ¬P(x).\n\nVÍ DỤ\nTrong miền số nguyên, ∃x(x²=4) đúng; ∀x(x²=4) sai.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nPhủ định câu “Mọi học viên đã làm ít nhất một bài tập”. Viết lượng từ với P(x,y): x đã làm bài y.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nPhủ định của ∃x P(x) là gì?\nA. ∀x ¬P(x)\nB. ∃x ¬P(x)\nC. ∀x P(x)\nD. P(x)∧¬P(x)\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/09.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"10 · Phương pháp đếm – Tập hợp – Ánh xạ","content":"MỤC TIÊU\nHiểu và vận dụng phương pháp đếm – tập hợp – ánh xạ qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nTập hợp gồm các phần tử không lặp. Ánh xạ f:A→B gán mỗi phần tử A đúng một ảnh trong B. Đơn ánh không gộp hai phần tử nguồn; toàn ánh phủ hết B; song ánh đồng thời đơn ánh và toàn ánh.\n\nVÍ DỤ\nf:{1,2}→{a,b}, f(1)=a, f(2)=b là song ánh.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nVới A={1,2,3}, B={a,b}, xét f(1)=a, f(2)=b, f(3)=a. f có đơn ánh, toàn ánh không?\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nÁnh xạ song ánh đồng thời có hai tính chất nào?\nA. Đơn ánh và toàn ánh\nB. Phản xạ và đối xứng\nC. Liên thông và đầy đủ\nD. Giao hoán và kết hợp\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/10.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"11 · Phương pháp đếm – Phép đếm – Giải tích tổ hợp","content":"MỤC TIÊU\nHiểu và vận dụng phương pháp đếm – phép đếm – giải tích tổ hợp qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nQuy tắc cộng áp dụng các khả năng loại trừ nhau; quy tắc nhân cho lựa chọn theo nhiều bước. Hoán vị xét thứ tự; tổ hợp không xét thứ tự. C(n,k)=n!/(k!(n−k)!) khi chọn k phần tử từ n phần tử phân biệt.\n\nVÍ DỤ\nChọn 2 người từ 5 người có C(5,2)=10 cách; chọn trưởng và phó có 5×4=20 cách.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nCó 6 học viên. Đếm số cách chọn nhóm 3 người và số cách chọn trưởng/phó/thư ký khác nhau.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nChọn 2 người không phân vai từ 4 người có bao nhiêu cách?\nA. 6\nB. 12\nC. 8\nD. 16\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/11.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"12 · Phương pháp đếm","content":"MỤC TIÊU\nHiểu và vận dụng phương pháp đếm qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nNguyên lý bù trừ hai tập: |A∪B|=|A|+|B|−|A∩B|. Nguyên lý Dirichlet: đặt nhiều hơn n đối tượng vào n hộp thì có hộp chứa ít nhất hai đối tượng. Cần mô tả rõ đối tượng, hộp và giả thiết.\n\nVÍ DỤ\nCó 18 người học Word, 15 người học Excel, 7 người học cả hai: có 26 người học ít nhất một trong hai.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nLớp có 31 học viên. Chứng minh ít nhất 3 người sinh cùng tháng, không xét ngày và năm.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\n|A|=8, |B|=7, |A∩B|=3. |A∪B| bằng bao nhiêu?\nA. 12\nB. 15\nC. 18\nD. 4\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/12.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"13 · Quan hệ (phần 1)","content":"MỤC TIÊU\nHiểu và vận dụng quan hệ (phần 1) qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nQuan hệ hai ngôi trên A là tập con của A×A. Phản xạ: mọi (a,a) có trong R. Đối xứng: aRb kéo theo bRa. Phản đối xứng: nếu aRb và bRa thì a=b. Bắc cầu: aRb và bRc kéo theo aRc.\n\nVÍ DỤ\nQuan hệ ≤ trên số nguyên là phản xạ, phản đối xứng, bắc cầu; không đối xứng.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nTrên A={1,2}, R={(1,1),(2,2),(1,2)}. Kiểm tra bốn tính chất trên.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nĐiều nào diễn tả tính phản xạ của R trên A?\nA. Mọi a∈A đều có aRa\nB. aRb luôn kéo theo bRa\nC. aRb và bRa kéo theo a=b\nD. Không có cặp (a,a)\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/13.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]},{"title":"14 · Quan hệ (phần 2)","content":"MỤC TIÊU\nHiểu và vận dụng quan hệ (phần 2) qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nQuan hệ tương đương có tính phản xạ, đối xứng và bắc cầu; các lớp tương đương tạo một phân hoạch. Quan hệ thứ tự bộ phận có phản xạ, phản đối xứng và bắc cầu. Quan hệ chia hết trên các số nguyên dương là một ví dụ thứ tự bộ phận.\n\nVÍ DỤ\nCùng số dư khi chia 3 là tương đương, tạo các lớp [0],[1],[2].\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nChia tập {0,1,2,3,4,5} thành lớp theo quan hệ cùng phần dư khi chia 3.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nQuan hệ tương đương cần những tính chất nào?\nA. Phản xạ, đối xứng, bắc cầu\nB. Phản xạ, phản đối xứng, bắc cầu\nC. Chỉ đối xứng\nD. Chỉ liên thông\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/discrete/14.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://tailieusinhvien.net/bai-giang-toan-roi-rac-pham-the-bao-3967/"}]}],"questions":[{"text":"Đồ thị vô hướng đơn có 5 cạnh. Tổng bậc của các đỉnh bằng bao nhiêu?","options":["10","5","20","Không xác định"],"correct":0},{"text":"Đặc điểm nào đúng với ma trận kề của đồ thị đơn vô hướng?","options":["Chỉ lưu trọng số âm","Đối xứng qua đường chéo chính","Mọi phần tử đều bằng 1","Luôn có kích thước m×m"],"correct":1},{"text":"Cấu trúc dữ liệu cơ bản nào dùng trong BFS?","options":["Cây cân bằng bắt buộc","Bảng định tuyến","Hàng đợi","Ngăn xếp duy nhất"],"correct":2},{"text":"Điều kiện cần để một đồ thị có sắp xếp topo là gì?","options":["Vô hướng và đầy đủ","Có mọi đỉnh bậc chẵn","Có cạnh trọng số âm","Có hướng và không có chu trình"],"correct":3},{"text":"Thuật toán Dijkstra chuẩn yêu cầu điều kiện nào?","options":["Tất cả trọng số cạnh không âm","Tất cả cạnh đều âm","Đồ thị luôn là cây","Mọi đỉnh bậc 2"],"correct":0},{"text":"Cây khung của đồ thị liên thông có n đỉnh chứa bao nhiêu cạnh?","options":["2n","n−1","n","n+1"],"correct":1},{"text":"Khi nào p→q sai?","options":["p sai và q sai","p đúng và q đúng","p đúng và q sai","p sai và q đúng"],"correct":2},{"text":"Từ p→q và ¬q, kết luận hợp lệ nào?","options":["p","q","p∧q","¬p"],"correct":3},{"text":"Phủ định của ∃x P(x) là gì?","options":["∀x ¬P(x)","∃x ¬P(x)","∀x P(x)","P(x)∧¬P(x)"],"correct":0},{"text":"Ánh xạ song ánh đồng thời có hai tính chất nào?","options":["Giao hoán và kết hợp","Đơn ánh và toàn ánh","Phản xạ và đối xứng","Liên thông và đầy đủ"],"correct":1},{"text":"Chọn 2 người không phân vai từ 4 người có bao nhiêu cách?","options":["8","16","6","12"],"correct":2},{"text":"|A|=8, |B|=7, |A∩B|=3. |A∪B| bằng bao nhiêu?","options":["15","18","4","12"],"correct":3},{"text":"Điều nào diễn tả tính phản xạ của R trên A?","options":["Mọi a∈A đều có aRa","aRb luôn kéo theo bRa","aRb và bRa kéo theo a=b","Không có cặp (a,a)"],"correct":0},{"text":"Quan hệ tương đương cần những tính chất nào?","options":["Chỉ liên thông","Phản xạ, đối xứng, bắc cầu","Phản xạ, phản đối xứng, bắc cầu","Chỉ đối xứng"],"correct":1}]},{"key":"networks","name":"Mạng máy tính","topic":"Mạng máy tính","marker":"[VEDU-COMPUTING-v1:networks]","summary":"10 bài từ tổng quan, OSI, địa chỉ IP đến thiết kế mạng nhỏ. Liên kết slide PDF công khai của ITC và bài tập thực hành gốc VEDU; không yêu cầu thiết bị thật.\nKhóa tự học do VEDU biên soạn bổ trợ, không phải khóa/chứng chỉ chính thức của đơn vị nguồn.","preparation":"Kiến thức nền tảng theo hướng dẫn đầu khóa.","lessons":[{"title":"00 · Hướng dẫn bắt đầu & đề cương","content":"HƯỚNG DẪN BẮT ĐẦU — Mạng máy tính\n\nMục tiêu: 10 bài từ tổng quan, OSI, địa chỉ IP đến thiết kế mạng nhỏ. Liên kết slide PDF công khai của ITC và bài tập thực hành gốc VEDU; không yêu cầu thiết bị thật.\n\nChuẩn bị: trình duyệt, sổ ghi chép; máy tính cá nhân để xem cấu hình mạng, tùy chọn phần mềm mô phỏng được cấp phép. Chỉ thực hành trong mạng được phép.\n\nCách học:\n1. Đọc đề cương và học lần lượt 10 bài theo danh sách.\n2. Trong mỗi bài: đọc tóm tắt → mở slide HTML VEDU → đọc slide/tài liệu gốc ở liên kết nguồn → làm bài tập nhỏ → mở gợi ý sau khi tự làm.\n3. Bấm “Tôi đã đọc tài liệu” để xác nhận tự học. Đây là xác nhận của bạn, không phải bằng chứng hệ thống đã chấm bài thực hành.\n4. Thi cuối khóa mở sau khi hoàn thành các bài; 10 câu gốc VEDU, 600 giây, đạt 7/10, tối đa 5 lượt.\n5. Đạt tất cả quiz → Bảng điều khiển → Chứng chỉ → cấp và tải PDF.\n\nVideo: bộ tài liệu chưa có video đã xác minh. Khóa này học bằng bài đọc, slide PDF/HTML và bài tập; không gắn video giả hoặc không tương ứng.\n\nĐề cương:\n1. Tổng quan về mạng máy tính\n2. Mô hình OSI và giao thức truyền thông\n3. Địa chỉ IP\n4. VLSM và Subnetting\n5. Tầng vật lý – Physical\n6. Ethernet và Switching\n7. Tầng mạng và giao thức IP\n8. Tầng vận chuyển – TCP/UDP\n9. Tầng ứng dụng\n10. Xây dựng hệ thống mạng cơ bản\n\nNguồn và giới hạn: các slide PDF bên ngoài mở tại máy chủ tác giả; có thể cần Internet hoặc bị nguồn thay đổi. Slide HTML/tóm tắt và câu hỏi VEDU là học liệu bổ trợ tự biên soạn, cần giảng viên thẩm định trước khi dùng đánh giá chính thức. Chứng nhận VEDU không thay thế văn bằng/chứng chỉ chính thức.","seconds":240,"resources":[{"title":"Hướng dẫn & đề cương — VEDU","type":"LINK","url":"/course-materials/networks/00.html"},{"title":"Nguồn học liệu tham khảo","type":"LINK","url":"https://itc.edu.vn/thong-tin/cong-khai-giao-duc-nghe-nghiep/cong-khai-bai-giang-mon-hoc?pagenumber=3"}]},{"title":"01 · Tổng quan về mạng máy tính","content":"MỤC TIÊU\nHiểu và vận dụng tổng quan về mạng máy tính qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nMạng kết nối thiết bị để trao đổi dữ liệu và chia sẻ tài nguyên. LAN phục vụ một phạm vi cục bộ; WAN kết nối các mạng ở khoảng cách lớn. Switch thường nối thiết bị trong LAN; router chuyển gói giữa các mạng.\n\nVÍ DỤ\nMột văn phòng có 8 laptop kết nối switch và một router ra Internet: switch phục vụ LAN; router là điểm đi ra mạng khác.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nVẽ mạng gia đình gồm hai laptop, một điện thoại, một máy in và router Wi-Fi. Chỉ ra thiết bị đầu cuối, thiết bị trung gian, đường truyền.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nThiết bị nào có chức năng định tuyến giữa các mạng IP?\nA. Router\nB. Bàn phím\nC. Hub thụ động\nD. Máy quét\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/01.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%201_T%E1%BB%95ng%20quan%20v%E1%BB%81%20m%E1%BA%A1ng%20m%C3%A1y%20t%C3%ADnh.pdf"}]},{"title":"02 · Mô hình OSI và giao thức truyền thông","content":"MỤC TIÊU\nHiểu và vận dụng mô hình osi và giao thức truyền thông qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nOSI chia trao đổi dữ liệu thành 7 tầng từ vật lý đến ứng dụng. Đóng gói thêm thông tin điều khiển khi dữ liệu đi xuống; tháo gói theo chiều ngược lại. Mô hình TCP/IP dùng nhóm tầng thực tế; không nhầm mô hình tham chiếu với một giao thức riêng.\n\nVÍ DỤ\nTrình duyệt dùng HTTPS ở tầng ứng dụng; TCP vận chuyển; IP định tuyến; Ethernet truyền trong liên kết cục bộ.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nXếp Ethernet, IP, TCP, HTTP vào tầng OSI tương ứng; giải thích lý do.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nIP chủ yếu hoạt động ở tầng OSI nào?\nA. Tầng mạng (3)\nB. Tầng ứng dụng (7)\nC. Tầng trình diễn (6)\nD. Tầng vật lý (1)\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/02.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%202_M%C3%B4%20h%C3%ACnh%20OSI%20v%C3%A0%20giao%20th%E1%BB%A9c%20truy%E1%BB%81n%20th%C3%B4ng%20tr%C3%AAn%20h%E1%BB%87%20th%E1%BB%91ng%20m%E1%BA%A1ng.pdf"}]},{"title":"03 · Địa chỉ IP","content":"MỤC TIÊU\nHiểu và vận dụng địa chỉ ip qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nIPv4 có 32 bit, biểu diễn bốn octet. Prefix /n cho biết số bit mạng; phần còn lại là bit host. Trong mạng con IPv4 thông thường, địa chỉ mạng và quảng bá không gán host; /31 và /32 có ngữ cảnh sử dụng riêng.\n\nVÍ DỤ\n192.168.10.23/24 thuộc mạng 192.168.10.0, broadcast 192.168.10.255.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nXác định network, broadcast, dải host của 192.168.1.70/26.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nSubnet mask tương ứng /24 là gì?\nA. 255.255.255.0\nB. 255.0.255.0\nC. 255.255.0.0\nD. 0.0.0.255\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/03.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%203_%C4%90%E1%BB%8Ba%20ch%E1%BB%89%20IP.pdf"}]},{"title":"04 · VLSM và Subnetting","content":"MỤC TIÊU\nHiểu và vận dụng vlsm và subnetting qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nSubnetting chia một mạng thành các mạng con. VLSM dùng prefix khác nhau theo nhu cầu host. Phân bổ nhu cầu lớn trước, căn chỉnh ranh giới khối và kiểm tra các dải không chồng lấn. Công thức host thông thường: 2^(32−prefix)−2.\n\nVÍ DỤ\nMạng cần 50 host dùng /26 (62 host); mạng cần 20 host dùng /27 (30 host).\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nChia 192.168.20.0/24 cho 60,30,12 host. Nêu một phương án không chồng lấn.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nMạng IPv4 /27 thông thường có tối đa bao nhiêu địa chỉ host sử dụng được?\nA. 30\nB. 32\nC. 27\nD. 62\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/04.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%204_VLSM%20-%20Subnetting.pdf"}]},{"title":"05 · Tầng vật lý – Physical","content":"MỤC TIÊU\nHiểu và vận dụng tầng vật lý – physical qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nTầng vật lý truyền bit qua môi trường hữu tuyến hoặc vô tuyến. Cáp đồng, cáp quang và Wi-Fi khác nhau về khoảng cách, nhiễu, chi phí và tốc độ hỗ trợ. Không đồng nhất băng thông danh định với tốc độ truyền thực tế.\n\nVÍ DỤ\nCáp quang phù hợp kết nối tòa nhà xa và ít bị nhiễu điện từ; Wi-Fi thuận tiện cho thiết bị di động.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nĐề xuất môi trường truyền cho hai phòng cách nhau 20 m và hai tòa nhà cách nhau 500 m. Nêu lý do và điều kiện cần kiểm tra.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nMôi trường nào truyền dữ liệu bằng ánh sáng?\nA. Cáp quang\nB. Cáp xoắn đôi đồng\nC. Cáp đồng trục\nD. Sóng âm\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/05.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%205_Gi%E1%BB%9Bi%20thi%E1%BB%87u%20t%E1%BA%A7ng%20Physical.pdf"}]},{"title":"06 · Ethernet và Switching","content":"MỤC TIÊU\nHiểu và vận dụng ethernet và switching qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nEthernet dùng địa chỉ MAC ở liên kết dữ liệu. Switch học MAC nguồn theo cổng, dùng bảng MAC để chuyển frame. Broadcast được phát trong miền broadcast; VLAN tách mạng logic. Không dùng bảng MAC thay bảng định tuyến IP.\n\nVÍ DỤ\nSwitch nhận frame từ MAC A ở cổng 1 sẽ ghi A→1; nếu MAC đích chưa biết, thường flood trong VLAN đó, trừ cổng vào.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nGiải thích quá trình switch học MAC của hai máy lần đầu liên lạc; phân biệt unicast, broadcast.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nSwitch Ethernet học bảng MAC từ thông tin nào của frame đến?\nA. Địa chỉ MAC nguồn\nB. Mật khẩu Wi-Fi\nC. Địa chỉ DNS\nD. Số thứ tự HTTP\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/06.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%206_T%E1%BA%A7ng%20Datalink%20-%20Ethernet%20-%20Switching.pdf"}]},{"title":"07 · Tầng mạng và giao thức IP","content":"MỤC TIÊU\nHiểu và vận dụng tầng mạng và giao thức ip qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nIP chuyển gói giữa các mạng theo địa chỉ đích. Router dùng bảng định tuyến, ưu tiên prefix khớp dài nhất. Default route dùng khi không có tuyến cụ thể hơn. TTL IPv4 giảm qua mỗi router để hạn chế vòng lặp.\n\nVÍ DỤ\nGiữa tuyến 10.0.0.0/8 và 10.1.0.0/16, gói tới 10.1.2.3 chọn /16 vì cụ thể hơn.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nCho các tuyến 0.0.0.0/0, 192.168.0.0/16, 192.168.10.0/24. Chọn tuyến cho 192.168.10.50 và 8.8.8.8.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nRouter chọn tuyến theo nguyên tắc nào khi nhiều prefix cùng khớp?\nA. Prefix khớp dài nhất\nB. Prefix ngắn nhất\nC. Luôn chọn default\nD. Chọn tuyến thêm sau cùng\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/07.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%207_T%E1%BA%A7ng%20Network%20v%C3%A0%20IP.pdf"}]},{"title":"08 · Tầng vận chuyển – TCP/UDP","content":"MỤC TIÊU\nHiểu và vận dụng tầng vận chuyển – tcp/udp qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nTCP cung cấp luồng byte có thứ tự và cơ chế truyền lại; UDP gửi datagram không tự đảm bảo thứ tự hay truyền lại. Port giúp phân biệt ứng dụng. Chọn giao thức theo nhu cầu độ trễ, độ tin cậy; mã hóa không tự có chỉ vì dùng TCP.\n\nVÍ DỤ\nTải tệp thường cần giao thức đáng tin cậy; thoại thời gian thực có thể ưu tiên độ trễ và xử lý mất gói ở ứng dụng.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nSo sánh TCP/UDP theo kết nối, thứ tự, truyền lại; cho một trường hợp phù hợp với từng loại.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nĐặc tính nào TCP cung cấp mà UDP cơ bản không tự cung cấp?\nA. Giao dữ liệu có thứ tự và truyền lại\nB. Mã hóa bắt buộc\nC. Không dùng port\nD. Không cần IP\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/08.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%208_Transport%20-%20Layer.pdf"}]},{"title":"09 · Tầng ứng dụng","content":"MỤC TIÊU\nHiểu và vận dụng tầng ứng dụng qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nGiao thức ứng dụng cung cấp dịch vụ như HTTP, DNS, DHCP. DNS phân giải tên và có nhiều loại bản ghi; DHCP cấp cấu hình IP động. HTTPS là HTTP qua TLS để bảo vệ trao đổi; cần kiểm tra chứng thư, không bỏ qua cảnh báo bảo mật.\n\nVÍ DỤ\nMở một website: máy có cấu hình IP, hỏi DNS để tìm địa chỉ, rồi thiết lập kết nối tới máy chủ web.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nPhân biệt lỗi mất kết nối IP và lỗi DNS bằng ping địa chỉ đã biết và nslookup một tên miền công khai trên máy của bạn. Không quét hệ thống ngoài phạm vi cho phép.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nDịch vụ nào thường phân giải tên miền thành địa chỉ IP?\nA. DNS\nB. DHCP\nC. Ethernet\nD. NAT\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/09.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%209_T%E1%BA%A7ng%20Application.pdf"}]},{"title":"10 · Xây dựng hệ thống mạng cơ bản","content":"MỤC TIÊU\nHiểu và vận dụng xây dựng hệ thống mạng cơ bản qua một ví dụ và bài tập nhỏ.\n\nKIẾN THỨC CỐT LÕI\nThiết kế mạng bắt đầu từ nhu cầu, số lượng thiết bị, sơ đồ vật lý và kế hoạch địa chỉ. Cấu hình, kiểm thử từng lớp và lưu tài liệu. Chỉ thực hành trên máy/mạng được phép; không chia sẻ mật khẩu, địa chỉ công khai hay cấu hình chứa bí mật.\n\nVÍ DỤ\nMạng nhỏ: 6 máy, switch, router, subnet /28; đặt gateway, DNS và kiểm tra truy cập tài nguyên nội bộ.\n\nBÀI TẬP NHỎ — tự thực hiện trước khi xem gợi ý\nThiết kế mạng cho 2 phòng, mỗi phòng 10 máy. Chọn subnet, gateway và sơ đồ kết nối; lập checklist kiểm tra và tệp ghi kết quả.\n\nMở slide bên dưới để xem gợi ý/đáp án tự đối chiếu. Nếu chưa hiểu, gửi câu hỏi trong Hỏi đáp khóa học; giảng viên có thể hướng dẫn thêm.\n\nTỰ KIỂM TRA\nBước nào nên làm trước khi mua và cấu hình thiết bị?\nA. Khảo sát nhu cầu và thiết kế sơ đồ, địa chỉ\nB. Tắt mọi tính năng bảo mật\nC. Đặt mọi máy cùng IP\nD. Xóa cấu hình không sao lưu\n\nTóm tắt và bài tập gốc VEDU, không trích nguyên ngân hàng câu hỏi của bên thứ ba. Thời gian đọc chỉ là dự kiến, không phải thời lượng video.","seconds":900,"resources":[{"title":"Slide HTML & bài tập — VEDU tự biên soạn","type":"LINK","url":"/course-materials/networks/10.html"},{"title":"Slide PDF gốc — ITC (cần Internet)","type":"PDF","url":"https://itc.edu.vn/Data/Sites/1/media/thongbao/2026/Dao%20tao/Kiemdinh/Baigiang/co_ly/B%C3%A0i%2010_X%C3%A2y%20d%E1%BB%B1ng%20h%E1%BB%87%20th%E1%BB%91ng%20m%E1%BA%A1ng%20c%C6%A1%20b%E1%BA%A3n.pdf"}]}],"questions":[{"text":"Thiết bị nào có chức năng định tuyến giữa các mạng IP?","options":["Router","Bàn phím","Hub thụ động","Máy quét"],"correct":0},{"text":"IP chủ yếu hoạt động ở tầng OSI nào?","options":["Tầng vật lý (1)","Tầng mạng (3)","Tầng ứng dụng (7)","Tầng trình diễn (6)"],"correct":1},{"text":"Subnet mask tương ứng /24 là gì?","options":["255.255.0.0","0.0.0.255","255.255.255.0","255.0.255.0"],"correct":2},{"text":"Mạng IPv4 /27 thông thường có tối đa bao nhiêu địa chỉ host sử dụng được?","options":["32","27","62","30"],"correct":3},{"text":"Môi trường nào truyền dữ liệu bằng ánh sáng?","options":["Cáp quang","Cáp xoắn đôi đồng","Cáp đồng trục","Sóng âm"],"correct":0},{"text":"Switch Ethernet học bảng MAC từ thông tin nào của frame đến?","options":["Số thứ tự HTTP","Địa chỉ MAC nguồn","Mật khẩu Wi-Fi","Địa chỉ DNS"],"correct":1},{"text":"Router chọn tuyến theo nguyên tắc nào khi nhiều prefix cùng khớp?","options":["Luôn chọn default","Chọn tuyến thêm sau cùng","Prefix khớp dài nhất","Prefix ngắn nhất"],"correct":2},{"text":"Đặc tính nào TCP cung cấp mà UDP cơ bản không tự cung cấp?","options":["Mã hóa bắt buộc","Không dùng port","Không cần IP","Giao dữ liệu có thứ tự và truyền lại"],"correct":3},{"text":"Dịch vụ nào thường phân giải tên miền thành địa chỉ IP?","options":["DNS","DHCP","Ethernet","NAT"],"correct":0},{"text":"Bước nào nên làm trước khi mua và cấu hình thiết bị?","options":["Xóa cấu hình không sao lưu","Khảo sát nhu cầu và thiết kế sơ đồ, địa chỉ","Tắt mọi tính năng bảo mật","Đặt mọi máy cùng IP"],"correct":1}]}]'::jsonb) LOOP
 idx=idx+1; tid=teacherids[1+((idx-1)%4)];
 SELECT course_id,teacher_id INTO cid,prev FROM lms.courses WHERE description LIKE (c->>'marker')||'%' ORDER BY course_id LIMIT 1;
 IF cid IS NULL THEN
  INSERT INTO lms.courses(course_name,description,teacher_id,price,status,topic) VALUES(c->>'name',(c->>'marker')||E'
'||(c->>'summary'),tid,0,'DRAFT',c->>'topic') RETURNING course_id INTO cid;
 END IF;
 UPDATE lms.courses SET course_name=c->>'name',description=(c->>'marker')||E'
'||(c->>'summary'),topic=c->>'topic',status='PUBLISHED',is_deleted=false,deleted_at=NULL,review_status='APPROVED',review_note='Học liệu gốc theo gói nhóm cung cấp; nội dung bổ sung chưa thẩm định độc lập. Chứng nhận hoàn thành VEDU.' WHERE course_id=cid;
 INSERT INTO lms.course_teachers(course_id,teacher_id,assigned_by) VALUES(cid,tid,adminid) ON CONFLICT DO NOTHING;
 INSERT INTO auth.notifications(user_id,title,body,route) VALUES(tid,'Khóa học được phân công',(c->>'name')||' — Tài khoản giảng viên kiểm thử hư cấu.','/teacher/content');
 INSERT INTO lms.curated_courses VALUES(c->>'key',cid,'2026.11') ON CONFLICT(course_key) DO UPDATE SET course_id=EXCLUDED.course_id,revision=EXCLUDED.revision;
 selected=array_append(selected,cid);
 SELECT section_id INTO sid FROM lms.course_sections WHERE course_id=cid ORDER BY section_order LIMIT 1;
 IF sid IS NULL THEN INSERT INTO lms.course_sections(course_id,title,section_order) VALUES(cid,'Hướng dẫn, bài học và thực hành',1) RETURNING section_id INTO sid; END IF;
 UPDATE lms.lessons SET lesson_order=lesson_order+10000 WHERE course_id=cid;
 pos=0;used='{}';
 FOR l IN SELECT value FROM jsonb_array_elements(c->'lessons') LOOP
  pos=pos+1;
  SELECT x.lesson_id INTO lid FROM lms.lessons x LEFT JOIN lms.lesson_pedagogy p USING(lesson_id) WHERE x.course_id=cid AND NOT x.is_deleted AND (p.content_key='curated-202611.'||(c->>'key')||'.'||pos OR regexp_replace(x.title,'^[0-9]+[[:space:]]*[·.-][[:space:]]*','')=regexp_replace(l->>'title','^[0-9]+[[:space:]]*[·.-][[:space:]]*','')) AND NOT(x.lesson_id=ANY(used)) ORDER BY x.lesson_id LIMIT 1;
  IF lid IS NULL THEN INSERT INTO lms.lessons(course_id,title,lesson_order) VALUES(cid,l->>'title',pos) RETURNING lesson_id INTO lid; END IF;
  UPDATE lms.lessons SET title=l->>'title',content=l->>'content',lesson_order=pos,estimated_duration_seconds=(l->>'seconds')::int,is_published=true,is_deleted=false,deleted_at=NULL,section_id=sid WHERE lesson_id=lid;
  used=array_append(used,lid);
  INSERT INTO lms.lesson_pedagogy(lesson_id,difficulty,kind,is_core,skills,goals,prerequisites,outcomes,sources,content_key)
  VALUES(lid,CASE WHEN pos>5 THEN 2 ELSE 1 END,CASE WHEN pos=1 THEN 'REVIEW' WHEN c->>'key' LIKE '%-lab' OR l->>'title' ~* 'Thực hành|Dự án' THEN 'PRACTICE' ELSE 'CONCEPT' END,pos<=3,jsonb_build_array(c->>'key'),'["FOUNDATION","PRACTICAL","CERTIFICATION"]'::jsonb,CASE WHEN pos=1 THEN '[]'::jsonb ELSE jsonb_build_array(used[pos-1]) END,jsonb_build_array(l->>'title'),'[]'::jsonb,'curated-202611.'||(c->>'key')||'.'||pos)
  ON CONFLICT(lesson_id) DO UPDATE SET kind=EXCLUDED.kind,is_core=EXCLUDED.is_core,skills=EXCLUDED.skills,goals=EXCLUDED.goals,prerequisites=EXCLUDED.prerequisites,outcomes=EXCLUDED.outcomes,content_key=EXCLUDED.content_key;
  DELETE FROM lms.lesson_resources WHERE lesson_id=lid;
  n=0;FOR r IN SELECT value FROM jsonb_array_elements(l->'resources') LOOP
   n=n+1;INSERT INTO lms.lesson_resources(lesson_id,resource_type,title,resource_url,display_order) VALUES(lid,r->>'type',left(r->>'title',220),r->>'url',n) RETURNING resource_id INTO rid;
  END LOOP;
 END LOOP;
 UPDATE lms.lessons SET is_published=false WHERE course_id=cid AND NOT(lesson_id=ANY(used));
 SELECT resource_id INTO rid FROM lms.lesson_resources WHERE lesson_id=used[1] AND resource_type='PDF' ORDER BY display_order LIMIT 1;
 INSERT INTO lms.course_overviews(course_id,audience,preparation,outcomes,practice_note,syllabus_resource_id)
 VALUES(cid,'Học viên tự học theo hướng dẫn và yêu cầu đầu khóa.',c->>'preparation',(SELECT jsonb_agg(value->>'title') FROM jsonb_array_elements(c->'lessons')),'Hoàn thành bài học và đạt quiz từ 7/10. Bài thực hành/tự luận dùng luyện tập, chưa tự chấm sản phẩm; chứng nhận hoàn thành VEDU không thay chứng chỉ chính thức.',rid)
 ON CONFLICT(course_id) DO UPDATE SET preparation=EXCLUDED.preparation,outcomes=EXCLUDED.outcomes,practice_note=EXCLUDED.practice_note,syllabus_resource_id=EXCLUDED.syllabus_resource_id;
 UPDATE assessment.quizzes SET is_published=false WHERE course_id=cid;
 INSERT INTO assessment.quizzes(course_id,title,description,time_limit_seconds,passing_score,max_attempts,is_published)
 VALUES(cid,'Thi cuối khóa — '||(c->>'name'),'Bài kiểm tra kiến thức VEDU 2026.11, không phải đề thi của trường. Bài thực hành đánh giá theo rubric riêng.',GREATEST(1200,jsonb_array_length(c->'questions')*60),7,3,true) RETURNING quiz_id INTO qid;
 n=0;FOR q IN SELECT value FROM jsonb_array_elements(c->'questions') LOOP
  n=n+1;INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points) VALUES(qid,q->>'text','SINGLE_CHOICE',n,1) RETURNING question_id INTO lid;
  ai=0;rotation=(n-1)%jsonb_array_length(q->'options');FOR a IN SELECT value FROM jsonb_array_elements(q->'options') LOOP
   INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order) VALUES(lid,a#>>'{}',ai=(q->>'correct')::int,1+((ai+rotation)%jsonb_array_length(q->'options')));ai=ai+1;
  END LOOP;
 END LOOP;
END LOOP;
INSERT INTO lms.catalog_retirements(course_id,previous_teacher_id,previous_status) SELECT course_id,teacher_id,status FROM lms.courses WHERE NOT(course_id=ANY(selected)) AND NOT is_deleted ON CONFLICT DO NOTHING;
UPDATE lms.courses c SET status='ARCHIVED',is_deleted=true,deleted_at=now(),teacher_id=CASE WHEN EXISTS(SELECT 1 FROM auth.users u WHERE u.user_id=c.teacher_id AND u.role='TEACHER' AND u.is_active) THEN c.teacher_id ELSE teacherids[1] END WHERE NOT(course_id=ANY(selected)) AND NOT is_deleted;
IF cardinality(selected)<>21 THEN RAISE EXCEPTION 'Catalog must contain 21 courses'; END IF;
-- VEDU demo commercial policy: keep the public catalog free except for one
-- advanced course used to verify checkout, payment reconciliation and access
-- locking. Apply this on every team seed so all developer databases agree.
UPDATE lms.courses c
SET price=CASE WHEN cc.course_key='data-mining' THEN 199000 ELSE 0 END
FROM lms.curated_courses cc
WHERE cc.course_id=c.course_id AND c.course_id=ANY(selected);
INSERT INTO lms.catalog_revisions(revision) VALUES('2026.11.2');
END $curated$;
COMMIT;
